window.__Q=window.__Q||{};window.__Q["tcm/5/A1"]=[{"q":"关于乳突小房叙述，下列错误的是","o":["位于颞骨乳突内","内衬黏膜","与鼓室的黏膜不连续","与乳突窦的黏膜相连续","中耳炎症可引起乳突小房炎症"],"a":2,"e":"乳突小房内覆黏膜，与乳突窦和鼓室的黏膜相连续，故“与鼓室的黏膜不连续”错误。乳突小房位于颞骨乳突部内，中耳炎可经乳突窦侵入乳突小房引起乳突炎。"},{"q":"循环系统的组成是","o":["心、血管、淋巴结","心、动脉、静脉、毛细血管","心、动脉、静脉、淋巴管","心血管系统和淋巴系统","心血管系统和免疫系统"],"a":3,"e":"脉管系统即循环系统，包括心血管系统和淋巴系统。心血管系统由心、动脉、毛细血管和静脉组成，淋巴系统包括淋巴管道、淋巴器官和淋巴组织。"},{"q":"开口高于窦底的鼻旁窦是","o":["额窦","蝶窦","筛窦的前、中小房","筛窦的后小房","上颌窦"],"a":4,"e":"上颌窦开口于中鼻道半月裂孔，开口位置高于窦底，分泌物不易排出。其余鼻旁窦的开口均低于窦底，利于引流。"},{"q":"属于后丘脑的结构是","o":["上丘","下丘","外侧膝状体","锥体","腹后核"],"a":2,"e":"后丘脑包括内侧膝状体和外侧膝状体，属特异性中继核。上丘、下丘属中脑顶盖，腹后核属背侧丘脑。"},{"q":"下列在体表不能摸到的结构是","o":["肩胛下窝","桡骨茎突","肱骨内上髁","桡骨头","尺骨鹰嘴"],"a":0,"e":"肩胛下窝为肩胛骨肋面的凹陷，被肩胛骨体及肩胛下肌覆盖，体表不能触及。桡骨茎突、肱骨内上髁、桡骨头和尺骨鹰嘴均可在体表摸到。"},{"q":"关于腹主动脉描述错误的是","o":["在主动脉裂孔处与胸主动脉相续","终于第4腰椎下缘平面","分支中有壁支和脏支两种","脏支较多，有成对脏支和单个脏支","分支中壁支全部成对"],"a":4,"e":"腹主动脉壁支中腰动脉为4对，但骶正中动脉为1支，故壁支并非全部成对。腹主动脉在主动脉裂孔续于胸主动脉，平第4腰椎下缘分为两髂总动脉，分支分壁支和脏支。"},{"q":"躯体感觉中枢位于","o":["中央后回和中央旁小叶后部","中央前回和中央旁小叶前部","颞横回","额下回后部","角回"],"a":0,"e":"第Ⅰ躯体感觉区位于中央后回和中央旁小叶后部，接受背侧丘脑腹后核传来的对侧半身感觉。中央前回和中央旁小叶前部为躯体运动区。"},{"q":"下列骨连结中属于直接连结的是","o":["椎间盘","肩关节","肘关节","髋关节","膝关节"],"a":0,"e":"椎间盘是连结相邻椎体的纤维软骨盘，属直接连结。肩、肘、髋、膝关节均为滑膜关节，属间接连结。"},{"q":"关于咽，下列说法正确的是","o":["向下在第6颈椎下缘处续于气管","是上窄下宽的肌性管道","分为鼻咽、口咽和喉咽","后壁与咽鼓管圆枕之间有咽鼓管咽口","下鼻甲后方约1cm处有咽隐窝"],"a":2,"e":"咽以腭帆游离缘和会厌上缘平面为界分为鼻咽、口咽和喉咽三部分。咽向下在第6颈椎下缘续于食管而非气管，咽鼓管咽口位于鼻咽侧壁而非后壁。"},{"q":"损伤哪种脑神经后不能闭眼","o":["动眼神经","展神经","滑车神经","面神经","三叉神经"],"a":3,"e":"面神经的特殊内脏运动纤维支配面部表情肌，其中眼轮匝肌瘫痪导致闭眼困难、角膜反射消失。动眼神经支配上睑提肌等眼外肌，不支配眼轮匝肌。"},{"q":"关于腭扁桃体的描述，正确的是","o":["位于腭舌弓与腭咽弓之间","在鼻咽部的侧壁内","在舌根部的黏膜内","位于扁桃体上窝内","在喉咽部的侧壁内"],"a":0,"e":"腭舌弓与腭咽弓之间的三角形凹陷为扁桃体窝，窝内容纳腭扁桃体。咽隐窝位于鼻咽侧壁，舌扁桃体位于舌根部黏膜内。"},{"q":"瞳孔位于","o":["虹膜的中央","角膜的边缘","脉络膜中央","视网膜中央","巩膜的中央"],"a":0,"e":"虹膜呈圆盘形，中央有圆形的瞳孔，为光线进入眼球的通道。角膜位于眼球前部，脉络膜和视网膜均位于眼球后部。"},{"q":"有关直肠横襞的叙述，正确的是","o":["主要构成齿状线","是会阴曲和骶曲的分界线","位于直肠的右前壁","内有括约肌","是由环行肌和黏膜形成的半月状皱襞"],"a":4,"e":"直肠横襞由黏膜及环行肌构成，呈半月状皱襞，具有阻挡粪便下移的作用。齿状线由肛瓣和肛柱下端形成，与直肠横襞无关。"},{"q":"有关肝门静脉的说法，正确的是","o":["行于肝胃韧带内","由肠系膜上、下静脉合成","注入下腔静脉","肾静脉是其属支","两端均为毛细血管"],"a":4,"e":"肝门静脉起始端和末端均与毛细血管相连，且无静脉瓣，是功能性血管而非注入下腔静脉。它由肠系膜上静脉和脾静脉汇合而成，行于肝十二指肠韧带内。"},{"q":"食管的第二个狭窄位置是","o":["食管起始处","食管与胃相接处","食管与左主气管交叉处","距中切牙约40cm","食管穿膈处"],"a":2,"e":"食管第2狭窄位于左主支气管后方与其交叉处，相当于第4、5胸椎之间，距中切牙约25cm。食管起始处为第1狭窄，穿膈处为第3狭窄。"},{"q":"位于延髓内的脑神经核是","o":["展神经核","面神经核","迷走神经背核","红核","薄束核"],"a":2,"e":"迷走神经背核位于延髓，内含副交感神经元的胞体。展神经核位于脑桥，面神经核位于脑桥，红核位于中脑。"},{"q":"关于肺动脉的描述，正确的是","o":["肺动脉中含的是动脉血","左肺动脉长，向左行至左肺门","右肺动脉向右经升主动脉与上腔静脉后方达右肺门","肺动脉全长包在心包内","在肺动脉分叉处的稍右侧有动脉韧带连于主动脉弓"],"a":2,"e":"右肺动脉较长且粗，经升主动脉和上腔静脉后方横行至右肺门，分为上、中、下三支入右肺。肺动脉运送静脉血；左肺动脉较短，在左主支气管前方横行。"},{"q":"背阔肌的作用","o":["使肩关节旋外","只能使肩关节内收","使肩胛骨旋内","使肩关节后伸、内收和旋内","使肩关节后伸和旋外"],"a":3,"e":"背阔肌收缩使肩关节后伸、内收和旋内，上肢固定时可引体向上。肩关节旋外由冈下肌、小圆肌完成，背阔肌作用不限于内收。"},{"q":"收集腹腔不成对脏器淋巴的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":0,"e":"肠干由腹腔淋巴结、肠系膜上淋巴结和肠系膜下淋巴结的输出淋巴管汇合而成，收集腹腔不成对脏器的淋巴。腰干收集下肢、盆部及腹后壁的淋巴。"},{"q":"通过斜角肌间隙的是","o":["阴部内动脉","臀上动脉","旋肱后动脉","锁骨下动脉","股动脉"],"a":3,"e":"前、中斜角肌与第1肋之间为斜角肌间隙，有锁骨下动脉和臂丛通过。锁骨下动脉呈弓状经胸膜顶前方，穿该间隙至第1肋外侧缘续为腋动脉。"},{"q":"下列关于脊髓丘脑侧束的描述，正确的是","o":["由同侧后角细胞轴突构成","由同侧脊神经节细胞的中枢突组成","传导对侧躯干、四肢的精细触觉","传导对侧躯干、四肢的痛温觉","传导对侧躯干、四肢触觉"],"a":3,"e":"脊髓丘脑侧束由对侧后角细胞发出的纤维经白质前连合交叉后组成，传导对侧躯干、四肢的痛温觉。粗略触觉和压觉由脊髓丘脑前束传导。"},{"q":"关于胸膜，下列说法正确的是","o":["胸膜腔在男性完全封闭，女性间接通体外","可分胸膜顶、肋胸膜、膈胸膜三部分","胸膜腔最低点是肋膈隐窝","胸膜顶高出胸骨上端2～3cm","胸膜下界在腋中线与第8肋相交"],"a":2,"e":"肋膈隐窝是肋胸膜与膈胸膜返折形成的半环形间隙，为诸胸膜隐窝中位置最低、容量最大者，胸膜腔积液常先积存于此。胸膜分胸膜顶、肋胸膜、膈胸膜和纵隔胸膜四部分。"},{"q":"下列哪项关于动脉触摸点的叙述是正确的","o":["颈总动脉触摸点在胸锁乳突肌后缘中点","足背动脉在活体上易触摸到搏动的部位是踝关节后方，内、外踝连线的中点","股动脉在活体上易触摸到的搏动部位是股动脉的上段","桡动脉在活体上诊脉的部位是桡动脉上段","锁骨下动脉触摸点在锁骨上小窝"],"a":2,"e":"股动脉在腹股沟韧带中点稍下方位置表浅，活体可触及搏动，下肢出血时可在此压向耻骨上支止血。颈总动脉触摸点在胸锁乳突肌前缘，桡动脉诊脉部位为桡动脉下段。"},{"q":"下列关于马尾描述正确的是","o":["由骶部脊神经后根形成","由下部脊神经前根形成","由下部几对脊神经形成","是在脊髓末端下行的脊神经根的总称","位于椎间孔内"],"a":3,"e":"脊髓圆锥下端约平第1腰椎下缘，其下方腰、骶、尾神经根围绕终丝聚集成束，称马尾，即脊髓末端下行的脊神经根总称。马尾位于椎管内，并非椎间孔内。"},{"q":"分布在大脑皮质顶枕沟以前的半球内侧面的主要动脉是","o":["大脑前动脉","大脑中动脉","大脑后动脉","椎动脉","基底动脉"],"a":0,"e":"大脑前动脉沿胼胝体沟向后行，皮质支分布于顶枕沟以前的半球内侧面、额叶底面一部分及额、顶两叶上外侧面。大脑后动脉分布于颞叶和枕叶内侧面，不覆盖顶枕沟以前区域。"},{"q":"关于尺骨形态的描述，何者错误","o":["属长骨","有尺切迹","有鹰嘴","下端无腕关节面","有滑车切迹"],"a":1,"e":"尺切迹位于桡骨下端内面，与尺骨头相关节，属桡骨结构。尺骨居前臂内侧，上端有鹰嘴和滑车切迹，下端为尺骨头，无腕关节面，属长骨。"},{"q":"大脑后动脉发自","o":["基底动脉","椎动脉","颈内动脉","颈外动脉","颈总动脉"],"a":0,"e":"基底动脉沿脑桥腹侧基底沟上行，至脑桥上缘分为左、右大脑后动脉，故大脑后动脉为基底动脉终末支。椎动脉在脑桥与延髓交界处汇合成基底动脉。"},{"q":"支配比目鱼肌的神经是","o":["闭孔神经","胫神经","腓浅神经","腓深神经","股神经"],"a":1,"e":"小腿后群肌均由胫神经支配，比目鱼肌属后群浅层，起自腓骨后面上部及胫骨比目鱼肌线，止于跟骨结节，作用为屈踝关节。腓浅神经支配外侧群，腓深神经支配前群。"},{"q":"女性生殖腺是","o":["卵巢","输卵管","子宫","阴道","前庭大腺"],"a":0,"e":"卵巢是女性生殖腺，位于盆腔卵巢窝内，产生卵子并分泌雌激素和孕激素。输卵管、子宫、阴道属生殖管道，前庭大腺为附属腺。"},{"q":"下列关于男性尿道的描述，正确的是","o":["分为前列腺部、膜部和海绵体部","全长粗细均匀一致","膜部有射精管开口","耻骨前弯是恒定弯曲","全长有三个弯曲"],"a":0,"e":"男性尿道分前列腺部、膜部和海绵体部三部分。全长粗细不均，有三个狭窄、三个膨大和两个弯曲；射精管开口于前列腺部，耻骨前弯可被矫正，耻骨下弯恒定。"},{"q":"脑神经有多少对","o":["10","11","12","13","14"],"a":2,"e":"脑神经是与脑相连的周围神经，共12对；脊神经与脊髓相连，共31对。"},{"q":"中央有视网膜中央血管穿过的结构是","o":["黄斑","中央凹","脉络膜","视神经盘","巩膜"],"a":3,"e":"视神经盘中央凹陷称视盘陷凹，有视网膜中央动、静脉穿过，无感光细胞，为生理性盲点。黄斑中央凹为视觉最敏锐处，无血管穿过。"},{"q":"左侧三叉丘系传导的感觉信息主要是","o":["左侧躯干、四肢意识性浅感觉","右侧躯干、四肢意识性浅感觉","左侧头面部意识性浅感觉","右侧头面部意识性浅感觉","双侧头面、躯干、四肢意识性浅感觉"],"a":3,"e":"三叉丘系传导头面部痛、温觉和触压觉，第3级神经元胞体在背侧丘脑腹后内侧核，经丘脑中央辐射投射至中央后回下部，故一侧三叉丘系受损引起对侧头面部意识性浅感觉障碍。"},{"q":"关于内分泌系统的描述，错误的是","o":["内分泌系统由内分泌器官组成","所有的内分泌腺都没有排泄导管","不同的内分泌腺分泌不同的激素","内分泌激素经血液循环运送到全身","内分泌腺接受神经系统的调节，也可影响神经系统的功能"],"a":0,"e":"内分泌系统由内分泌腺和内分泌组织组成，并非仅由内分泌器官构成。内分泌腺无导管，激素经血液循环作用于靶器官，并受神经系统调节。"},{"q":"有关肋间外肌的说法，错误的是","o":["位于各肋间隙的浅层","起自肋骨下缘","受肋间神经支配","提肋，协助吸气","止于下一肋骨上缘"],"a":1,"e":"肋间外肌起自上位肋骨下缘，止于下位肋骨上缘，肌束斜向前下，提肋助吸气，受肋间神经支配。"},{"q":"隐神经发自","o":["股神经","闭孔神经","正中神经","坐骨神经","阴部神经"],"a":0,"e":"隐神经是股神经最长的皮支，伴股动脉进入收肌管，于缝匠肌下端后方浅出，分布于小腿内侧面及足内侧缘皮肤。"},{"q":"下列器官，何者属于内分泌腺","o":["垂体","卵巢","胰腺","睾丸","前列腺"],"a":0,"e":"垂体属内分泌腺，无导管，分泌激素直接入血。卵巢、睾丸、胰腺虽含内分泌组织，但兼具外分泌或生殖功能，不列为内分泌腺。"},{"q":"左侧内囊膝病变时，最有可能出现","o":["左侧面神经核上瘫","右侧面神经核上瘫","左侧面神经核下瘫","右侧面神经核下瘫","双侧下半部面瘫"],"a":1,"e":"皮质核束经内囊膝下行，面神经核下部只接受对侧皮质核束支配，故左侧内囊膝病变致右侧面下部肌核上瘫。"},{"q":"关于肺的说法，错误的是","o":["肺底又称膈面","外侧面又称肋面","右肺分为上、中、下三叶","左肺前缘有心切迹","肺动脉、肺静脉、淋巴管和神经组成肺根"],"a":4,"e":"肺根由主支气管、肺动脉、肺静脉、淋巴管和神经等被胸膜包绕构成，肺动脉、肺静脉、淋巴管和神经的表述遗漏主支气管。"},{"q":"上鼻甲后上方与蝶骨体之间的凹陷为","o":["上颌窦","上鼻道","蝶筛隐窝","垂体窝","咽隐窝"],"a":2,"e":"上鼻甲后上方与蝶骨体之间的凹陷称蝶筛隐窝，蝶窦开口于此。上颌窦位于上颌骨体内，垂体窝在蝶鞍，咽隐窝在鼻咽部。"},{"q":"视觉中枢位于","o":["中央后回和中央旁小叶后部","中央前回和中央旁小叶前部","颞横回","额下回后部","距状沟上、下皮质"],"a":4,"e":"视觉中枢位于距状沟上、下方的枕叶皮质（楔叶和舌回，17区），接受外侧膝状体发出的视辐射纤维。中央后回为躯体感觉中枢，中央前回为躯体运动中枢，颞横回为听觉中枢。"},{"q":"下列结构属于躯体感觉核的是","o":["面神经核","舌下神经","三叉神经脑桥核","迷走神经背核","展神经核"],"a":2,"e":"三叉神经脑桥核属一般躯体感觉核，接受头面部触、压觉初级纤维。面神经核、舌下神经核、展神经核为躯体运动核，迷走神经背核为一般内脏运动核。"},{"q":"下列关于薄束和楔束的描述，正确的是","o":["楔束起自第4胸髓节段以下的脊神经节细胞","薄束起自第5胸髓节段以上的脊神经节细胞","传导同侧的本体觉和精细触觉","终于脊髓板层Ⅰ～Ⅴ","贯穿脊髓全长"],"a":2,"e":"薄束、楔束传导同侧躯干及四肢的本体感觉和皮肤精细触觉。薄束起自第4胸髓节段以下的脊神经节细胞，楔束起自第4胸髓节段以上，薄束贯穿脊髓全长而楔束仅见于胸髓中段以上。"},{"q":"下列关于骨盆的叙述中，正确的是","o":["由髋骨借关节等连结构成","可分为大、小骨盆","大骨盆的内腔称骨盆腔","男性骨盆腔呈圆桶状","女性耻骨下角为锐角"],"a":1,"e":"骨盆由左、右髋骨和骶、尾骨及其间骨连结构成，经界线分为上方的大骨盆和下方的小骨盆。骨盆腔位于小骨盆内，女性耻骨下角为钝角。"},{"q":"位于肾窦内的结构","o":["肾柱","肾小盏","肾锥体","肾纤维囊","肾门"],"a":1,"e":"肾窦容纳肾血管、肾小盏、肾大盏、肾盂和脂肪等，肾小盏位于肾窦内。肾柱、肾锥体属肾实质，肾门是肾窦的开口，肾纤维囊包于肾表面。"},{"q":"颞浅动脉的描述何者有误","o":["是颈内动脉的终支之一","是颈外动脉的终支之一","经过外耳门的前方","颧弓根部前方可压迫止血","主要分布至颞区"],"a":0,"e":"颞浅动脉是颈外动脉的终支之一，经外耳门前方上行，分布于颞区，颧弓根部前方可压迫止血。颈内动脉在颈部无分支，不发出颞浅动脉。"},{"q":"副交感神经的低级中枢不包括","o":["动眼神经副核","脊髓骶部第2～4节段灰质的骶副交感核","迷走神经背核","上泌涎核","脊髓腰部第1～3节段灰质的侧角"],"a":4,"e":"副交感神经低级中枢位于脑干的一般内脏运动核（动眼神经副核、上泌涎核、下泌涎核、迷走神经背核）和脊髓S2～S4节段的骶副交感核。脊髓T1～L3节段中间带外侧核是交感神经低级中枢。"},{"q":"关于肌的起止和作用，下列描述正确的是","o":["四肢肌多起于肢体远端","躯干肌多起于远离正中线的部位","肌在移动骨上的附着点称止点或定点","肌的起止点在一定条件下可以互换","肌在固定骨上的附着点称起点或动点"],"a":3,"e":"肌在骨上的定点和动点是相对的，在一定条件下可以互相转换。肌在固定骨上的附着点称定点（起点），在移动骨上的附着点称动点（止点）。"},{"q":"颈内静脉汇入下列何静脉","o":["颈总静脉","头臂静脉","颈外静脉","腋静脉","锁骨下静脉"],"a":1,"e":"颈内静脉在胸锁关节后方与锁骨下静脉汇合成头臂静脉，故汇入头臂静脉。锁骨下静脉在第1肋外侧缘续于腋静脉，与颈内静脉汇合处称静脉角。"},{"q":"右淋巴导管注入部位是","o":["左静脉角","右静脉角","左颈前静脉","右颈前静脉","左锁骨下静脉"],"a":1,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，注入右静脉角。胸导管注入左静脉角，两者分别注入左、右静脉角。"},{"q":"关于肾上腺的描述，错误的是","o":["位于腹膜后方","左肾上腺近似半月形","分皮质和髓质两部分","与肾共同包在肾纤维囊内","分泌的激素可参与调节体内水盐代谢"],"a":3,"e":"肾上腺与肾共同包裹于肾筋膜内，而非肾纤维囊内；纤维囊紧贴肾实质表面。左肾上腺呈半月形、右肾上腺呈三角形，肾上腺分皮质和髓质，其激素参与水盐代谢。"},{"q":"不成对的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":0,"e":"全身9条淋巴干中，腰干、支气管纵隔干、锁骨下干、颈干均成对，仅肠干不成对，汇入乳糜池。"},{"q":"舌下神经出脑时，其内侧紧邻","o":["下丘","大脑脚","基底沟","橄榄","锥体"],"a":4,"e":"舌下神经起自延髓舌下神经核，经锥体与橄榄之间的前外侧沟出脑，其内侧紧邻锥体，外侧为橄榄。"},{"q":"连结上肢与躯干的关节","o":["肩锁关节","肩关节","胸锁关节","胸肋关节","肋椎关节"],"a":2,"e":"胸锁关节由锁骨的胸骨端与胸骨柄的锁切迹构成，是上肢骨与躯干骨之间唯一的关节。肩锁关节属上肢带骨之间的连结。"},{"q":"属于下丘脑的神经核是","o":["视上核","齿状核","下橄榄核","腹后核","杏仁体"],"a":0,"e":"视上核位于下丘脑，合成抗利尿激素经视上垂体束投射至神经垂体。齿状核属小脑，下橄榄核属延髓，腹后核属丘脑，杏仁体属端脑。"},{"q":"以下对三叉神经的描述，正确的是","o":["为第Ⅵ对脑神经","三条分支均含有运动纤维","三个分支均经眶上裂出颅","运动纤维支配表情肌","为混合性脑神经"],"a":4,"e":"三叉神经为混合性脑神经，含一般躯体感觉和特殊内脏运动两种纤维。三叉神经为第Ⅴ对脑神经，仅下颌神经含运动纤维，眼神经、上颌神经分别经眶上裂、圆孔出颅，其运动纤维支配咀嚼肌。"},{"q":"位于中脑的结构是","o":["锥体交叉","薄束结节","基底沟","橄榄","大脑脚"],"a":4,"e":"大脑脚位于中脑腹侧，由大脑皮质发出的下行纤维构成，两侧大脑脚之间为脚间窝。锥体交叉在延髓，薄束结节在延髓，基底沟在脑桥，橄榄在延髓。"},{"q":"关于肝门静脉，下列说法正确的是","o":["收集胃、肠、肝等不成对脏器的血液","行于肝镰状韧带内","注入下腔静脉","经肝门入肝","由肠系膜上、下静脉汇合成"],"a":3,"e":"肝门静脉经肝十二指肠韧带内上行至肝门，分为两支入肝左、右叶。肝门静脉收集腹腔不成对脏器（肝除外）的血液，由肠系膜上静脉和脾静脉汇合而成，注入肝血窦而非下腔静脉。"},{"q":"下颌窝是哪块骨上的结构","o":["下颌骨","蝶骨","颞骨","上颌骨","颧骨"],"a":2,"e":"颞骨岩部与鳞部交界处下方有下颌窝，与下颌骨的下颌头构成颞下颌关节，窝前缘隆起为关节结节。下颌窝属颞骨结构，非下颌骨、蝶骨、上颌骨或颧骨。"},{"q":"以下对上颌神经的描述，正确的是","o":["通过圆孔","延续为眶上神经","支配颞肌","分布于口裂以下的皮肤","为混合性神经"],"a":0,"e":"上颌神经为三叉神经分支，含一般躯体感觉纤维，穿圆孔出颅入翼腭窝，再经眶下裂入眶续为眶下神经。眶上神经为眼神经分支，颞肌由下颌神经分支支配。"},{"q":"占眼球纤维膜前1/6的结构是","o":["角膜","巩膜","虹膜","脉络膜","视网膜"],"a":0,"e":"角膜占眼球纤维膜前1/6，无色透明、无血管而富感觉神经末梢，具有屈光作用。巩膜占后5/6，虹膜、脉络膜、视网膜分属血管膜和视网膜。"},{"q":"关于腹直肌的描述，正确的是","o":["起自剑突和附近肋软骨的前面","腱划与腹直肌鞘后层紧密相连","全长被腱划分成若干个肌腹","后面全部被腹直肌鞘包裹","收缩时，可使脊柱后伸"],"a":2,"e":"腹直肌全长被3～4条横行腱划分成多个肌腹，腱划与腹直肌鞘前层紧密结合，后面不与后层愈合而游离。腹直肌起自耻骨联合和耻骨嵴，止于剑突和5～7肋软骨前面，收缩使脊柱前屈。"},{"q":"关于肝的描述，正确的是","o":["主要位于右季肋区和左季肋区","主要位于左季肋区和腹上区","大部分位于腹上区和左侧季肋区","大部分被肋弓所覆盖","剑突下触摸不到肝"],"a":3,"e":"肝大部分位于右季肋区和腹上区，小部分位于左季肋区，其前面大部分被肋弓掩盖，仅在腹上区剑突下露出。右肋弓下一般不能触及肝，剑突下可触及约3cm。"},{"q":"前交通动脉连接","o":["颈内动脉与大脑前动脉","颈内动脉与大脑中动脉","两侧大脑前动脉","两侧颈内动脉","两侧大脑中动脉"],"a":2,"e":"大脑前动脉在视神经上方行向前内进入大脑纵裂，与对侧同名动脉借前交通动脉相连。前交通动脉连接两侧大脑前动脉，是动脉瘤好发部位。"},{"q":"占眼球血管膜后2/3的结构是","o":["虹膜","角膜","睫状体","脉络膜","脉络丛"],"a":3,"e":"脉络膜占眼球血管膜的后2/3，富含血管及色素，可营养眼球内组织并吸收分散光线。虹膜和睫状体位于血管膜前部。"},{"q":"齿状线","o":["是肛门内、外括约肌的分界线","肛柱下端与肛瓣边缘的环形线","临床上称为痔环","又称为肛直肠线","肛柱上端的环形线"],"a":1,"e":"齿状线是连接各肛柱下端与各肛瓣边缘的锯齿状环行线，为肛管黏膜与皮肤的分界。肛直肠线为各肛柱上端的连线，即直肠与肛管的分界线。"},{"q":"关于甲状腺的描述，正确的是","o":["分泌甲状腺素和降钙素","呑咽时，可随喉上、下移动","形态为“C”型，分左右二叶","锥状叶常由左叶或右叶向上伸出","左、右叶后外侧有颈内动脉、颈内静脉、膈神经通过"],"a":1,"e":"甲状腺借假被膜形成的甲状腺悬韧带固定于喉和气管壁上，吞咽时可随喉上、下移动。甲状腺滤泡旁细胞分泌降钙素，锥状叶多自峡部或左叶伸出。"},{"q":"关于面动脉的描述何者有误","o":["经咬肌前缘和下颌底相交处进入面部","向上行经口角的外侧","至内眦处更名为内眦动脉","其后方有面静脉伴行","双侧面动脉间无吻合"],"a":4,"e":"面动脉与对侧面动脉之间存在吻合，故“双侧面动脉间无吻合”有误。面动脉经咬肌前缘与下颌底相交处入面部，行经口角外侧，至内眦处更名内眦动脉，后方有面静脉伴行。"},{"q":"发自臂丛外侧束的神经为","o":["腋神经","胸背神经","肌皮神经","尺神经","桡神经"],"a":2,"e":"肌皮神经自臂丛外侧束发出，斜穿喙肱肌后分布于肱二头肌、肱肌和喙肱肌。腋神经、桡神经发自后束，尺神经发自内侧束。"},{"q":"关于肝下界的描述，正确的是","o":["在右腋中线起自第10肋","在左腋中线起自第10肋","在右侧第7、8肋软骨结合处离开右肋弓","在左肋弓第8、9肋软骨结合处进入左季肋区","在剑突下触摸不到肝"],"a":0,"e":"肝下界在右腋中线起自第10肋，右锁骨中线处平右肋弓下缘。肝下界在右肋弓下缘与右肋弓相交，剑突下可触及肝下缘。"},{"q":"关于肘正中静脉的叙述正确的是","o":["起于手背静脉网","直接汇入肱静脉","属于深静脉","属于浅静脉","连接桡静脉和尺静脉"],"a":3,"e":"肘正中静脉位于浅筋膜内，属上肢浅静脉，于肘窝处连接头静脉与贵要静脉。贵要静脉起自手背静脉网尺侧，头静脉起自桡侧。"},{"q":"以下有关颞下颌关节的叙述，正确的是","o":["由下颌骨下颌头与颞骨下颌窝构成","关节内有关节盘","关节囊紧张坚韧","仅能做开口、闭口运动","容易发生后脱位"],"a":1,"e":"颞下颌关节腔内含纤维软骨构成的关节盘，将关节腔分为上、下两部分。关节囊松弛，可作上提、下降、前进、后退及侧方运动，前壁薄弱易发生前脱位。"},{"q":"静脉角由下列哪两支静脉汇合而成","o":["颈内静脉、颈外静脉","左、右头臂静脉","锁骨下静脉与颈内静脉","锁骨下静脉与颈外静脉","锁骨下静脉与颈总静脉"],"a":2,"e":"静脉角由颈内静脉与锁骨下静脉在胸锁关节后方汇合而成，是淋巴导管的注入部位。颈外静脉注入锁骨下静脉，左、右头臂静脉汇合形成上腔静脉。"},{"q":"完成拇指对掌运动的主要关节是","o":["桡腕关节","腕骨间关节","第1掌指关节","掌骨间关节","拇指腕掌关节"],"a":4,"e":"拇指腕掌关节由大多角骨与第1掌骨底构成，属鞍状关节，可作屈伸、收展、环转和对掌运动，对掌运动即由该关节完成。"},{"q":"关于阑尾，下列说法正确的是","o":["结肠带是寻找阑尾的标志","是腹膜间位器官","以回肠后位多见","由腹腔干供血","没有系膜"],"a":0,"e":"结肠带由肠壁纵行肌增厚形成，3条结肠带均会聚于阑尾根部，沿结肠带向下追踪是寻找阑尾的可靠方法。阑尾为腹膜内位器官，多居回肠后位，由回结肠动脉供血。"},{"q":"淋巴导管注入部位是","o":["静脉角","胸骨角","脊肋角","下颌角","下腔静脉"],"a":0,"e":"胸导管注入左静脉角，右淋巴导管注入右静脉角，静脉角是淋巴导管注入部位。胸骨角、脊肋角、下颌角均为体表标志，与淋巴回流无关。"},{"q":"有关心尖的描述，正确的是","o":["朝向左后下方","由左心房构成","由左心室构成","由左心房和左心室构成","位于左侧第5肋间隙与左侧锁骨中线相交处"],"a":2,"e":"心尖圆钝、游离，由左心室构成，朝向左前下方，在左侧第5肋间隙锁骨中线内侧1～2cm处可触及心尖搏动。"},{"q":"关于脊髓灰质的描述，错误的是","o":["板层Ⅷ～Ⅸ位于前角","板层Ⅰ～Ⅳ相当于后角","板层Ⅴ～Ⅶ居中间带","由神经元突起和神经胶质组成","板层Ⅹ位于中央管周围"],"a":3,"e":"脊髓灰质是神经元胞体及突起、神经胶质和血管等的复合体，并非仅由神经元突起和神经胶质组成。板层Ⅰ～Ⅳ相当于后角，Ⅴ～Ⅶ居中间带，Ⅷ～Ⅸ位于前角，Ⅹ位于中央管周围。"},{"q":"食管腹段的动脉供应来自","o":["胃左动脉","胃右动脉","胃网膜左动脉","胃网膜右动脉","胃短动脉"],"a":0,"e":"食管腹段由胃左动脉分支供应，胃左动脉起自腹腔干，沿胃小弯行。胃右动脉、胃网膜左、右动脉及胃短动脉分别供应胃的其他部位。"},{"q":"关于鼓膜的描述，下列错误的是","o":["位于外耳道与鼓室之间","构成鼓室外侧壁的大部分","婴儿鼓膜更为倾斜，几乎呈水平位","鼓膜边缘附着在颞骨鼓部和鳞部，鼓膜周缘较厚","鼓膜中心向内凹陷，称鼓膜脐，为砧骨柄末端附着处"],"a":4,"e":"鼓膜脐为锤骨柄末端附着处，而非砧骨柄。鼓膜位于外耳道与鼓室之间，构成鼓室外侧壁的大部分，边缘附着于颞骨，小儿鼓膜更倾斜，几乎呈水平位。"},{"q":"关于呼吸系统的叙述，正确的是","o":["由呼吸道和肺组成","其功能仅是进行气体交换","鼻、咽、喉、气管称上呼吸道","主支气管及其在肺内的分支称下呼吸道","肺仅有肺泡构成"],"a":0,"e":"呼吸系统由呼吸道和肺组成，呼吸道包括鼻、咽、喉、气管和各级支气管。上呼吸道指鼻、咽、喉，下呼吸道为气管和各级支气管；肺由肺实质和肺间质构成，并非仅由肺泡构成。"},{"q":"以下关于脊髓的描述，正确的是","o":["薄束和楔束传导痛温觉","第1胸髓节段～第3腰髓节段侧角有副交感神经低级中枢","皮质脊髓侧束终止于对侧前角运动神经元","脊髓丘脑束起始于脊神经节","白质分为前索、后索和外侧索三部分"],"a":4,"e":"脊髓白质借纵沟分为前索、外侧索和后索三部分。薄束、楔束传导本体觉和精细触觉；侧角为交感神经低级中枢；皮质脊髓侧束止于同侧前角运动神经元。"},{"q":"由肾门深入肾实质之间的腔隙称为","o":["肾柱","肾大盏","肾盂","肾蒂","肾窦"],"a":4,"e":"由肾门伸入肾实质的腔隙称肾窦，容纳肾血管、肾小盏、肾大盏、肾盂和脂肪等。肾窦是肾门的延续，肾门为肾窦的开口。"},{"q":"有关心包腔的描述，错误者是","o":["由纤维性心包与浆膜性心包围成","由浆膜性心包的脏层与壁层围成","内有少量的浆液","对心脏有保护作用","与胸膜腔不相通"],"a":0,"e":"心包腔由浆膜心包脏层与壁层返折围成，内含少量浆液，可减少心脏搏动时的摩擦，与胸膜腔不相通。纤维心包位于浆膜心包外层，不参与围成心包腔。"},{"q":"肩关节囊内通过的肌腱是","o":["胸大肌肌腱","背阔肌肌腱","肱二头肌长头肌腱","肱二头肌短头肌腱","肱三头肌长头肌腱"],"a":2,"e":"肱二头肌长头腱起自肩胛骨盂上结节，通过肩关节囊，经肱骨结节间沟下降，周围包以结节间滑膜鞘。短头起自喙突，不穿关节囊。"},{"q":"以下骨骼肌，由胫神经支配的是","o":["股二头肌","小腿三头肌","胫骨前肌","腓骨长肌","腓骨短肌"],"a":1,"e":"小腿三头肌由腓肠肌和比目鱼肌组成，由胫神经支配。股二头肌由坐骨神经支配，胫骨前肌、腓骨长肌和腓骨短肌由腓深、腓浅神经支配。"},{"q":"右心室的入口是","o":["右房室口","左房室口","肺动脉口","主动脉口","肺静脉口"],"a":0,"e":"右心室流入道的入口为右房室口，呈卵圆形，周围有三尖瓣环围绕，三尖瓣基底附着于该环上。肺动脉口为右心室流出道的出口。"},{"q":"关于椎动脉正确的描述是","o":["向上穿行全部颈椎的横突孔","为颈外动脉的分支之一","参与组成大脑动脉环","经枕骨大孔入颅","发出大脑后动脉"],"a":3,"e":"椎动脉起自锁骨下动脉，向上穿第6至第1颈椎横突孔，经枕骨大孔入颅腔，在脑桥与延髓交界处左右汇合成基底动脉。基底动脉发出大脑后动脉，椎动脉不穿全部颈椎横突孔。"},{"q":"受腋神经支配的骨骼肌为","o":["三角肌","肱三头肌","肱肌","喙肱肌","肱桡肌"],"a":0,"e":"三角肌由腋神经支配。腋神经从臂丛后束发出，穿四边孔绕肱骨外科颈至三角肌深面，发支支配三角肌和小圆肌。肱三头肌、肱肌、喙肱肌、肱桡肌分别由桡神经、肌皮神经、肌皮神经、桡神经支配。"},{"q":"伸髋、屈膝的肌肉是","o":["髂腰肌","股四头肌","阔筋膜张肌","缝匠肌","股二头肌"],"a":4,"e":"股二头肌属大腿后群肌，作用是屈膝关节、伸髋关节。后群半腱肌、半膜肌同样屈膝伸髋；股四头肌屈髋伸膝，缝匠肌屈髋屈膝，髂腰肌屈髋，阔筋膜张肌紧张阔筋膜。"},{"q":"舌咽神经的根丝通过颅底什么结构出入颅腔","o":["圆孔","卵圆孔","棘孔","颈静脉孔","枕骨大孔"],"a":3,"e":"舌咽神经连于延髓橄榄后沟上部，与迷走神经、副神经同穿颈静脉孔出入颅腔。圆孔、卵圆孔、棘孔分别通行上颌神经、下颌神经、脑膜中动脉，枕骨大孔为脊髓与延髓交界处。"},{"q":"关于脑膜中动脉的叙述，错误的是","o":["是上颌动脉的分支","营养硬脑膜","经棘孔入颅","其前支经翼点深面","营养软脑膜"],"a":4,"e":"脑膜中动脉是上颌动脉的分支，穿棘孔入颅，分布于颅骨和硬脑膜，前支行经翼点内面，颞部骨折时易损伤致硬膜外血肿。软脑膜由脑的血管分支营养，不由脑膜中动脉供血。"},{"q":"有关节盘的关节是","o":["肩关节","肘关节","髋关节","膝关节","颞下颌关节"],"a":4,"e":"颞下颌关节由下颌头与颞骨下颌窝及关节结节构成，关节囊内有纤维软骨性关节盘，将关节腔分为上、下两部。肩、肘、髋关节均无关节盘，膝关节的关节盘为半月板。"},{"q":"关于肋骨正确的描述是","o":["为长骨","分体和前、后两端","肋头与胸椎横突相关节","肋沟位于各肋内面上缘","前端和胸骨相关节"],"a":1,"e":"肋骨属扁骨，分为体和前、后两端。肋头与胸椎上、下肋凹相关节，肋沟位于肋体内面下缘，前端借肋软骨连于胸骨或上位肋软骨。"},{"q":"下列关于睾丸的描述，正确的是","o":["表面光滑，周围覆以鞘膜","上端有血管、神经和淋巴管进入","上端和后缘为附睾贴附","分为皮质和髓质两部分","精直小管能产生精子和分泌雄性激素"],"a":2,"e":"附睾呈新月形，紧贴睾丸上端和后缘，分头、体、尾三部。睾丸后缘有血管、神经和淋巴管出入，表面覆以鞘膜，实质分小叶而非皮质髓质；产生精子并分泌雄激素的是睾丸间质细胞。"},{"q":"属于脊髓内的下行纤维束有","o":["薄束","楔束","红核脊髓束","脊髓丘脑前束","三叉丘系"],"a":2,"e":"红核脊髓束起自中脑红核，交叉后于脊髓外侧索下行，属下行运动传导束。薄束、楔束、脊髓丘脑前束为上行传导束，三叉丘系位于脑干，传导头面部感觉。"},{"q":"下面属于面颅骨的是","o":["上鼻甲","中鼻甲","下鼻甲","筛骨","颞骨"],"a":2,"e":"下鼻甲是独立的面颅骨，成对，属面颅15块骨之一。上、中鼻甲由筛骨迷路内侧壁的薄骨片构成，筛骨属脑颅骨。"},{"q":"虎口周缘感觉功能障碍，最有可能损伤的神经为","o":["腋神经","尺神经","正中神经","桡神经","肌皮神经"],"a":3,"e":"桡神经在肱骨中段后方紧贴桡神经沟走行，骨折易损伤，致前臂伸肌群瘫痪呈“垂腕”，并出现第1、2掌骨间背面（虎口区）皮肤感觉障碍。"},{"q":"躯干和四肢痛温觉传导通路的第2级神经元是","o":["三叉神经节","三叉神经脊束核","脊髓后角细胞","脊髓侧角细胞","脊神经节"],"a":2,"e":"躯干和四肢痛温觉传导通路第1级神经元为脊神经节假单极神经元，中枢突经后根入脊髓后终止于脊髓后角细胞，即第2级神经元。三叉神经脊束核接受头面部痛温觉。"},{"q":"卵巢与子宫角相连的韧带是","o":["卵巢系膜","卵巢固有韧带","卵巢悬韧带","子宫圆韧带","子宫阔韧带"],"a":1,"e":"卵巢固有韧带由结缔组织和平滑肌纤维构成，自卵巢下端连至输卵管与子宫结合处的后下方，即连于子宫角。卵巢悬韧带为阔韧带上缘外侧1/3的腹膜皱襞。"},{"q":"腹主动脉通常不发出以下哪条动脉","o":["卵巢动脉","睾丸动脉","肾上腺中动脉","肾上腺上动脉","膈下动脉"],"a":3,"e":"肾上腺上动脉发自膈下动脉，不直接起自腹主动脉。腹主动脉成对脏支有肾上腺中动脉、肾动脉、睾丸动脉或卵巢动脉，膈下动脉为其壁支。"},{"q":"不供应大肠的动脉是","o":["中结肠动脉","回结肠动脉","左结肠动脉","右结肠动脉","回肠动脉"],"a":4,"e":"回肠动脉自肠系膜上动脉左侧壁发出，经动脉弓供应空肠和回肠。中、右、左结肠动脉及回结肠动脉分别营养升、横、降结肠及盲肠、阑尾等大肠各部。"},{"q":"关于鼓室，下列说法正确的是","o":["经咽鼓管与鼻腔相通","镫骨底封闭其前庭窗","与筛窦小房相通","其内空气来自外耳道","有前庭蜗神经通过"],"a":1,"e":"镫骨底借韧带连于前庭窗周边并封闭前庭窗，是声波经听小骨链传入内耳的关键。鼓室经咽鼓管通鼻咽部而非鼻腔，其内空气来自鼻咽部。"},{"q":"可以限制子宫向侧方移位的韧带是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":0,"e":"子宫阔韧带为子宫侧缘向盆侧壁延伸的双层腹膜皱襞，可限制子宫向两侧移动。子宫圆韧带和子宫主韧带主要维持子宫前倾。"},{"q":"受正中神经支配的骨骼肌为","o":["肱桡肌","拇收肌","第1～2蚓状肌","尺侧腕屈肌","小鱼际"],"a":2,"e":"第1、2蚓状肌由正中神经支配。教材载正中神经在手部的运动纤维支配第1、2蚓状肌和鱼际肌（拇收肌除外）。拇收肌由尺神经支配，肱桡肌由桡神经支配。"},{"q":"在下丘下方出脑的神经为","o":["动眼神经","展神经","滑车神经","视神经","副神经"],"a":2,"e":"滑车神经是唯一自脑干背侧面出脑的脑神经，于下丘下方与上髓帆之间出脑。动眼神经自中脑脚间窝出脑，展神经自脑桥延髓沟出脑。"},{"q":"关于咽鼓管描述，下列错误的是","o":["咽鼓管使鼓室的气压与外界的大气压相等，以保持鼓膜内、外的压力平衡","咽鼓管连通鼻咽部与鼓室","咽鼓管骨部向后外开口于咽鼓管鼓室口","咽鼓管软骨部向前内开口于咽鼓管咽口，平时处于开放状态","小儿咽鼓管短而宽，接近水平位，故咽部感染可经咽鼓管侵入鼓室"],"a":3,"e":"咽鼓管软骨部向前内侧开口于鼻咽部侧壁的咽鼓管咽口，平时处于闭合状态，吞咽或打哈欠时才开放以平衡鼓膜内外压力。"},{"q":"胸骨线","o":["沿胸骨正中的垂线","沿胸骨外侧缘的垂线","沿胸骨旁线内侧所作的垂线","沿锁骨中线所作的垂线","经腹股沟韧带中点向上所作的垂线"],"a":1,"e":"胸骨线为沿胸骨最宽处外侧缘所作的垂直线。胸骨旁线则经胸骨线与锁骨中线之间连线的中点。"},{"q":"下列肌中，使肩关节外展的是","o":["三角肌","大圆肌","斜方肌","前锯肌","肩胛下肌"],"a":0,"e":"三角肌起自锁骨外侧1/3、肩峰和肩胛冈，止于肱骨三角肌粗隆，主要作用为使肩关节外展。肩胛下肌使肩关节内收、旋内。"},{"q":"关于桡骨的描述，正确的是","o":["桡骨位于尺骨的外侧","上端有冠突","上端有鹰嘴","下端较小","下端有桡切迹"],"a":0,"e":"桡骨位于前臂外侧，即尺骨的外侧。冠突与鹰嘴均为尺骨上端结构，桡切迹位于尺骨。"},{"q":"关于上肢浅静脉的叙述正确的是","o":["头静脉沿前臂尺侧上行","贵要静脉注入肘正中静脉","头静脉沿肱二头肌内侧沟上行","肘正中静脉是浅静脉","肘正中静脉注入头静脉"],"a":3,"e":"肘正中静脉属于上肢浅静脉，通常在肘窝处连接头静脉和贵要静脉。头静脉沿前臂桡侧上行，贵要静脉沿尺侧上行。"},{"q":"支配瞳孔开大肌的节前神经元的胞体位于","o":["颈上神经节","颈胸神经节","T1～2节段的前角细胞","T1～2节段的侧角细胞","T1～2节段的后角细胞"],"a":3,"e":"交感神经节前神经元胞体位于脊髓T1～L3节段中间带外侧核（侧角），支配瞳孔开大肌的节前纤维起自T1～T2节段侧角，在颈上神经节换元。颈上神经节为节后神经元胞体所在。"},{"q":"骶管麻醉的穿刺部位是","o":["骶角","骶管裂孔","骶前孔","骶后孔","骶岬"],"a":1,"e":"骶管麻醉常以骶角作为定位标志，经骶管裂孔穿刺进入骶管。骶管裂孔为骶管下端的裂孔，两侧有向下突出的骶角，故穿刺部位是骶管裂孔。"},{"q":"关于甲状腺的描述，错误的是","o":["吞咽时甲状腺可随喉上、下移动","甲状腺峡常有向上伸出的锥状叶","甲状腺素的主要作用是促进新陈代谢","甲状腺左、右叶贴于喉下部和气管颈部的前外侧","甲状腺峡位于第5～6气管软骨前方"],"a":4,"e":"甲状腺峡位于第2～4气管软骨环前方，连接左、右侧叶，并非第5～6气管软骨环前方。甲状腺借假被膜形成的悬韧带固定于喉和气管壁，吞咽时随喉上、下移动。"},{"q":"连结椎体的结构是","o":["后纵韧带","黄韧带","棘上韧带","棘间韧带","关节突关节"],"a":0,"e":"椎体间借椎间盘及前、后纵韧带相连，后纵韧带位于椎管内椎体后面，属连结椎体的结构。黄韧带、棘上韧带、棘间韧带和关节突关节均属椎弓间连结。"},{"q":"男性生殖腺是","o":["睾丸","附睾","前列腺","精囊","肾上腺"],"a":0,"e":"睾丸是男性生殖腺，产生精子和分泌雄激素。附睾、输精管属生殖管道，前列腺、精囊属附属腺，肾上腺为内分泌腺。"},{"q":"不属于腹膜间位器官的是","o":["子宫","肝","胆","升结肠","横结肠"],"a":4,"e":"横结肠属腹膜内位器官，由横结肠系膜连于腹后壁，活动度较大。子宫、肝、胆、升结肠均为腹膜间位器官。"},{"q":"关于子宫动脉的描述中何者有误","o":["发自髂内动脉","行于子宫阔韧带两层之间","在距子宫颈外侧约2cm处输尿管跨过其前方","供应子宫、卵巢、输卵管等","与卵巢动脉的分支吻合"],"a":2,"e":"子宫动脉在子宫颈外侧约2cm处从输尿管的前方跨过，即输尿管从其后方绕过，而非输尿管跨过其前方。子宫动脉发自髂内动脉，行于子宫阔韧带两层之间，供应子宫、卵巢、输卵管并与卵巢动脉分支吻合。"},{"q":"躯干和四肢意识性本体感觉传导通路的第2级神经元是","o":["三叉神经脑桥核","三叉神经脊束核","脊髓后角细胞","脊髓前角运动细胞","薄束核和楔束核"],"a":4,"e":"躯干和四肢意识性本体感觉传导通路的第2级神经元胞体位于薄束核和楔束核，由此二核发出纤维交叉形成内侧丘系。三叉神经核传递头面部感觉，脊髓后角、前角细胞不参与该通路。"},{"q":"在中耳鼓室内，听小骨由外向内依次是","o":["锤骨 镫骨 砧骨","锤骨 砧骨 镫骨","镫骨 锤骨 砧骨","镫骨 砧骨 锤骨","砧骨 锤骨 镫骨"],"a":1,"e":"听小骨链由外向内依次为锤骨、砧骨、镫骨：锤骨柄附于鼓膜，砧骨长脚与镫骨头形成砧镫关节，镫骨底封闭前庭窗，将声波振动传入内耳。"},{"q":"肾的被膜从内向外依次为","o":["脂肪囊 纤维囊 肾筋膜","肾筋膜 脂肪囊 纤维囊","纤维囊 脂肪囊 肾筋膜","纤维囊 肾筋膜 脂肪囊","肾筋膜 纤维囊 脂肪囊"],"a":2,"e":"肾的被膜由内向外依次为纤维囊、脂肪囊和肾筋膜。纤维囊紧贴肾实质表面，脂肪囊位于纤维囊外周，肾筋膜包被于脂肪囊外面。"},{"q":"角膜和虹膜之间的腔隙称","o":["眼球后房","眼球前房","虹膜角膜角","虹膜角膜角隙","前房角"],"a":1,"e":"虹膜将眼房分为前房和后房，角膜与虹膜之间的腔隙为眼球前房。虹膜角膜角是前房周边的环形区域，并非腔隙本身。"},{"q":"用来描述空腔脏器的方位术语是","o":["内、外","内侧、外侧","近侧、远侧","深、浅","近端、远端"],"a":0,"e":"内、外是描述体腔或空腔器官相互位置关系的术语，近内腔者为内。内侧、外侧用于描述与正中矢状面的位置关系，二者含义不同。"},{"q":"卵巢位于","o":["盆腔中央","盆腔前壁","盆腔后壁","盆腔侧壁","盆膈上面"],"a":3,"e":"卵巢位于盆腔卵巢窝内，相当于髂内、外动脉夹角处的骨盆外侧壁。卵巢为成对生殖腺，不属于盆腔中央或前后壁结构。"},{"q":"支配肱三头肌的神经为","o":["正中神经","尺神经","桡神经","肌皮神经","腋神经"],"a":2,"e":"桡神经发自臂丛后束，其肌支主要分布于肱三头肌、肘肌、肱桡肌和桡侧腕长伸肌。桡神经沿桡神经沟绕肱骨中段后面下行。"},{"q":"关于肱骨内上髁形态的描述，正确的是","o":["活体不能触及","位于肱骨头的内侧","后下有尺神经沟","呈半球形","与解剖颈相接"],"a":2,"e":"肱骨内上髁后方的浅沟称尺神经沟，尺神经由此经过。内上髁位于肱骨下端内侧，活体可触及，并非半球形。"},{"q":"关于胸导管的描述，正确的是","o":["注入左静脉角","行于胸主动脉后方","由右腰干和肠干合成","收纳身体右侧半淋巴","经膈的食管裂孔入胸腔"],"a":0,"e":"胸导管起自乳糜池，经主动脉裂孔入胸腔，沿胸主动脉右后方上行，注入左静脉角，收纳全身约3/4部位的淋巴。乳糜池接受左、右腰干和肠干。"},{"q":"连通第三脑室与第四脑室的结构是","o":["正中孔","外侧孔","中脑水管","室间孔","终池"],"a":2,"e":"第三脑室后经中脑水管通第四脑室。室间孔连通侧脑室与第三脑室，正中孔和外侧孔使第四脑室与蛛网膜下隙相通。"},{"q":"关于十二指肠悬肌(Treitz韧带)的说法，错误的是","o":["是腹部手术中确认空肠起始的重要标志","由肌组织和结缔组织构成","下端附于十二指肠空肠曲","是区分十二指肠水平部与升部的标志","对十二指肠空肠曲有悬吊、固定的作用"],"a":3,"e":"Treitz韧带由十二指肠悬肌及其表面腹膜皱襞构成，连于十二指肠空肠曲，对十二指肠空肠曲起悬吊固定作用，是腹部手术中确认空肠起始的重要标志。区分十二指肠水平部与升部的标志是十二指肠空肠曲本身，而非该韧带。"},{"q":"对输尿管的描述，错误的是","o":["起自肾盂","开口于膀胱","在小骨盆上缘处，跨过髂血管的后方","有三个生理狭窄","由平滑肌构成"],"a":2,"e":"输尿管起自肾盂，经小骨盆上口处跨过髂血管的前方，而非后方，此处为第二狭窄。输尿管由平滑肌构成，开口于膀胱，全长有三处生理狭窄。"},{"q":"第Ⅲ对脑神经为","o":["滑车神经","动眼神经","三叉神经","展神经","视神经"],"a":1,"e":"脑神经按与脑相连部位先后以罗马数字编号，第Ⅲ对为动眼神经，含一般躯体运动纤维和副交感纤维，支配眼球外肌及瞳孔括约肌、睫状肌。滑车神经为第Ⅳ对，三叉神经为第Ⅴ对。"},{"q":"血管吻合的最常见方式是","o":["动脉通过毛细血管与静脉吻合","动脉与动脉之间的吻合","静脉与静脉之间的吻合","动静脉短路","侧支吻合"],"a":0,"e":"血管吻合最常见的形式是动脉经毛细血管与静脉相通连，即微循环通路。动脉间、静脉间及动静脉间吻合为补充形式，静脉吻合较动脉丰富。"},{"q":"关于肩胛骨正确的描述是","o":["关节盂位于肩胛骨内侧缘","肩胛上角平第3肋","肩胛下角平第7肋","肩胛冈的内侧端构成肩峰","肩胛下窝位于肩胛冈下方"],"a":2,"e":"肩胛下角平对第7肋，是背部计数肋骨的骨性标志。关节盂位于肩胛骨外侧角，肩胛上角平第2肋，肩峰为肩胛冈外侧端延续，肩胛下窝位于肩胛骨前面。"},{"q":"支配肱二头肌的神经为","o":["正中神经","尺神经","桡神经","肌皮神经","腋神经"],"a":3,"e":"肌皮神经自臂丛外侧束发出后斜穿喙肱肌，分支支配喙肱肌、肱二头肌和肱肌，并延续为前臂外侧皮神经。正中神经、尺神经、桡神经均不支配肱二头肌。"},{"q":"参与组成小网膜的韧带是","o":["肝胃韧带","胃结肠韧带","肝镰状韧带","脾胃韧带","肝圆韧带"],"a":0,"e":"小网膜由肝胃韧带和肝十二指肠韧带组成，前者连于肝门与胃小弯，后者连于肝门与十二指肠上部。胃结肠韧带属胃的韧带，肝镰状韧带、肝圆韧带为肝的韧带。"},{"q":"下面有关跟腱的描述，正确的是","o":["是胫骨后肌的肌腱","止于跟骨结节","是小腿后肌群共同汇合点","断裂后踝关节不能背屈","断裂后足不能外翻"],"a":1,"e":"跟腱由腓肠肌和比目鱼肌的肌腱合成，止于跟骨结节。跟腱断裂后踝关节不能跖屈，足外翻由腓骨肌完成，与跟腱无关。"},{"q":"十二指肠的动脉供应来自","o":["胃网膜左动脉","胃网膜右动脉","胰十二指肠上前、后动脉","胰十二指肠下前、后动脉","胰十二指肠上前、后动脉与胰十二指肠下前、后动脉"],"a":4,"e":"十二指肠由胰十二指肠上前、后动脉与胰十二指肠下前、后动脉共同供血，二者在胰头与十二指肠之间吻合。胃网膜右动脉属胃十二指肠动脉分支，主要营养胃大弯侧。"},{"q":"以下对视神经的描述，错误的是","o":["为第Ⅱ对脑神经","穿经圆孔入颅","由视网膜节细胞的轴突构成","由特殊躯体感觉纤维组成","一侧视神经损伤出现同侧视野全盲"],"a":1,"e":"视神经为第Ⅱ对脑神经，属特殊躯体感觉纤维，由视网膜节细胞轴突构成，经视神经管入颅，损伤后同侧视野全盲。经圆孔入颅的是上颌神经。"},{"q":"受肌皮神经支配的骨骼肌为","o":["肱三头肌","肱二头肌","三角肌","小圆肌","背阔肌"],"a":1,"e":"肱二头肌属臂前群屈肌，由肌皮神经支配，作用为屈肘关节并使前臂旋后。肱三头肌由桡神经支配，三角肌、小圆肌由腋神经支配。"},{"q":"枕额肌的作用是","o":["皱额","皱眉","提上脸","皱枕部头皮","睁眼"],"a":0,"e":"枕额肌额腹止于眉部皮肤，收缩时提眉并使额部皮肤出现皱纹。皱眉由皱眉肌完成，眼轮匝肌睑部收缩使眼裂闭合。"},{"q":"收缩时使额部皮肤出现皱纹的肌肉是","o":["枕额肌","颊肌","眼轮匝肌","口轮匝肌","翼内肌"],"a":0,"e":"枕额肌额腹收缩可提眉并使额部皮肤出现皱纹，枕腹收缩向后牵拉帽状腱膜。眼轮匝肌、口轮匝肌分别闭合眼裂、口裂。"},{"q":"呈乳白色的眼球纤维膜是","o":["角膜","巩膜","虹膜","脉络膜","视网膜"],"a":1,"e":"巩膜占眼球纤维膜后5/6，呈乳白色不透明，厚而坚韧，有保护眼球内容物和维持眼球形态的作用。角膜无色透明，不呈乳白色。"},{"q":"下列关于精囊的描述，正确的是","o":["位于膀胱底后面，输精管壶腹内侧","是一对长椭圆形器官，表面平滑","具有贮存精子的作用","其排泄管与输精管壶腹的下端汇合成射精管","是男性结扎的常用部位"],"a":3,"e":"精囊为长椭圆形囊状器官，位于膀胱底后方、输精管壶腹下外侧，其排出管与输精管壶腹末端汇合成射精管。输精管才是男性结扎的常用部位。"},{"q":"供应胸腹壁的动脉中没有","o":["肋间后动脉、肋间前动脉","肋下动脉、肌膈动脉","腹壁上动脉、腹壁下动脉","膈下动脉、腰动脉","骶外侧动脉、闭孔动脉"],"a":4,"e":"胸腹壁由肋间后动脉、肋间前动脉、肋下动脉、肌膈动脉、腹壁上动脉、腹壁下动脉及膈下动脉、腰动脉等供血。骶外侧动脉供应盆壁，闭孔动脉供应股内侧群肌，不参与胸腹壁供血。"},{"q":"下面有关腓肠肌的描述，正确的是","o":["使踝关节背屈、足内翻","使踝关节跖屈、足内翻","使踝关节跖屈、足外翻","能屈膝关节和背屈踝关节","屈膝关节并使足跖屈"],"a":4,"e":"腓肠肌起自股骨内、外上髁后面，止于跟骨结节，可屈膝关节并使踝关节跖屈。背屈踝关节由小腿前群肌完成，足内翻、外翻分别由胫骨后肌、腓骨长短肌完成。"},{"q":"有关节唇的关节是","o":["肘关节","桡腕关节","髋关节","膝关节","距小腿关节"],"a":2,"e":"髋关节的髋臼周缘有髋臼唇加深关节窝，属有唇的关节。膝关节有半月板而无关节唇，肩关节虽有盂唇但选项中未列，肘、桡腕、距小腿关节均无关节唇。"},{"q":"关于颈内静脉，下列描述中正确的是","o":["在颈静脉孔处续于乙状窦","在卵圆孔处续于乙状窦","在圆孔处续于乙状窦","在颈静脉孔处续于横窦","在颈静脉孔处续于直窦"],"a":0,"e":"乙状窦位于乙状窦沟内，向前下在颈静脉孔处出颅续为颈内静脉。卵圆孔、圆孔为三叉神经分支通过处，横窦、直窦不直接延续为颈内静脉。"},{"q":"阑尾根部的体表投影是","o":["脐与右髂前上棘连线的中、内1/3交点处","脐与右髂前上棘连线的中、外1/3交点处","脐与右髂前下棘连线的中、外1/3交点处","两侧髂结节连线的中、右1/3交点处","两侧髂前上棘连线中点处"],"a":1,"e":"阑尾根部体表投影为右髂前上棘与脐连线的中、外1/3交点，即McBurney点。Lanz点位于左、右髂前上棘连线右、中1/3交点，为另一常用定位点。"},{"q":"以下对眼神经的描述，错误的是","o":["其分支泪腺神经含有来自面神经的副交感纤维控制泪腺分泌","额神经为眼神经的分支","为三叉神经的分支之一","经眶上裂入眶","为混合性神经"],"a":4,"e":"眼神经为三叉神经第1支，属感觉性神经，经眶上裂入眶，分支有泪腺神经、额神经等。泪腺神经含面神经副交感纤维，管理泪腺分泌。"},{"q":"不能做环转运动的关节是","o":["肩关节","桡腕关节","掌指关节","髋关节","膝关节"],"a":4,"e":"环转运动要求关节具有额状轴和矢状轴两个运动轴。膝关节为屈戌关节，仅能屈伸及半屈位时少许旋转，不能环转；肩、髋、桡腕及掌指关节均可环转。"},{"q":"有关膀胱的描述，正确的是","o":["膀胱各部之间界限明显","充盈时呈卵圆形","膀胱尖朝向前下方","膀胱尖的内面有一膀胱三角","肌层由横纹肌构成"],"a":1,"e":"膀胱充盈时呈卵圆形，空虚时呈锥体形。膀胱三角位于膀胱底内面而非膀胱尖，膀胱尖朝向前上方，肌层为平滑肌。"},{"q":"射精管开口于","o":["膀胱三角内","前列腺实质内","尿道前列腺部","尿道膜部","尿道海绵体部"],"a":2,"e":"射精管由输精管末端与精囊排出管汇合而成，穿前列腺实质，开口于尿道前列腺部后壁的精阜。前列腺输出管开口于尿道前列腺部后壁尿道嵴两侧。"},{"q":"男性尿道可分为","o":["前列腺部、膜部和球部","前列腺部、膜部和海绵体部","前列腺部、膜部、球部和海绵体部","壁内部、膜部和海绵体部","膜部、球部和海绵体部"],"a":1,"e":"男性尿道分前列腺部、膜部和海绵体部三部分，起自尿道内口止于尿道外口。球部是海绵体部在尿道球内的膨大，并非独立分部。"},{"q":"有系膜相连的器官","o":["回肠","盲肠","升结肠","降结肠","直肠"],"a":0,"e":"空肠和回肠被肠系膜悬系于腹后壁，合称系膜小肠，回肠属系膜小肠，有系膜相连。盲肠、升结肠、降结肠和直肠均为腹膜间位或腹膜外位器官，无系膜。"},{"q":"关于肋正确的描述是","o":["上6对肋直接与胸骨相连，故称真肋","呈长条形，属长骨","第8～12肋组成肋弓","肋结节与椎体肋凹相关节","第2肋平对胸骨角"],"a":4,"e":"胸骨角两侧平对第2肋软骨，是计数肋的重要标志。上6对肋借肋软骨直接连于胸骨称真肋；肋属扁骨；第8～10肋软骨构成肋弓；肋结节与胸椎横突肋凹相关节。"},{"q":"黄骨髓存在于","o":["所有骨的内部","幼儿长骨骨干内部","成人长骨骨干内部","幼儿长骨骨骺内部","成人扁骨内部"],"a":2,"e":"5岁以后长骨骨干内的红骨髓逐渐被脂肪组织代替，呈黄色，称黄骨髓。胎儿和幼儿骨髓均为红骨髓，扁骨及长骨骺内终身存在红骨髓。"},{"q":"关于喉的描述，错误的是","o":["位于颈前部正中","喉以软骨为支架","上部借韧带和肌与舌骨相连","声门裂是喉腔内最狭窄的部位","既是呼吸道，又是味觉器官"],"a":4,"e":"喉既是呼吸的管道，又是发音的器官，并非味觉器官。喉位于颈前部正中，以喉软骨为支架，上部借韧带和肌与舌骨相连，声门裂为喉腔最狭窄处。"},{"q":"男性尿道的第二个狭窄位于","o":["尿道内口","尿道外口","尿道前列腺部","尿道膜部","尿道海绵体部"],"a":3,"e":"男性尿道有三个狭窄，依次为尿道内口、尿道膜部和尿道外口，第二个狭窄即尿道膜部。尿道外口最窄，呈矢状裂隙。"},{"q":"脑干内，接受味觉纤维的神经核是","o":["疑核","孤束核","舌下神经核","舌咽神经核","面神经核"],"a":1,"e":"孤束核上部（头段）为特殊内脏感觉核，接受来自味蕾的味觉传入纤维。疑核为特殊内脏运动核，舌下神经核为躯体运动核。"},{"q":"下列直接汇入下腔静脉的静脉是","o":["脾静脉","肝门静脉","肝静脉","肠系膜上静脉","肠系膜下静脉"],"a":2,"e":"肝左、中、右静脉在腔静脉沟处直接注入下腔静脉。脾静脉、肠系膜上静脉和肠系膜下静脉汇合成肝门静脉，肝门静脉入肝后经肝静脉回流。"},{"q":"咽腔的通道有几个","o":["4","5","6","7","8"],"a":3,"e":"咽腔有7个通道：向前经鼻后孔通鼻腔，经咽鼓管咽口通鼓室，经咽口通口腔，经喉口通喉腔，向下续食管。"},{"q":"关于骨的描述，错误的是","o":["成人骨共有206块，其中6块听小骨属于感觉器","骨按部位可分为长骨、短骨、扁骨、不规则骨","骨的表面常有有突起、凹陷、膨大等形态结构","骨主要由骨质、骨膜和骨髓构成","骨由有机质和无机质构成"],"a":1,"e":"骨按部位分为颅骨、躯干骨和附肢骨；长骨、短骨、扁骨、不规则骨是按形态分类。"},{"q":"支配右下肢末端骨骼肌随意运动的大脑皮质区位于","o":["左半球中央前回下部","右半球中央前回下部","左半球中央旁小叶前部","右半球中央旁小叶前部","左半球中央前回中部"],"a":2,"e":"第Ⅰ躯体运动区上下颠倒、左右交叉，支配下肢的皮质位于中央旁小叶前部，右侧下肢受左侧半球支配。"},{"q":"收集头颈部的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":1,"e":"颈干由颈外侧下深淋巴结输出淋巴管合成，收集头颈部淋巴，左侧注入胸导管、右侧注入右淋巴导管。"},{"q":"供应大脑半球外侧面的主要动脉是","o":["大脑前动脉","大脑中动脉","大脑后动脉","基底动脉","前交通动脉"],"a":1,"e":"大脑中动脉营养大脑半球外侧面大部分和岛叶，包括躯体运动区、躯体感觉区和语言中枢。"},{"q":"男性尿道最短的一部是","o":["尿道壁内部","尿道前列腺部","尿道膜部","尿道海绵体部","尿道球部"],"a":2,"e":"男性尿道分前列腺部、膜部和海绵体部，膜部穿尿生殖膈，长约1.2cm，为三部中最短者。"},{"q":"脑脊液产生于","o":["硬脑膜","软脑膜","蛛网膜","脉络丛","蛛网膜粒"],"a":3,"e":"脑脊液主要由脑室脉络丛产生，少量由室管膜上皮和毛细血管产生。"},{"q":"收肌结节位于","o":["胫骨上端内侧","胫骨上端外侧","股骨内上髁上方","股骨外上髁上方","股骨内上髁后方"],"a":2,"e":"收肌结节为股骨内上髁上方的小突起，是大收肌腱的附着处。"},{"q":"支配瞳孔括约肌的神经为","o":["眼神经","滑车神经","展神经","副神经","动眼神经"],"a":4,"e":"动眼神经中的副交感纤维经睫状神经节换元后，节后纤维经睫状短神经入眼球，支配瞳孔括约肌和睫状肌。眼神经为三叉神经分支，属感觉神经。"},{"q":"胸大肌收缩时","o":["臂外展和旋外","臂内收和旋内","臂外展和后伸","下降肋骨助呼气","臂内收和前屈"],"a":1,"e":"胸大肌起自锁骨内侧2/3、胸骨和第1～6肋软骨，止于肱骨大结节嵴，收缩时使肩关节内收和旋内，锁骨部还可使肩关节前屈。"},{"q":"最晚闭合的颅囟是","o":["前囟","后囟","乳突囟","蝶囟","枕囟"],"a":0,"e":"前囟最大，呈菱形，位于矢状缝与冠状缝相接处，于1～2岁时闭合；后囟、蝶囟和乳突囟均于生后不久闭合。"},{"q":"下列汇入颈内静脉的血管是","o":["耳后静脉","颈外静脉","头静脉","枕静脉","面静脉"],"a":4,"e":"面静脉起自内眦静脉，在面动脉后方下行，至舌骨大角附近注入颈内静脉。颈外静脉注入锁骨下静脉，头静脉注入腋静脉。"},{"q":"海马位于大脑哪个叶","o":["额叶","颞叶","顶叶","枕叶","岛叶"],"a":1,"e":"海马位于颞叶内侧面的海马旁回深部，属边缘叶的组成部分，与记忆功能相关。"},{"q":"下列结构中，位于阴囊内的是","o":["前列腺","精囊腺","附睾","射精管","海绵体"],"a":2,"e":"阴囊由肉膜形成阴囊中隔分为左右两腔，容纳睾丸、附睾及精索等；前列腺、精囊腺位于盆腔内，射精管穿前列腺。"},{"q":"股骨体后面的纵行骨嵴是","o":["大转子","股骨颈","粗线","臀肌粗隆","耻骨肌线"],"a":2,"e":"股骨体后面有纵行骨嵴称粗线，其上端分叉延续为臀肌粗隆和耻骨肌线，为肌肉附着处。"},{"q":"以下对前庭蜗神经描述错误的是","o":["其为第Ⅷ对脑神经","又称位听神经","其经内耳门入颅","蜗神经节由双极神经元组成","前庭神经传导听觉"],"a":4,"e":"前庭蜗神经为第Ⅷ对脑神经，又称位听神经，经内耳门入颅，由前庭神经和蜗神经组成；前庭神经传导平衡觉，蜗神经才传导听觉。"},{"q":"关于腮腺管的描述，正确的是","o":["发自腺的下缘","在颧弓下2横指处越过咬肌表面","穿咬肌开口于腮腺管乳头","开口于与上颌第2磨牙相对的颊黏膜处","开口于与上颌第1磨牙相对的颊黏膜处"],"a":3,"e":"腮腺管自腮腺浅部前缘发出，于颧弓下一横指处横越咬肌表面，至咬肌前缘弯向内侧斜穿颊肌，开口于平对上颌第二磨牙牙冠的颊黏膜腮腺管乳头。"},{"q":"下列结构，何项是肾皮质构成","o":["肾大盏","肾乳头","肾柱","肾盂","肾窦"],"a":2,"e":"伸入肾锥体之间的肾皮质称肾柱，属肾皮质结构。肾大盏、肾盂为排尿管道，肾乳头由肾锥体尖端构成，肾窦为肾门内的腔隙。"},{"q":"有关心的描述，何者为错","o":["为循环系统的动力器官","左半心的血富含氧气","右半心的血富含CO2","左、右心房以卵圆孔相通","左、右心室互不相通"],"a":3,"e":"卵圆窝是胚胎时期卵圆孔闭合后的遗迹，出生后左、右心房互不相通。左半心流动动脉血富含氧，右半心流动静脉血富含二氧化碳，左、右心室被室间隔隔开。"},{"q":"肝的右纵沟前部容纳的是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","动脉韧带"],"a":2,"e":"肝的右纵沟前部为胆囊窝，容纳胆囊；后部为腔静脉沟，容纳下腔静脉。肝圆韧带和静脉韧带分别位于左纵沟的前、后部。"},{"q":"双侧收缩使头后仰的肌肉是","o":["胸锁乳突肌","二腹肌","前斜角肌","肩胛舌骨肌","颈阔肌"],"a":0,"e":"胸锁乳突肌一侧收缩使头向同侧倾斜、脸转向对侧，两侧同时收缩使头后仰。二腹肌降下颌，前斜角肌提肋助吸气，肩胛舌骨肌降舌骨。"},{"q":"支配表情肌的神经核是","o":["疑核","孤束核","面神经核","展神经核","动眼神经核"],"a":2,"e":"面神经核发出特殊内脏运动纤维，支配全部表情肌及二腹肌后腹、茎突舌骨肌和镫骨肌。疑核支配咽喉肌，孤束核为内脏感觉核，展神经核与动眼神经核支配眼外肌。"},{"q":"关于颈内动脉，错误的是","o":["是颈总动脉的分支","在颅外没有分支","起始处膨大部是化学感受器","营养脑","营养视器"],"a":2,"e":"颈内动脉起始处膨大为颈动脉窦，窦壁外膜内富含压力感受器，感受血压变化；化学感受器是颈动脉小球。颈内动脉为颈总动脉分支，颅外无分支，营养脑和视器。"},{"q":"下列不属于硬脑膜窦的是","o":["上矢状窦","下矢状窦","海绵窦","乙状窦","冠状窦"],"a":4,"e":"冠状窦属心的静脉系统，收集心大、中、小静脉，注入右心房，不属硬脑膜窦。上矢状窦、下矢状窦、海绵窦、乙状窦均为颅内硬脑膜窦。"},{"q":"肺下界在锁骨中线处相交于","o":["第6肋","第7肋","第8肋","第9肋","第10肋"],"a":0,"e":"肺下缘在锁骨中线处与第6肋相交，腋中线处与第8肋相交，肩胛线处与第10肋相交。肺下界一般较胸膜下界高出约两个肋的距离。"},{"q":"关于右心房描述正确的是","o":["参与构成心的右侧缘","有四入口和一出口","壁厚而腔小","出生以后可见卵圆孔","向右前方突出形成右心耳"],"a":0,"e":"右心房构成心的右缘，即右上点与右下点之间微向右凸的弧形连线。右心房壁薄而腔大，接受上、下腔静脉和冠状窦等入口，经右房室口通向右心室。"},{"q":"属于腹膜内位器官的是","o":["胃","膀胱","升结肠","降结肠","输尿管"],"a":0,"e":"胃属于腹膜内位器官，表面几乎全部被腹膜覆盖。膀胱为腹膜间位器官，升结肠、降结肠亦属腹膜间位器官，输尿管为腹膜外位器官。"},{"q":"关于脑的静脉，以下说法错误的是","o":["一般不与动脉伴行","有瓣膜","分为浅、深两组","浅组收集皮质的静脉血","经硬脑膜窦回流"],"a":1,"e":"脑的静脉不与动脉伴行，内无瓣膜，分为浅、深两组，浅组收集大脑皮质静脉血，最终经硬脑膜窦回流。"},{"q":"属于混合性的神经为","o":["耳大神经","颈横神经","枕小神经","锁骨上神经","膈神经"],"a":4,"e":"膈神经由第3～5颈神经前支组成，含运动纤维和感觉纤维，属混合性神经。耳大神经、颈横神经、枕小神经、锁骨上神经均为颈丛皮支，属感觉性神经。"},{"q":"下丘脑的主要功能不包括","o":["皮质下内脏活动调节","随意运动调节","体温调节","昼夜节律调节","摄食行为调节"],"a":1,"e":"下丘脑是神经-内分泌调控中心和内脏活动的高级调节中枢，参与体温、昼夜节律及摄食行为的调节。随意运动的调节主要由锥体系和小脑完成。"},{"q":"不属于髋骨体表标志的是","o":["髂前上棘","髂窝","耻骨结节","髂结节","坐骨结节"],"a":1,"e":"髂窝为髂骨翼内面的浅窝，属骨性凹陷而非体表可触及的标志。髂前上棘、髂结节、耻骨结节和坐骨结节均可在体表扪及。"},{"q":"与上颌磨牙邻近的鼻旁窦是","o":["额窦","上颌窦","蝶窦","筛窦前、中小房","筛窦后小房"],"a":1,"e":"上颌窦底为上颌骨牙槽突，与第一、二磨牙及第二前磨牙根部紧邻，仅隔薄层骨质，故牙病与上颌窦炎可相互累及。"},{"q":"颅内压增高时，以个哪个结构最有可能被挤入小脑幕切迹与中脑之间而形成脑疝","o":["小脑蚓","小脑扁桃体","小脑下脚","颞横回","海马旁回"],"a":4,"e":"海马旁回位于小脑幕切迹上方，颅内压增高时向下移位入切迹与中脑之间，形成小脑幕切迹疝并压迫大脑脚和动眼神经。小脑扁桃体疝入枕骨大孔，属小脑扁桃体疝。"},{"q":"关于左心房描述正确的是","o":["构成心底","入口为肺动脉口","出口周围有三尖瓣","向左前突出为左心耳","后方无食管通过"],"a":0,"e":"左心房构成心底的大部，是四个心腔中最靠后的腔。左心耳是左心房前部向左前突出的部分，肺静脉口为其入口，出口通向左心室。"},{"q":"下列关于肌形态和构造的描述，错误的是","o":["骨骼肌包括肌腹和肌腱两部分","四肢骨骼肌多为短肌","肌腹主要由肌纤维组成","肌腱由胶原纤维组成","肌腹一般以肌腱附着于骨"],"a":1,"e":"长肌肌束与肌长轴平行，收缩时显著缩短，引起大幅度运动，多见于四肢。骨骼肌由肌腹和肌腱构成，肌腹由肌纤维组成，肌腱由胶原纤维构成。"},{"q":"关于腋动脉的描述，错误的是","o":["在第1肋外侧缘接锁骨下动脉","在大圆肌下缘续肱动脉","在腋窝内被臂丛三束包裹","其内侧有同名静脉伴行","腋动脉没有分支到胸大肌"],"a":4,"e":"腋动脉发出胸肩峰动脉、胸外侧动脉等分支，分布于胸大肌、胸小肌等。腋动脉在第1肋外侧缘续锁骨下动脉，于大圆肌下缘续肱动脉，在腋窝内被臂丛三束包围。"},{"q":"关于胸椎叙述正确的是","o":["关节突呈矢状位","椎体小","椎孔最大","有肋凹","棘突呈方板状"],"a":3,"e":"胸椎椎体两侧有肋凹，与肋头相关节，为其特征性结构。胸椎椎体较大，椎孔较小，棘突长而向后下方倾斜，关节突呈冠状位。"},{"q":"使瞳孔扩大的肌是","o":["眼轮匝肌","瞳孔开大肌","瞳孔括约肌","内直肌","上睑提肌"],"a":1,"e":"瞳孔开大肌呈放射状排列于虹膜内，受交感神经支配，收缩时开大瞳孔。瞳孔括约肌呈环形排列，受动眼神经副交感纤维支配，收缩时缩小瞳孔。"},{"q":"感光最敏锐之处是","o":["黄斑","中央凹","视神经盘","视神经乳头","虹膜"],"a":1,"e":"中央凹位于黄斑中央，由密集视锥细胞构成且无血管，为感光最敏锐处。视神经盘无感光细胞，称生理性盲点。"},{"q":"房水产生过多，可造成眼内压升高，压迫视网膜，影响视力称","o":["白内障","麦粒肿","霰粒肿","青光眼","沙眼"],"a":3,"e":"房水回流受阻或产生过多使眼压升高，压迫视网膜影响视力，称青光眼。晶状体混浊为白内障，睑腺炎为麦粒肿。"},{"q":"关于脑膜中动脉的描述正确的是","o":["是分布到脑的动脉之一","是颈外动脉的直接分支","穿卵圆孔入颅腔","发自上颌动脉","翼点损伤时脑膜中动脉主干也会损伤"],"a":3,"e":"脑膜中动脉发自上颌动脉，经棘孔入颅，分布于硬脑膜。它是颈外动脉的间接分支，并非分布到脑的动脉，也不穿卵圆孔。"},{"q":"有关主动脉的描述何者有误","o":["是体循环的动脉主干","其内流动的是含C02量高的血液","全长分升主动脉、主动脉弓和降主动脉","末端在第4腰椎下缘分为左、右髂总动脉","起自左心室的主动脉口"],"a":1,"e":"主动脉是体循环的动脉主干，起自左心室，内流含氧量高的动脉血，全长分升主动脉、主动脉弓和降主动脉，末端平第4腰椎下缘分为左、右髂总动脉。"},{"q":"骶管麻醉的穿刺部位应在","o":["骶前孔","骶后孔","骶管裂孔","骶角","骶岬"],"a":2,"e":"骶管裂孔由第5骶椎及尾椎的椎弓板缺如形成，两侧可扪及骶角，是骶管麻醉的穿刺标志和进针部位。骶前、后孔有骶神经通过，非穿刺部位。"},{"q":"有关冠状窦的描述，错误的是","o":["位于心膈面的冠状沟内","心大静脉是其属支之一","收集心的全部静脉血","注入到右心房","有心中和心小静脉注入"],"a":2,"e":"心的静脉血绝大部分经冠状窦汇入右心房，但还有一部分直接流入右心房，故冠状窦并不收集心的全部静脉血。其属支包括心大、中、小静脉。"},{"q":"支配三角肌的神经为","o":["腋神经","正中神经","尺神经","桡神经","肌皮神经"],"a":0,"e":"腋神经发自臂丛后束，与旋肱后血管伴行穿四边孔，绕肱骨外科颈至三角肌深面，支配三角肌和小圆肌。肱骨外科颈骨折损伤腋神经可致三角肌瘫痪、方肩。"},{"q":"运动性语言中枢位于","o":["额中回","颞横回","缘上回","角回","Broca区"],"a":4,"e":"运动性语言中枢即Broca区，位于额下回后1/3部（44、45区），即三角部后部和岛盖部，损伤后出现运动性失语症。"},{"q":"支配心肌的副交感神经节前神经元的胞体位于","o":["孤束核","迷走神经背核","上泌涎核","脊髓骶部第2～4节段灰质的骶副交感核","脊髓T1～L3节段的侧角"],"a":1,"e":"支配心的副交感节前纤维起自延髓迷走神经背核，随迷走神经心支走行，在心丛内的心神经节换元后分布于心，兴奋时引起心动过缓。"},{"q":"无系膜的肠管是","o":["空肠","盲肠","阑尾","横结肠","乙状结肠"],"a":1,"e":"盲肠属腹膜内位器官，各面均有腹膜被覆，但无系膜或仅有短小系膜，位置相对固定。空肠、阑尾、横结肠、乙状结肠均有系膜。"},{"q":"下列结构属于鼓室后壁的是","o":["前庭窗","蜗窗","咽鼓管的开口","面神经管凸","乳突窦的开口"],"a":4,"e":"鼓室后壁即乳突壁，其上部有乳突窦的入口，鼓室借此连通乳突小房。前庭窗、蜗窗位于内侧壁，咽鼓管开口位于前壁，面神经管凸位于内侧壁。"},{"q":"下列关于脊髓的描述，正确的是","o":["中央管上直接通第三脑室","主要由灰质构成","灰质围绕在白质周围","白质可分为前索、外侧索和后索","网状结构位于两前角之间"],"a":3,"e":"脊髓白质借纵沟分为前索、外侧索和后索。中央管不通第三脑室，脊髓灰质位于中央、白质居外周，网状结构位于灰质后角基部。"},{"q":"有关肌的辅助装置的描述，正确的是","o":["浅筋膜又称固有筋膜","滑膜囊都独立存在","人体内长肌腱周围均有腱鞘","肌间隔和筋膜鞘均为深筋膜形成的结构","籽骨不是辅助结构"],"a":3,"e":"深筋膜插入肌群之间形成肌间隔，并与包被肌群的深筋膜共同构成筋膜鞘。浅筋膜为皮下组织，滑膜囊多与关节腔相通，腱鞘仅见于腕、踝、指趾等活动灵活处。"},{"q":"下列关于桡腕关节的叙述中，正确的是","o":["由桡、尺骨下端构成关节窝","由腕骨近侧列的手舟骨、月骨、三角骨和豌豆骨的近侧面组成关节头","关节囊的两侧有桡、尺侧副韧带加强","可做屈伸、收展和环转运动","关节内没有关节盘等辅助结构"],"a":3,"e":"桡腕关节由桡骨下端和尺骨头下方的关节盘构成关节窝，与手舟骨、月骨、三角骨构成关节头，可作屈伸、收展和环转运动。豌豆骨不参与构成关节头。"},{"q":"下列属于女性内生殖器的是","o":["阴阜","阴蒂","前庭大腺","小阴唇","前庭球"],"a":2,"e":"女性内生殖器由生殖腺（卵巢）、生殖管道（输卵管、子宫、阴道）和附属腺（前庭大腺）组成。阴阜、阴蒂、小阴唇、前庭球均属外生殖器。"},{"q":"肩胛下角约平对","o":["第2肋","第4肋","第5肋","第6肋","第7肋"],"a":4,"e":"肩胛下角为脊柱缘与腋缘会合处，平对第7肋或第7肋间隙，是背部计数肋骨的标志。上角平对第2肋。"},{"q":"成人肾门约平","o":["第11胸推体下缘","第12胸推体中份","第1腰椎体","第2腰椎体下缘","第3腰椎体中份"],"a":2,"e":"肾门约在第1腰椎椎体平面，相当于第9肋软骨前端高度，距后正中线约5cm。"},{"q":"有关迷走神经的叙述，错误的是","o":["为第Ⅹ对脑神经","属混合性神经","特殊内脏运动纤维支配咽喉肌","可分布于外耳道的皮肤","损伤后患者可出现心动过缓症状"],"a":4,"e":"迷走神经为第Ⅹ对脑神经，属混合性神经，其特殊内脏运动纤维支配咽喉肌，一般躯体感觉纤维分布于外耳道皮肤。迷走神经兴奋引起心动过缓，损伤后不出现心动过缓。"},{"q":"两肺根内的结构排列自前向后依次为","o":["上肺静脉、肺动脉和主支气管","肺动脉、上肺静脉和主支气管","肺动脉、主支气管和下肺静脉","上肺静脉、主支气管和肺动脉","主支气管、下肺静脉和肺动脉"],"a":0,"e":"肺根内结构自前向后依次为上肺静脉、肺动脉、主支气管和下肺静脉。教材明确两肺根结构排列自前向后为上肺静脉、肺动脉、主支气管和下肺静脉。"},{"q":"距小腿关节最不稳定的状态是","o":["足背屈","足跖屈","足内翻","足外翻","足背伸"],"a":1,"e":"距骨滑车前宽后窄，跖屈时较窄的滑车后部进入关节窝，足可作轻微侧方运动，关节不够稳定，故踝关节扭伤多发生在跖屈时。背屈时较宽的前部嵌入关节窝，关节稳定。"},{"q":"关于上腔静脉，下列描述正确的是","o":["入心前接受奇静脉","起自右腰升静脉","半奇静脉直接注入","注入左心房","由颈内静脉和锁骨下静脉汇合而成"],"a":0,"e":"奇静脉沿胸主动脉右侧上行，至第4胸椎高度向前勾绕右肺根上方注入上腔静脉，故上腔静脉入心前接受奇静脉。上腔静脉由左、右头臂静脉汇合而成，半奇静脉注入奇静脉而非直接注入上腔静脉。"},{"q":"下列哪块肌为主要呼吸肌","o":["胸大肌","膈肌","背阔肌","腹直肌","腹外斜肌"],"a":1,"e":"膈肌为主要的呼吸肌，收缩时穹窿下降，胸腔容积扩大以助吸气。胸大肌、背阔肌、腹直肌和腹外斜肌均非主要呼吸肌。"},{"q":"旧纹状体是指","o":["基底核","尾状核头","尾状核尾","豆状核的壳","苍白球"],"a":4,"e":"苍白球为较旧的结构，称旧纹状体；尾状核和壳是较新的结构，合称新纹状体。旧纹状体即苍白球。"},{"q":"运动上眼睑的肌是","o":["上睑提肌","眼轮匝肌","上直肌","下直肌","内直肌"],"a":0,"e":"上睑提肌起自视神经管前上方眶壁，止于上睑皮肤和上睑板，收缩时提上睑、开大眼裂，由动眼神经支配。眼轮匝肌睑部收缩闭合睑裂，上直肌、下直肌、内直肌均为运动眼球的肌。"},{"q":"食管第三个狭窄约平第几胸椎","o":["8","9","10","11","12"],"a":4,"e":"食管第三个狭窄位于食管裂孔处，约平第10胸椎水平，有食管和迷走神经通过。第一狭窄在起始处，第二狭窄在左主支气管跨越处。"},{"q":"下列属于男性附属腺的是","o":["睾丸","附睾","前列腺","肾上腺","前庭大腺"],"a":2,"e":"男性内生殖器由生殖腺（睾丸）、输精管道（附睾、输精管、射精管、男性尿道）和附属腺（精囊、前列腺、尿道球腺）组成，前列腺属附属腺。睾丸为生殖腺，附睾为输精管道，前庭大腺属女性生殖系统。"},{"q":"头面部浅感觉传导通路的第2级神经元是","o":["三叉神经节","脊神经节","侧角细胞","三叉神经脊束核和脑桥核","薄束核和楔束核"],"a":3,"e":"头面部浅感觉传导通路的第2级神经元胞体位于三叉神经脊束核和三叉神经脑桥核，前者接受痛温觉纤维，后者接受触压觉纤维。三叉神经节内为第1级假单极神经元胞体。"},{"q":"关于椎弓的说法，错误的是","o":["位于椎体的后方","呈半环状","与椎体共同围成椎孔","由一对椎弓板构成","相邻椎弓间有黄韧带"],"a":3,"e":"椎弓由一对椎弓根和一对椎弓板构成，并非仅由椎弓板构成。椎弓位于椎体后方，与椎体共同围成椎孔，相邻椎弓板间由黄韧带连结。"},{"q":"有关颈内动脉的描述，何者正确","o":["在环状软骨上缘发自颈总动脉","在颈部分支很少","经颈动脉管入颅前窝","经颈动脉管入颅中窝","分支营养脑的全部"],"a":3,"e":"颈内动脉经颈动脉管入颅，进入颅中窝，紧贴海绵窦内侧壁前行。颈内动脉在颈部无分支，并非分支很少。"},{"q":"有关室间隔的描述，何者错误","o":["分隔左、右心室","分膜部和肌部两部","膜部是缺损的好发部位","肌部内有心房肌","室间隔缺损占先天性心脏病约17、8%"],"a":3,"e":"室间隔肌部由心肌组织构成，分隔左、右心室，其内不含心房肌。室间隔分肌部和膜部，膜部为缺损好发部位。"},{"q":"支配瞳孔括约肌的脑神经核是","o":["动眼神经副核","动眼神经核","滑车神经核","展神经核","疑核"],"a":0,"e":"动眼神经副核发出副交感节前纤维随动眼神经至睫状神经节换元，节后纤维支配瞳孔括约肌和睫状肌。动眼神经核为躯体运动核，支配眼球外肌。"},{"q":"关于大网膜的描述，正确的是","o":["是双层腹膜结构","连于胃大弯与横结肠之间","内有脾动脉通过","包裹腹腔器官","右上缘有一网膜孔"],"a":1,"e":"大网膜是连于胃大弯与腹后壁之间的腹膜结构，其前两层连于胃大弯与横结肠之间形成胃结肠韧带。大网膜由四层腹膜构成，并非双层。"},{"q":"参与构成肋弓的肋软骨是","o":["第7～9肋软骨","第6～9肋软骨","第8～10肋软骨","第8～11肋软骨","第9～12肋软骨"],"a":2,"e":"第8～10对肋软骨前端不直接与胸骨相连，依次与上位肋软骨形成软骨连结，在剑突两侧构成肋弓。第11、12肋前端游离。"},{"q":"椎动脉的描述何者有误","o":["发自锁骨下动脉上壁","途经第1～6颈椎横突孔","经枕骨大孔入颅","分布于脑和脊髓","分布至脑的大部分"],"a":4,"e":"椎动脉发自锁骨下动脉，穿第1～6颈椎横突孔，经枕骨大孔入颅，分布于脑和脊髓，供应大脑后部、小脑及脑干等，并非分布至脑的大部分。"},{"q":"关于胃的位置，描述正确的是","o":["胃后壁邻膈、脾","中等充盈时，大部分位于腹上区","临床上胃触诊的部位在剑突下方","贲门位于第12胸椎体的左侧","胃前壁的左侧被肝左叶遮盖"],"a":2,"e":"胃前壁在剑突下方直接与腹前壁相贴，是临床胃触诊的部位。胃底邻膈和脾，贲门位于第11胸椎左侧，胃前壁左侧被肝左叶遮盖。"},{"q":"由四层腹膜形成的结构是","o":["肝十二指肠韧带","肝胃韧带","大网膜","子宫阔韧带","小网膜"],"a":2,"e":"大网膜由四层腹膜构成，前两层由胃和十二指肠上部前后腹膜向下延伸形成，后两层返折向上移行于腹后壁。小网膜、肝胃韧带和肝十二指肠韧带均为双层腹膜。"},{"q":"不含味蕾的结构是","o":["丝状乳头","轮廓乳头","软腭的黏膜上皮","叶状乳头","菌状乳头"],"a":0,"e":"丝状乳头内无味蕾，故无味觉功能。味蕾嵌于菌状乳头、轮廓乳头、叶状乳头及软腭、会厌等处黏膜上皮内。"},{"q":"以下对内脏感觉神经描述错误的是","o":["痛阈较低","定位不准","内脏感觉神经元的细胞形态也是假单极神经元","传导内脏感觉的脑神经节细胞的中枢突终止于孤束核","内脏感觉神经元的周围突是粗细不等的有髓或无髓纤维"],"a":0,"e":"内脏感觉纤维数目少且多为细纤维，痛阈较高，一般强度刺激不引起主观感觉。内脏感觉神经元胞体位于脑神经节和脊神经节内，为假单极神经元。"},{"q":"关于脾的描述，正确的是","o":["与右肾相邻","位于右季肋区","长轴与第10肋一致","位于右侧第9～11肋深面","正常情况下在肋弓下可触及脾脏"],"a":2,"e":"脾位于左季肋部，胃底与膈之间，第9～11肋深面，长轴与第10肋一致。正常时左肋弓下触不到脾。"},{"q":"对肾的描述，错误的是","o":["是泌尿器官","左肾低于右肾","有三层被膜","内侧缘中部有肾门","内部有肾窦"],"a":1,"e":"因受肝挤压，右肾低于左肾约1～2cm，左肾位置高于右肾。肾为泌尿器官，内侧缘中部有肾门，内部有肾窦，外被三层被膜。"},{"q":"下列关于脑脊液的描述，正确的是","o":["位于硬脊膜与蛛网膜之间","充满蛛网膜下腔","经室间孔流入硬脑膜窦","经蛛网膜流入下矢状窦","充满硬膜外隙"],"a":1,"e":"脑脊液充满脑室系统、蛛网膜下隙和脊髓中央管。蛛网膜下隙位于蛛网膜与软膜之间，脑脊液经蛛网膜粒渗入上矢状窦。"},{"q":"阑尾动脉来自","o":["中结肠动脉","回结肠动脉","右结肠动脉","空肠动脉","回肠动脉"],"a":1,"e":"阑尾动脉为回结肠动脉发出的分支，经回肠末端后方进入阑尾系膜，分支营养阑尾。回结肠动脉还营养回肠末端、盲肠和升结肠。"},{"q":"有关心的描述，错误的是","o":["心位于胸腔的中纵隔","心呈倒置的圆锥体","左右心房有卵圆孔相通","心包脏层构成心外膜","窦房结是特殊的心肌"],"a":2,"e":"卵圆孔在出生后闭合形成卵圆窝，左右心房互不相通，仅房间隔缺损时才有异常通道。心位于中纵隔，呈倒置圆锥体，心包脏层即心外膜，窦房结为特殊心肌构成。"},{"q":"眼动脉来自","o":["颈内动脉","颈外动脉","上颌动脉","面动脉","脑膜中动脉"],"a":0,"e":"眼动脉自颈内动脉发出，经视神经管入眶，供应眼球及眶内结构。上颌动脉、面动脉、脑膜中动脉均属颈外动脉分支。"},{"q":"使踝关节跖屈和足内翻的肌群是","o":["小腿前群","小腿后群","小腿外侧群","足底肌","足背肌"],"a":1,"e":"小腿后群肌包括小腿三头肌、胫骨后肌等，可跖屈踝关节并使足内翻。小腿前群使足背屈，外侧群使足外翻。"},{"q":"胫骨下端的主要骨性标志是","o":["内踝","胫骨粗隆","内侧髁","外侧髁","臀肌粗隆"],"a":0,"e":"胫骨下端向内下方突出形成内踝，可在体表扪及，为重要骨性标志。胫骨粗隆位于上端，内、外侧髁亦属上端结构。"},{"q":"属于腹膜间位器官的是","o":["脾","肝","胃","胰","肾"],"a":1,"e":"肝属腹膜间位器官，表面大部分被腹膜覆盖。脾、胃为腹膜内位器官，胰、肾为腹膜外位器官。"},{"q":"与面静脉交通的硬脑膜窦是","o":["上矢状窦","下矢状窦","海绵窦","乙状窦","直窦"],"a":2,"e":"面静脉经眼上、眼下静脉与海绵窦交通，且口角以上缺乏静脉瓣，面部感染可蔓延至海绵窦。上矢状窦、乙状窦、直窦不与面静脉直接交通。"},{"q":"淋巴干共有几条","o":["共5条","共6条","共7条","共8条","共9条"],"a":4,"e":"全身淋巴干共9条，即成对的腰干、支气管纵隔干、锁骨下干、颈干和不成对的肠干，汇合成胸导管和右淋巴导管。"},{"q":"下列关于卵巢的描述，正确的是","o":["下端与盆壁之间有卵巢悬韧带","上端与子宫之间有卵巢固有韧带","位于小骨盆腔内","后缘有卵巢系膜","为腹膜外位器官"],"a":2,"e":"卵巢位于小骨盆腔内，外侧面贴卵巢窝。卵巢悬韧带连于骨盆侧缘与卵巢上端，卵巢固有韧带连于子宫与卵巢下端，后缘有卵巢系膜。"},{"q":"不属于腹膜外位器官的是","o":["十二指肠水平部","肾","输尿管","输卵管","胰"],"a":3,"e":"输卵管属腹膜内位器官，其表面几乎全部被腹膜覆盖，故不属于腹膜外位器官。肾、输尿管、胰及十二指肠水平部均为腹膜外位器官。"},{"q":"关于主动脉叙述，错误的是","o":["起始于左心室的主动脉口","主动脉弓自右前方弯向左后方","自主动脉弓发出左、右头臂干","根据其行程可分为三部分","下端在第4腰椎高度分叉"],"a":2,"e":"主动脉弓上由右向左依次发出头臂干、左颈总动脉和左锁骨下动脉，左头臂干并不存在。主动脉起自左心室主动脉口，弓自右前弯向左后，下端平第4腰椎分叉。"},{"q":"关于垂体的描述，错误的是","o":["借漏斗连于下丘脑","位于蝶骨的垂体窝内","分腺垂体和神经垂体两部分","腺垂体分远侧部、结节部和中间部","神经垂体能分泌加压素(抗利尿素)和催产素"],"a":4,"e":"神经垂体本身不能合成激素，仅贮存并释放由视上核、室旁核合成的抗利尿激素和缩宫素。腺垂体分为远侧部、结节部和中间部，垂体借漏斗连于下丘脑并位于蝶骨垂体窝内。"},{"q":"在延髓腹侧面上部，紧邻前正中裂的隆起是","o":["薄束结节","楔束结节","锥体","橄榄","下丘"],"a":2,"e":"延髓腹侧面前正中裂两侧的纵行隆起为锥体，由皮质脊髓束纤维构成，其下端纤维交叉形成锥体交叉。橄榄位于锥体背外侧，薄束结节、楔束结节位于背侧。"},{"q":"对膀胱三角的描述，错误的是","o":["膀胱三角底的两端为输尿管的开口","膀胱三角的尖为尿道内口","膀胱三角区的黏膜常保持平滑状态","黏膜层与肌层紧密结合","具有丰富的黏膜下层"],"a":4,"e":"膀胱三角区黏膜层与肌层紧密相贴，缺乏黏膜下层，故黏膜常保持平滑。其底两端为输尿管口，尖为尿道内口。"},{"q":"关于小腿三头肌的描述，正确的是","o":["由腓骨长肌和比目鱼肌构成","比目鱼肌起自股骨内、外侧髁","以跟腱止于跟骨结节","主要作用是伸膝关节和使足跖屈","还可使足内翻"],"a":2,"e":"小腿三头肌由腓肠肌和比目鱼肌构成，两肌腱合成跟腱止于跟骨结节。比目鱼肌起自腓骨后面上部和胫骨比目鱼肌线，该肌可屈踝关节使足跖屈，并协助屈膝。"},{"q":"精索内含有","o":["射精管","输精管","附睾管","精曲小管","精囊排泄管"],"a":1,"e":"精索内主要有输精管、睾丸动脉、蔓状静脉丛、神经、淋巴管及腹膜鞘突残余等。射精管由输精管末端与精囊排出管汇合而成，位于前列腺内。"},{"q":"皮质下内脏活动中枢是","o":["背侧丘脑","后丘脑","下丘脑","上丘","下丘"],"a":2,"e":"下丘脑是调节交感与副交感活动的主要皮质下中枢，为内脏活动的高级调节中枢，兼神经-内分泌调控中心。背侧丘脑为感觉传导接替站，上丘、下丘属中脑。"},{"q":"声门裂位于","o":["两侧喉室之间","两侧声襞及杓状软骨基底部之间","两侧声韧带之间","两侧前庭襞之间","方形膜的下缘"],"a":1,"e":"声门裂是两侧声襞与杓状软骨底和声带突之间的裂隙，为喉腔最狭窄处。两侧前庭襞之间的裂隙称前庭裂，较声门裂宽。"},{"q":"下面哪个孔不位于颅中窝","o":["破裂孔","棘孔","颈静脉孔","圆孔","卵圆孔"],"a":2,"e":"颈静脉孔位于枕骨与颞骨岩部交界处，属颅后窝结构。破裂孔、棘孔、圆孔、卵圆孔均位于颅中窝。"},{"q":"呈双凸透镜状，有屈光作用的结构是","o":["晶状体","房水","角膜","玻璃体","虹膜"],"a":0,"e":"晶状体呈双凸透镜状，位于虹膜与玻璃体之间，借睫状小带连于睫状体，是眼屈光装置的重要部分。角膜虽亦屈光，但呈前凸后凹的透镜状而非双凸透镜状。"},{"q":"一侧内侧丘系传导的感觉信息主要是","o":["同侧躯干、四肢意识性深感觉和精细触觉","对侧躯干、四肢意识性深感觉和精细触觉","同侧躯干、四肢意识性浅感觉","对侧躯干、四肢意识性浅感觉","双侧听觉"],"a":1,"e":"内侧丘系由薄束核、楔束核发出的纤维交叉后形成，传导对侧躯干和四肢的意识性本体感觉及精细触觉。"},{"q":"发自臂丛后束的神经为","o":["肌皮神经","腋神经","正中神经","尺神经","前臂内侧皮神经"],"a":1,"e":"腋神经发自臂丛后束，与旋肱后血管伴行穿四边孔，支配三角肌和小圆肌。肌皮神经发自外侧束，正中神经发自内、外侧束，尺神经发自内侧束。"},{"q":"关于掌浅弓的描述何者有误","o":["位于掌腱膜的深面","位于掌腱膜的浅面","由桡动脉的掌浅支和尺动脉的终支组成","弓上发出指掌侧总动脉","掌浅弓与掌深弓互相吻合"],"a":1,"e":"掌浅弓由尺动脉末端与桡动脉掌浅支吻合而成，位于掌腱膜深面，弓上发出指掌侧总动脉，并与掌深弓吻合。"},{"q":"关于腹股沟韧带的叙述，下列正确的是","o":["位于两侧髂前上棘之间","由腹内斜肌腱膜构成","由腹外斜肌腱膜下缘卷曲增厚构成","为腹股沟管前壁","参与腹股沟管浅环的构成"],"a":2,"e":"腹股沟韧带由腹外斜肌腱膜下缘卷曲增厚、连于髂前上棘与耻骨结节之间而成。腹股沟管前壁为腹外斜肌腱膜和腹内斜肌，浅环由腹外斜肌腱膜裂孔形成。"},{"q":"大腿内收肌群受什么神经支配","o":["臀上神经","臀下神经","闭孔神经","股神经","阴部神经"],"a":2,"e":"大腿内侧群即内收肌群，包括耻骨肌、长收肌、短收肌、大收肌和股薄肌，主要由闭孔神经支配。股神经支配前群，坐骨神经支配后群。"},{"q":"直接连结与间接连结的最主要区别是","o":["连结的复杂程度","骨间有无间隙","骨间能否相互活动","骨间距离的远近","以上都不对"],"a":1,"e":"间接连结的骨面间互相分离并充以滑液，形成腔隙，而直接连结骨间无间隙，这是两者最主要的区别。间接连结因有腔隙而活动性大。"},{"q":"关于十二指肠大乳头的叙述，正确的是","o":["副胰管开口于大乳头","位于十二指肠降部的前壁中份","是十二指肠纵襞下端的圆形隆起","距中切牙约55cm","位于小乳头的上方"],"a":2,"e":"十二指肠大乳头是十二指肠纵襞下端的圆形隆起，为肝胰壶腹的开口处。副胰管开口于大乳头上方的小乳头，大乳头距中切牙约75cm。"},{"q":"下列关于精索的描述，正确的是","o":["起于附睾尾","远端连于膀胱底","内含有射精管","穿过腹股沟管","全长可分为四部"],"a":3,"e":"精索经腹股沟管深环进入腹股沟管，再经浅环穿出，故穿过腹股沟管。精索起于腹股沟管深环而非附睾尾，内含输精管而非射精管。"},{"q":"耻骨联合属于","o":["韧带连结","纤维连结","软骨连结","骨性结合","间接连结"],"a":2,"e":"耻骨联合是两侧耻骨联合面借纤维软骨构成的软骨连结。纤维连结以纤维结缔组织相连，骨性结合为骨组织相连。"},{"q":"下列关于皮质脊髓侧束的描述，正确的是","o":["支配对侧前角运动神经元","逐渐终于对侧板层Ⅳ～Ⅸ","所有纤维都终于中间神经元","在脊髓侧索前部下行","一侧损伤出现同侧肢体随意运动障碍"],"a":4,"e":"皮质脊髓侧束在延髓锥体交叉后下行于脊髓侧索，故一侧损伤引起同侧肢体随意运动障碍。该束大部分纤维经中间神经元接替，并非全部直接终止于前角运动神经元。"},{"q":"关于鼻腔，下列说法正确的是","o":["经鼻后孔通喉腔","鼻中隔由软骨构成","鼻腔被鼻中隔分为左、右两个腔","外侧壁有4个鼻道","中鼻甲下方是下鼻道"],"a":2,"e":"鼻腔被鼻中隔分为左、右两腔，向前经鼻孔通外界，向后经鼻后孔通鼻咽部。鼻中隔由犁骨、筛骨垂直板和鼻中隔软骨共同构成。"},{"q":"主要由神经元细胞体构成的结构是","o":["神经束","纤维束","神经核","白质","神经"],"a":2,"e":"神经核是灰质内聚集成群的神经细胞体，故主要由神经元细胞体构成。神经束、纤维束和白质主要由神经纤维构成。"},{"q":"右心室内有","o":["右心耳","梳状肌","二尖瓣","动脉韧带","乳头肌"],"a":4,"e":"右心室内有前、后、隔侧三群乳头肌，其尖端发出腱索连于三尖瓣。右心耳和梳状肌属右心房，二尖瓣位于左心室，动脉韧带位于肺动脉与主动脉之间。"},{"q":"直接发自椎动脉的动脉是","o":["小脑上动脑","大脑后动脉","后交通动脉","大脑中动脉","小脑下后动脉"],"a":4,"e":"小脑下后动脉是椎动脉的最大分支，在平橄榄下端附近发出，分布于小脑下面后部和延髓后外侧部。小脑上动脉发自基底动脉，大脑后动脉为基底动脉终支。"},{"q":"左心室舒张时","o":["二尖瓣开放","三尖瓣关闭","主动脉瓣开放","肺动脉瓣开放","右心室收缩"],"a":0,"e":"左心室舒张时，室内压低于左房压，二尖瓣开放使血液由左心房流入左心室；此时主动脉瓣关闭，防止血液反流。"},{"q":"位于眼球前方的眼副器是","o":["球结膜","角膜","巩膜","眼睑","外直肌"],"a":3,"e":"眼睑位于眼球前方，属眼副器，对眼球起保护作用。球结膜、角膜、巩膜均属眼球结构，外直肌为眼球外肌。"},{"q":"肺动脉干起始于","o":["左心室","右心室","左心房","右心房","毛细血管"],"a":1,"e":"肺动脉干起于右心室，输送静脉血至肺。升主动脉起于左心室，两者在胸肋面上交叉走行。"},{"q":"使瞳孔转向上内的肌是","o":["上直肌","上斜肌","下斜肌","下直肌","上睑提肌"],"a":0,"e":"上直肌起自总腱环，止于眼球赤道以前的巩膜，收缩时使瞳孔转向上内。上斜肌使瞳孔转向下外，下斜肌使瞳孔转向上外。"},{"q":"有关骨的构造，正确的说法是","o":["骨干由松质构成","骨骺由密质构成","骨膜有血管无神经","骨髓有神经无血管","骨膜过度缺损，影响骨折愈合"],"a":4,"e":"骨膜成骨功能在骨折时重新活跃以促进愈合，骨膜过度剥离或损伤则骨折愈合困难。骨干由密质构成，骨骺主要由松质构成，骨膜富含血管和神经。"},{"q":"限制脊柱过度后伸的韧带是","o":["前纵韧带","后纵韧带","黄韧带","棘间韧带","棘上韧带"],"a":0,"e":"前纵韧带位于椎体前面，宽而坚韧，牢固附着于椎体和椎间盘，防止脊柱过度后伸和椎间盘向前脱出。黄韧带则限制脊柱过度前屈。"},{"q":"关于胃后动脉描述正确的是","o":["分布至胃小弯","分布至胃大弯","分布至胃底","分布至胃的幽门部","分布至胃体后壁上部"],"a":4,"e":"胃后动脉在中1/3段发出，行于网膜囊后壁腹膜后面，经胃膈韧带至胃底，分布于胃体后壁上部。胃短动脉分布于胃底，胃网膜左动脉分布于胃大弯。"},{"q":"屈肘并协助屈肩关节的肌是","o":["旋前圆肌","旋后肌","肱二头肌","指深屈肌","指伸肌"],"a":2,"e":"肱二头肌可屈肘关节，其长头起自盂上结节，能协助肩关节前屈和内收。旋前圆肌、旋后肌、指深屈肌和指伸肌均不作用于肩关节。"},{"q":"鼻泪管开口于","o":["额窦","上颌窦","蝶窦","筛窦","下鼻道的外侧壁"],"a":4,"e":"鼻泪管下部在鼻腔外侧壁黏膜深面，开口于下鼻道外侧壁。鼻旁窦包括额窦、上颌窦、蝶窦和筛窦，均不接纳鼻泪管。"},{"q":"上消化道不包括","o":["十二指肠","口腔","胃","空肠","咽"],"a":3,"e":"上消化道指从口腔到十二指肠的消化管，包括口腔、咽、食管、胃和十二指肠。空肠以下的部分属下消化道。"},{"q":"右主支气管的特点是","o":["走向较水平","细而短","细而长","粗而长","粗而短"],"a":4,"e":"右主支气管粗而短，走行较陡直，异物易坠入右侧。左主支气管则细而长、斜行。"},{"q":"听觉中枢位于","o":["缘上回","角回","颞横回","额下回","扣带回"],"a":2,"e":"听区位于颞横回（41、42区），接受内侧膝状体发出的听辐射。缘上回和角回属联络区，额下回后部为运动性语言中枢。"},{"q":"具有屈髋关节和屈膝关节的肌是","o":["股直肌","缝匠肌","半腱肌","股二头肌","股四头肌"],"a":1,"e":"缝匠肌起自髂前上棘，止于胫骨上端内侧面，可屈髋关节和膝关节，并使已屈的膝关节旋内。股四头肌只屈髋伸膝，股二头肌和半腱肌伸髋屈膝。"},{"q":"以下属于内脏感觉神经核的是","o":["疑核","孤束核","舌下神经核","三叉神经脊束核","前庭神经核"],"a":1,"e":"孤束核接受面神经、舌咽神经和迷走神经的一般及特殊内脏感觉纤维，属内脏感觉核。疑核为特殊内脏运动核，三叉神经脊束核为躯体感觉核。"},{"q":"左心室的入口是","o":["右房室口","左房室口","肺动脉口","主动脉口","肺静脉口"],"a":1,"e":"左心室的入口为左房室口，口周二尖瓣环附有二尖瓣；出口为主动脉口。右房室口通右心室，肺静脉口开口于左心房。"},{"q":"关于腮腺，下列说法中正确的是","o":["是最大的消化腺","开口于口腔前庭","开口于舌下阜和舌下襞","有数条腮腺导管","开口于上颌第2磨牙"],"a":1,"e":"腮腺导管开口于平对上颌第2磨牙牙冠的颊黏膜，即口腔前庭。最大消化腺是肝，舌下腺开口于舌下阜和舌下襞，腮腺导管仅一条。"},{"q":"下列哪个Brodmann区是躯体感觉中枢（第一躯体感觉区）","o":["3，1，2区","4区","17区","22区","40区"],"a":0,"e":"第Ⅰ躯体感觉区位于中央后回和中央旁小叶后部，即Brodmann 3、1、2区。4区为第Ⅰ躯体运动区，17区为视区。"},{"q":"躯干和四肢痛温觉传导通路的第3级神经元是","o":["后角细胞","三叉神经脊束核","薄束核","丘脑腹后内侧核","丘脑腹后外侧核"],"a":4,"e":"躯干四肢痛温觉传导通路由3级神经元组成，第3级胞体位于背侧丘脑腹后外侧核，发出纤维投射至中央后回。薄束核为深感觉通路第2级神经元。"},{"q":"下面有关臀大肌的描述，正确的是","o":["只起自髂骨的外面","使髋关节后伸和外旋","使髋关节的前屈和外旋","能内旋大腿","属于大腿肌后群"],"a":1,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和臀肌粗隆，作用为使髋关节伸和旋外。该肌属髋肌后群，非大腿肌后群。"},{"q":"关于颈内静脉，下列描述错误的是","o":["与锁骨下静脉汇合成头臂静脉","由乙状窦延续而成","行于颈外动脉外侧","起于颈静脉孔","有颅内和颅外属支"],"a":2,"e":"颈内静脉在颈动脉鞘内沿颈内动脉和颈总动脉外侧下行，并非行于颈外动脉外侧。其于颈静脉孔续乙状窦，与锁骨下静脉汇合成头臂静脉。"},{"q":"下列静脉中，缺乏静脉瓣的静脉是","o":["贵要静脉","头静脉","股静脉","大隐静脉","面静脉"],"a":4,"e":"面静脉在口角以上一般缺乏静脉瓣，故面部感染可经眼静脉等途径蔓延至海绵窦。四肢静脉如大隐静脉、头静脉等均有较多静脉瓣。"},{"q":"心的正常起搏点是","o":["窦房结","结间束","房室结","房室束","Purkinje纤维网"],"a":0,"e":"窦房结是心的正常起搏点，位于上腔静脉与右心房交界处界沟上1/3的心外膜深面。房室结为潜在起搏点，Purkinje纤维网传导兴奋。"},{"q":"有关交感神经交通支的描述，错误的是","o":["分白交通支和灰交通支","每个交感干神经节与相应的脊神经直接都有交通支相连","白交通支属于节前纤维","灰交通支属于节后纤维","灰交通支只存在于T1～L3各脊神经的前支与相应的交感干神经节之间"],"a":4,"e":"白交通支仅见于T1～L3节段，灰交通支则连于全部31对脊神经前支与相应交感干神经节之间。白交通支为节前纤维，灰交通支为节后纤维。"},{"q":"受尺神经支配的骨骼肌为","o":["第1～2蚓状肌","第2～3蚓状肌","第3～4蚓状肌","第1、4蚓状肌","第2、4蚓状肌"],"a":2,"e":"尺神经深支分布于小鱼际肌、拇收肌、骨间掌侧肌、骨间背侧肌及第3、4蚓状肌；第1、2蚓状肌由正中神经支配。"},{"q":"通常卵子受精的部位是","o":["输卵管壶腹","输卵管峡","输卵管子宫部","输卵管伞","输卵管漏斗"],"a":0,"e":"卵子多在此受精，壶腹部粗而长、壁薄腔大，约占输卵管全长2/3。输卵管峡为结扎术常用部位。"},{"q":"肛管内皮肤与黏膜的分界线是","o":["齿状线","肛梳","直肠下横襞","肛柱","白线"],"a":0,"e":"齿状线是连接各肛柱下端与各肛瓣边缘的锯齿状环行线，为肛管黏膜与皮肤的分界。齿状线以上被覆单层柱状上皮，以下为复层扁平上皮。"},{"q":"颧弓是由下面哪些骨组成的","o":["上颌骨与颞骨","颞骨与蝶骨","蝶骨与颧骨","颧骨与颞骨","上颌骨与颧骨"],"a":3,"e":"颧骨的颞突向后接颞骨的颧突，二者共同构成颧弓。"},{"q":"注入肾静脉的血管是","o":["膈下静脉","左睾丸静脉","右睾丸静脉","腰升静脉","腰静脉"],"a":1,"e":"左肾静脉接受左睾丸静脉（或左卵巢静脉）和左肾上腺静脉；右睾丸静脉以锐角直接注入下腔静脉。"},{"q":"下列结构中，位于直肠壶腹内的是","o":["肛柱","齿状线","肛梳","肛瓣","直肠横襞"],"a":4,"e":"直肠内面有三个直肠横襞，由黏膜及环行肌构成，位于直肠壶腹内。肛柱、齿状线、肛梳、肛瓣均属肛管结构。"},{"q":"尿道前列腺部是","o":["尿道最长的一段","前尿道的一部分","尿道最狭窄的一段","尿道最短的一段","尿道的起始部"],"a":4,"e":"尿道前列腺部起自尿道内口，为尿道的起始部。前尿道为海绵体部，尿道最长的一段亦为海绵体部。"},{"q":"坐位时，腹膜腔的最低点是","o":["肝肾隐窝","盲肠后隐窝","耻骨后间隙","直肠子宫陷凹","膀胱子宫陷凹"],"a":3,"e":"站立或坐位时，女性的直肠子宫陷凹（Douglas腔）是腹膜腔的最低部位，积液多聚积于此，可经阴道后穹穿刺诊断。"},{"q":"止于背侧丘脑腹后内侧核的纤维束是","o":["内侧丘系","脊髓丘系","三叉丘系","薄束","楔束"],"a":2,"e":"三叉丘系由对侧三叉神经脊束核和双侧三叉神经脑桥核发出的二级感觉纤维组成，终止于背侧丘脑腹后内侧核，传导头面部感觉。腹后外侧核接受内侧丘系和脊髓丘系，薄束、楔束止于延髓薄束核和楔束核。"},{"q":"肾蒂内主要结构从前向后依次为","o":["肾动脉 肾静脉 肾盂","肾静脉 肾动脉 肾盂","肾盂 肾静脉 肾动脉","肾动脉 肾盂 肾静脉","肾盂 肾动脉 肾静脉"],"a":1,"e":"肾蒂内结构自前向后依次为肾静脉、肾动脉和肾盂末端，自上向下依次为肾动脉、肾静脉和肾盂。"},{"q":"产生泪液的结构是","o":["泪点","上泪小管","下泪小管","泪囊","泪腺"],"a":4,"e":"泪腺位于眼眶外上方的泪腺窝内，分泌的泪液经排泄管开口于结膜上穹外侧部，有防止角膜干燥和冲洗微尘的作用。泪点、泪小管和泪囊均属泪道，为引流泪液的结构。"},{"q":"传导表情肌随意运动信息的纤维束是","o":["三叉神经脊束","内侧丘系","脊髓丘系（脊髓丘脑束）","皮质核束","皮质脊髓束"],"a":3,"e":"皮质核束起自中央前回下1/3，经内囊膝部下行，终止于脑干一般躯体运动核和特殊内脏运动核，支配头面部表情肌等随意运动。皮质脊髓束支配躯干四肢肌，三叉神经脊束为感觉纤维束。"},{"q":"关于颈总动脉描述正确的是","o":["双侧均发自主动脉弓","在舌骨大角平面分为颈内、颈外动脉","其内侧有颈内静脉","分叉处有颈动脉窦和颈动脉小球","头面部出血时可在甲状软骨外侧压迫该动脉"],"a":3,"e":"颈总动脉分叉处及其附近有颈动脉窦和颈动脉小球两个重要结构，分别属压力感受器和化学感受器。右颈总动脉发自头臂干，左侧发自主动脉弓；分叉平面约平甲状软骨上缘。"},{"q":"牙式表示的是","o":["恒牙","乳牙","乳牙和恒牙","乳牙或恒牙以及牙的位置","牙的位置"],"a":3,"e":"临床牙式以“+”划分四区，用罗马数字Ⅰ～Ⅴ标示乳牙、阿拉伯数字1～8标示恒牙，故牙式表示乳牙或恒牙以及牙的位置。"},{"q":"有关主动脉弓的描述，正确的是","o":["在右侧第3胸肋关节高度弓形弯向左侧","其壁内有压力感受器","在第5胸椎下缘续降主动脉","弓的凸缘发出左、右颈总动脉及锁骨下动脉","以上描述均正确"],"a":1,"e":"主动脉弓壁外膜下有丰富神经末梢，可感受血压变化，称压力感受器。主动脉弓于右侧第2胸肋关节高度起始，凸缘发出头臂干、左颈总动脉和左锁骨下动脉。"},{"q":"关于肱三头肌的描述，正确的是","o":["长头起于关节盂的上方","止于桡骨粗隆","使前臂旋后","是伸肘关节的肌","长头可屈肩关节"],"a":3,"e":"肱三头肌长头起自肩胛骨盂下结节，内侧头和外侧头起自肱骨后面桡神经沟两侧骨面，三头会合以肌腱止于尺骨鹰嘴，作用是伸肘关节。"},{"q":"关于桡动脉描述错误的是","o":["为肱动脉两个终支之一","行于前臂的外侧肌之间","在肱桡肌与桡侧腕屈肌腱间桡动脉位置表浅","桡动脉的拇主要动脉不参与掌浅弓的组成","桡动脉的掌浅支参与掌深弓的组成"],"a":4,"e":"桡动脉末端与尺动脉掌深支吻合形成掌深弓，其掌浅支参与的是掌浅弓。桡动脉为肱动脉终支之一，行于前臂外侧肌间，在肱桡肌与桡侧腕屈肌腱间位置表浅，拇主要动脉不参与掌浅弓组成。"},{"q":"下列关于骶副交感核的描述，正确的是","o":["位于第1胸髓节段～第3腰髓节段中间带的内侧部","位于第2～4髓骶节段中间带的内侧部","位于第1胸髓节段～第3腰髓节段中间带的外侧部","位于第2～4髓骶节段中间带的外侧部","是副交感节后神经元胞体"],"a":3,"e":"骶副交感核位于S2～S4节段中间带的外侧部，是副交感神经节前神经元胞体所在部位，发出纤维组成盆内脏神经。中间带内侧核参与内脏传入信息传递，胸腰段中间带外侧核为交感神经低级中枢。"},{"q":"关于头臂静脉，下列描述中错误的是","o":["右侧有右淋巴导管注入","左侧有胸导管注入","由同侧颈总静脉与锁骨下静脉合成","左、右各一条","注入上腔静脉"],"a":2,"e":"头臂静脉由同侧颈内静脉与锁骨下静脉在胸锁关节后方汇合而成，并非颈总静脉。左头臂静脉接受胸导管注入，右头臂静脉接受右淋巴导管注入，左右各一，汇合后注入上腔静脉。"},{"q":"属于软骨连结的是","o":["颅骨的缝","桡、尺骨间的连结","腕骨间的连结","椎间盘","第2肋与胸骨间的连结"],"a":3,"e":"椎间盘是连结相邻椎体的纤维软骨盘，属软骨连结。颅骨缝为纤维连结，桡尺骨间和腕骨间为滑膜关节，第2肋与胸骨间为胸肋关节。"},{"q":"使足外翻的肌肉是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌起自腓骨外侧面，肌腱经外踝后方转向前止于内侧楔骨和第1跖骨底，可屈踝关节并使足外翻。胫骨前肌和胫骨后肌使足内翻，腓肠肌和比目鱼肌只屈踝关节。"},{"q":"上腔静脉注入到下列何处","o":["右心房","左心房","无名静脉","左心室","右心室"],"a":0,"e":"上腔静脉由左、右头臂静脉汇合而成，沿升主动脉右侧下行，平第3胸肋关节下缘处注入右心房。"},{"q":"下面有关胸锁乳突肌的描述，正确的是","o":["表面无肌覆盖","仅起自胸骨柄","止于颞骨的乳突","两侧收缩使头前屈","该肌一侧收缩使头歪向对侧"],"a":2,"e":"胸锁乳突肌起自胸骨柄前面和锁骨胸骨端，止于颞骨乳突。一侧收缩使头向同侧倾斜、脸转向对侧，两侧同时收缩使头后仰；该肌大部分被颈阔肌覆盖。"},{"q":"关于甲状旁腺的描述，正确的是","o":["呈“H”形","左、右各一个","位于甲状腺前方","功能与甲状腺相同","可参与调节体内钙、磷的代谢"],"a":4,"e":"甲状旁腺分泌甲状旁腺激素，主要调节体内钙、磷代谢，与降钙素共同维持血钙稳定。甲状旁腺通常上下各一对，位于甲状腺侧叶后面，功能与甲状腺不同。"},{"q":"具有3个运动轴的关节是","o":["肩关节","肘关节","桡腕关节","膝关节","距小腿关节"],"a":0,"e":"肩关节属三轴关节，可绕冠状轴屈伸、矢状轴收展、垂直轴旋内旋外，并作环转运动。肘关节为单轴关节，桡腕关节为双轴关节。"},{"q":"被射精管穿过的结构是","o":["睾丸","精囊","附睾","前列腺","尿道球腺"],"a":3,"e":"射精管由输精管末端与精囊排出管汇合而成，穿入前列腺，斜向前下方开口于尿道前列腺部后壁的精阜。"},{"q":"与直肠子宫陷凹相邻的是","o":["阴道前穹","阴道后穹","阴道左穹","阴道右穹","膀胱颈"],"a":1,"e":"阴道穹后部最深，与直肠子宫陷凹仅隔阴道壁和一层腹膜，临床上可经阴道后穹穿刺引流该陷凹内积液。"},{"q":"下列哪个器官的静脉血未汇入肝门静脉","o":["胃","脾","肾","胰","十二指肠"],"a":2,"e":"肝门静脉收集腹腔内除肝以外不成对脏器及盆腔消化道的静脉血，胃、脾、胰、十二指肠的静脉血均经其属支汇入。肾静脉直接注入下腔静脉。"},{"q":"下列关于胸廓的叙述中，错误的是","o":["由12块胸椎、肋和胸骨连结而成","成人近似圆锥体","上部狭窄，下部宽阔","其前后径大于横径","其下口宽阔而被膈肌封闭"],"a":3,"e":"胸廓上窄下宽、前后扁平，横径大于前后径。吸气时肋上提使横径加大，胸骨上升使前后径加大。"},{"q":"右淋巴导管收集的淋巴液范围是","o":["右半身","人体右上1/3","人体右上2/3","人体右上1/4","人体右上3/4"],"a":3,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，引流右上肢、右胸部和右头颈部，即全身约1/4部位的淋巴。"},{"q":"下列关于脊髓节段与椎骨关系的描述，正确的是","o":["第3腰髓节段平对第2腰椎","第7胸髓节段平对第7胸椎","第5颈髓节段平对第5颈椎","骶尾节段平对第2腰椎","第2胸髓节段平对第1胸椎"],"a":4,"e":"下颈髓和上胸髓节段约平对同序数椎骨的上1块椎骨，故第2胸髓节段平对第1胸椎。第5颈髓节段平对第4颈椎。"},{"q":"关于右冠状动脉描述正确的是","o":["发自主动脉弓","分为前室间支和旋支","行走在冠状沟的左侧","在室间隔与左冠状动脉相吻合","不分支营养窦房结"],"a":3,"e":"右冠状动脉分布于右心房、右心室及室间隔后1/3，其分支与左冠状动脉在室间隔等处存在吻合。右冠状动脉发自升主动脉，分为后室间支和右旋支。"},{"q":"解剖学姿势下两侧髋骨的最低处是","o":["髂前上棘","髂前下棘","髂后下棘","坐骨棘","坐骨结节"],"a":4,"e":"坐骨结节是坐骨最低部，为坐位时体重的承受点，解剖学姿势下位于髋骨最下方，可在体表扪及。髂前上棘、坐骨棘等位置均高于坐骨结节。"},{"q":"大脑内，属于连合纤维的是","o":["胼胝体","皮质脊髓束","丘脑中央辐射","视辐射","听辐射"],"a":0,"e":"胼胝体由连合左、右大脑半球新皮质的纤维构成，属连合纤维。皮质脊髓束为投射纤维，丘脑中央辐射及视、听辐射均为投射纤维。"},{"q":"有关女性尿道的描述，正确的是","o":["前方邻接阴道","后方邻接直肠","穿尿生殖膈","开口于阴道口与肛门之间","尿道阴道括约肌为平滑肌"],"a":2,"e":"女性尿道向前下方走行，穿过尿生殖膈，开口于阴道前庭的尿道外口。女性尿道前方邻耻骨联合、后方邻阴道，尿道阴道括约肌为横纹肌。"},{"q":"咽鼓管咽口位于","o":["咽鼓管圆枕后上方","下鼻道后部","口咽部","中耳鼓室","咽鼓管圆枕前下方"],"a":4,"e":"咽鼓管软骨部向前内侧开口于鼻咽部侧壁的咽鼓管咽口，位于咽鼓管圆枕前下方，平对下鼻甲后方。咽鼓管圆枕是寻找咽鼓管咽口的标志。"},{"q":"关于直肠的说法，正确的是","o":["内有直肠纵襞","上端接降结肠","在男性，通过直肠指诊可触及前列腺","有骶曲和尾曲","向下通过肛门续于肛管"],"a":2,"e":"前列腺体后面有前列腺沟，活体直肠指诊可触及此沟，故经直肠可触及前列腺。直肠上端续于乙状结肠，向下续于肛管，并具有骶曲和会阴曲。"},{"q":"需要两侧同时运动的关节是","o":["肩关节","肘关节","髋关节","膝关节","颞下颌关节"],"a":4,"e":"颞下颌关节属于联合关节，两侧必须同时运动。肩、肘、髋、膝关节均为单动关节，可单独运动。"},{"q":"关于小网膜的描述，正确的是","o":["仅位于肝门与胃小弯之间","由四层腹膜形成","即肝胃韧带","内有胃左动脉和胃右动脉","与大网膜相连续"],"a":3,"e":"小网膜内含有胃左动脉和胃右动脉，二者沿胃小弯走行并吻合。小网膜包括肝胃韧带和肝十二指肠韧带，由双层腹膜形成，向下与网膜囊后壁相延续。"},{"q":"关于肋间后动脉，错误的是","o":["12对肋间后动脉均来自主动脉胸部","分布于第3～11肋间隙的肋间后动脉来自主动脉胸部","分布于第1～2肋间隙的肋间后动脉来自锁骨下动脉","第12对肋间后动脉行于12肋下缘称肋下动脉","肋下动脉也来自主动脉胸部"],"a":0,"e":"第1～2肋间隙的肋间后动脉来自锁骨下动脉的肋颈干，其余9对肋间后动脉及1对肋下动脉均起自胸主动脉，故“12对均来自胸主动脉”错误。"},{"q":"脑室系统中，不包含脉络丛的结构是","o":["第三脑室","第四脑室","侧脑室","中脑水管","室间孔"],"a":3,"e":"中脑水管是连接第三脑室与第四脑室的窄管，管壁无脉络丛。侧脑室、第三脑室和第四脑室顶部均有脉络丛，室间孔为侧脑室通第三脑室处，亦无脉络丛。"},{"q":"在蜗顶处，前庭阶与鼓阶借下列哪个结构彼此相通","o":["蜗管","蜗窗","蜗孔","前庭水管外口","前庭窗"],"a":2,"e":"蜗孔位于蜗顶，由骨螺旋板和膜螺旋板与蜗轴围成，是前庭阶与鼓阶连通的唯一通道。蜗窗、前庭窗分别通鼓室，蜗管属膜迷路。"},{"q":"上颌神经不分布于","o":["上颌牙和牙龈","上颌窦黏膜","舌前2/3的黏膜","口腔顶","睑裂与口裂之间的皮肤"],"a":2,"e":"舌前2/3黏膜的一般感觉由舌神经（三叉神经下颌支）分布，味觉由面神经鼓索分布，均非上颌神经。上颌神经分布于上颌牙及牙龈、上颌窦黏膜、口腔顶和睑裂与口裂之间的皮肤。"},{"q":"一侧皮质脊髓束下行不经过","o":["内囊前肢","内囊后肢","中脑大脑脚","脑桥基底部","延髓锥体"],"a":0,"e":"皮质脊髓束起自中央前回上中部，下行经内囊后肢的前部、大脑脚底中3/5外侧部、脑桥基底部至延髓锥体。内囊前肢主要为额桥束和丘脑前辐射，不含皮质脊髓束。"},{"q":"关于纤维性心包，下列说法错误的是","o":["包裹在心及其大血管根部外面","是坚韧的结缔组织囊","与浆膜性心包壁层紧贴","与膈肌中心腱愈着","心包积液时伸缩性较大"],"a":4,"e":"纤维心包由坚韧的纤维结缔组织构成，包裹心和大血管根部，下方与膈中心腱愈着，缺乏伸缩性，心包积液时不能充分扩张。浆膜心包壁层紧贴其内面。"},{"q":"内侧丘系交叉位于","o":["延髓","脑桥","中脑","间脑","内囊"],"a":0,"e":"薄束核与楔束核发出的内弓状纤维在延髓中下部中央管腹侧越中线交叉，形成内侧丘系交叉，交叉后上行构成内侧丘系。"},{"q":"关于肾上腺的描述，正确的是","o":["左、右各一，均为肾形","肾上腺位于腹膜腔内","左侧呈半月形，右侧呈三角形","左、右肾上腺均位于肾脏下端","肾上腺皮质激素又称肾上腺素"],"a":2,"e":"肾上腺位于肾的上方，与肾共同包裹于肾筋膜内，属腹膜外位器官；左侧呈半月形，右侧呈三角形。肾上腺皮质激素与肾上腺素是不同物质。"},{"q":"上腔静脉由下列的什么静脉汇合而成","o":["头臂静脉","锁骨下静脉","颈内静脉","头臂干","颈外静脉"],"a":0,"e":"上腔静脉由左、右头臂静脉在右侧第1胸肋结合处后方汇合而成。头臂静脉由颈内静脉与锁骨下静脉在胸锁关节后方汇合而成，头臂干为动脉。"},{"q":"关于大隐静脉，下列说法正确的是","o":["起于足背静脉网外侧","经内踝后方上行","静脉瓣很少","注入股静脉","属于深静脉"],"a":3,"e":"大隐静脉在注入股静脉前经隐静脉裂孔注入股静脉。其起自足背静脉弓内侧，经内踝前方上行，属浅静脉，管壁内有较多静脉瓣。"},{"q":"使脑脊液渗入上矢状窦的结构是","o":["正中孔","外侧孔","室间孔","蛛网膜粒","中脑水管"],"a":3,"e":"蛛网膜粒是脑蛛网膜突入上矢状窦的绒毛状结构，脑脊液经此渗入上矢状窦回流入血。正中孔、外侧孔、室间孔和中脑水管均为脑脊液循环通路，非渗入部位。"},{"q":"舌下神经管位于下面哪块颅骨上","o":["额骨","颞骨","枕骨","筛骨","蝶骨"],"a":2,"e":"舌下神经管内口位于枕骨大孔前外缘，舌下神经管外口位于枕髁前外侧，故舌下神经管位于枕骨。"},{"q":"喉炎时易发生水肿的部位是","o":["喉室","声门裂","声门下腔","喉口","前庭裂"],"a":2,"e":"声门下腔黏膜下组织疏松，炎症时易发生喉水肿，婴幼儿尤易致喉阻塞。"},{"q":"现代人体解剖学的创始人是","o":["Vesalius","Galen","Harvey","Hippocrates","Schwann"],"a":0,"e":"比利时解剖学家安德烈·维萨里（Vesalius）亲自解剖尸体，1543年出版《人体构造》，奠定了人体解剖学的科学基础，为现代解剖学奠基人。"},{"q":"坐骨神经出盆腔的部位是","o":["闭孔","坐骨小孔","骶管裂孔","梨状肌上孔","梨状肌下孔"],"a":4,"e":"坐骨神经从骶丛发出后经梨状肌下孔出盆腔至臀大肌深面，此形式最常见。"},{"q":"骨损伤后能参与修复的结构是","o":["骨质","骨骺","骨膜","骨髓","关节面的软骨"],"a":2,"e":"骨膜内层和骨内膜有分化成骨细胞和破骨细胞的能力，骨折时骨膜成骨功能活跃，促进骨折修复愈合。"},{"q":"下颌下腺和舌下腺共同开口在","o":["舌盲孔","舌系带","舌下襞","舌下阜","伞襞"],"a":3,"e":"舌下腺大管与下颌下腺管共同开口于舌下阜；舌下腺小管直接开口于舌下襞表面。"},{"q":"关于斜方肌，下列描述正确的是","o":["起于枕外隆突和上部腰椎棘突","止于肩胛骨的上角","收缩时使肩胛骨外展","两侧同时收缩，可使肩胛骨向脊柱靠拢","下部肌纤维收缩，可上提肩胛骨"],"a":3,"e":"斜方肌两侧同时收缩可使肩胛骨向脊柱靠拢，该肌起自上项线、枕外隆凸、项韧带及全部胸椎棘突，止于锁骨外侧1/3、肩峰和肩胛冈。上部肌束上提肩胛骨，下部肌束下拉肩胛骨。"},{"q":"胆囊动脉","o":["胆囊动脉由腹腔干发出","胆囊动脉由肝总动脉发出","胆囊动脉由肝固有动脉左支发出","胆囊动脉经肝胆三角至胆囊","胆囊动脉伴胆囊管至胆囊"],"a":3,"e":"胆囊动脉发自肝固有动脉右支，经胆囊三角（Calot三角）至胆囊，该三角是胆囊手术中寻找胆囊动脉的标志。胆囊动脉并非起自腹腔干或肝总动脉。"},{"q":"关于呼吸道的叙述，正确的是","o":["咽既是呼吸道，也是消化道","上呼吸道只有呼吸功能","上呼吸道包括口腔、鼻、咽","咽和喉属于下呼吸道","肺和支气管为下呼吸道"],"a":0,"e":"咽是消化管与呼吸道的共同通道，既属消化道又属呼吸道。上呼吸道指鼻、咽、喉，下呼吸道为气管和各级支气管，肺不属于呼吸道。"},{"q":"关于肝上界的描述，正确的是","o":["在右腋中线起自第7肋","在右腋中线起自第11肋","在左锁骨中线起自第7肋","在右锁骨中线起自第6肋","在右锁骨中线起自第7肋"],"a":0,"e":"肝上界在右腋中线起自第7肋，右锁骨中线平第5肋，右锁骨中线与第5肋交点为其上界标志。右腋中线第7肋为肝上界在腋中线的对应高度。"},{"q":"产生精子的部位是","o":["精曲小管","精囊腺","输精管","前列腺","附睾"],"a":0,"e":"精子由生精小管（精曲小管）的生精上皮产生，生精小管汇合成精直小管入睾丸网。附睾仅贮存精子，精囊腺、前列腺分泌精液成分。"},{"q":"左右心室收缩时","o":["二尖瓣开放","三尖瓣开放","主动脉瓣开放","肺动脉瓣关闭","心房也收缩"],"a":2,"e":"心室收缩时，房室瓣（二尖瓣、三尖瓣）关闭，主动脉瓣和肺动脉瓣开放，血液射入主动脉和肺动脉。心房收缩发生在心室舒张期。"},{"q":"颈外静脉汇入下列哪个静脉","o":["颈内静脉","头臂静脉","颈总静脉","腋静脉","锁骨下静脉"],"a":4,"e":"颈外静脉由下颌后静脉后支、耳后静脉和枕静脉汇合而成，沿胸锁乳突肌表面下行，注入锁骨下静脉或静脉角。"},{"q":"坐骨大切迹位于","o":["坐骨棘的上方","坐骨棘的下方","髂前上棘下方","髂前上棘上方","髂后上棘上方"],"a":0,"e":"坐骨大切迹位于坐骨棘与髂后下棘之间，即坐骨棘的上方，与骶棘韧带围成坐骨大孔。坐骨小切迹位于坐骨棘下方。"},{"q":"下面关于面肌的描述，错误的是","o":["全是皮肌","有开闭眼、口、鼻孔的作用","人类特别发达","能显示喜、怒、哀、乐","枕额肌、颊肌、颞肌都属于面肌"],"a":4,"e":"面肌为面部扁薄的皮肌，分布于孔裂周围，有闭合或开大孔裂及牵动皮肤显示表情的作用。枕额肌、颊肌属面肌，而颞肌属咀嚼肌，由下颌神经支配。"},{"q":"眼神经不分布于","o":["眼球","硬脑膜","鼻背部的皮肤","下睑的皮肤","泪腺"],"a":3,"e":"下睑皮肤由眶下神经分布，眶下神经属上颌神经分支。眼神经分布于眼球、硬脑膜、鼻背皮肤及泪腺等。"},{"q":"有关骨髓腔的描述，正确的是","o":["位于骨骺内","位于长骨的骨干内","成人骨髓腔内含红骨髓","小儿骨髓腔内含黄骨髓","骨髓腔逐渐萎缩变小"],"a":1,"e":"骨髓腔位于长骨骨干内，容纳骨髓。5岁后骨干内红骨髓渐被脂肪代替为黄骨髓，骨髓腔随骨生长改建而扩大。"},{"q":"胸主动脉的分支中没有","o":["肋间后动脉","肋下动脉","肋间前动脉","膈上动脉","食管支、心包支"],"a":2,"e":"胸主动脉发出肋间后动脉、肋下动脉、膈上动脉及食管支、心包支等。肋间前动脉来自胸廓内动脉，不属胸主动脉分支。"},{"q":"关于腹膜腔的描述，正确的是","o":["是一个与体外不通的浆膜间隙","由脏、壁两层腹膜互相移行而成","腹、盆腔脏器有的位于腹膜腔之内，有的位于腹膜腔之外","内有大部分器官","是区分内位器官和外位器官的分界线"],"a":1,"e":"腹膜腔由壁腹膜与脏腹膜互相延续、移行共同围成，腔内仅少量浆液。男性封闭，女性借输卵管腹腔口与外界相通。"},{"q":"关于胃壁的说法，错误的是","o":["肌层只有两层平滑肌","分四层","最内层是黏膜层","外膜为浆膜","幽门处有幽门瓣"],"a":0,"e":"胃肌层由外纵、中环、内斜三层平滑肌构成，并非只有两层。胃壁分黏膜、黏膜下层、肌层和浆膜四层，幽门处有幽门瓣。"},{"q":"锥体交叉位于","o":["中脑上部","中脑下部","脑桥","延髓上部","延髓下部"],"a":4,"e":"锥体交叉位于延髓下部，由大脑皮质下行的锥体束纤维在此交叉。延髓上部中央管敞开形成菱形窝。"},{"q":"使瞳孔缩小的肌是","o":["外直肌","内直肌","上直肌","瞳孔括约肌","瞳孔开大肌"],"a":3,"e":"瞳孔括约肌环绕瞳孔周缘排列，收缩时缩小瞳孔，受动眼神经副交感纤维支配。瞳孔开大肌呈放射状排列，收缩开大瞳孔。"},{"q":"对外耳道的叙述，下列错误的是","o":["是从外耳门至鼓膜的管道","外2/3为软骨部，内1/3为骨部","骨性都是颞骨鳞部和鼓部围成的短管","婴儿的外耳道几乎全部由软骨支持","外耳道表面的皮肤富含感觉神经末梢"],"a":1,"e":"外耳道外1/3为软骨部，内2/3为骨性部，由颞骨鳞部和鼓部围成，故“外2/3为软骨部”错误。外耳道为外耳门至鼓膜的管道，检查鼓膜时成人需将耳郭向后上方牵拉。"},{"q":"伸肘时，臂与前臂之间形成的向外侧的钝角是","o":["颈干角","提携角","倾斜角","肘后三角","外侧角"],"a":1,"e":"伸肘时前臂偏向外侧，与上臂形成向外开放的钝角，约165°～170°，称提携角，其补角为10°～15°。颈干角为股骨颈与股骨干之间的夹角。"},{"q":"关于口腔，下列说法正确的是","o":["由上、下牙龈分为前外侧部和后内侧部","为牙与唇、颊之间的空隙","牙与腭之间的空隙","上、下牙咬合时，口腔前庭与固有口腔不相通","借咽峡与口咽相通"],"a":4,"e":"口腔向后经咽峡与咽相通，咽峡由腭垂、腭帆游离缘、两侧腭舌弓及舌根围成，是口腔与咽的分界。口腔借上、下牙弓和牙龈分为口腔前庭与固有口腔。"},{"q":"尺神经损伤容易导致以下哪块肌肉瘫痪","o":["肱桡肌","拇收肌","拇短展肌","拇短屈肌","指浅屈肌"],"a":1,"e":"正中神经支配除拇收肌以外的鱼际肌，拇收肌由尺神经支配，故尺神经损伤可致拇收肌瘫痪。拇短展肌、拇短屈肌属鱼际肌，由正中神经支配。"},{"q":"小脑水平切面的白质中，呈皱缩口袋状的神经核是","o":["球状核","闩状核","顶核","齿状核","下橄榄核"],"a":3,"e":"齿状核位于小脑半球白质内，最大，呈皱缩的口袋状，袋口朝向前内侧，属新小脑。顶核位于第四脑室顶上方、小脑蚓白质内。"},{"q":"关于股四头肌的描述，正确的是","o":["股直肌起自髂前上棘","止于胫骨、腓骨上端","能伸髋关节","能屈膝关节","肌腱向下延续为髌韧带"],"a":4,"e":"股四头肌四个头向下构成髌腱，包绕髌骨后续为髌韧带，止于胫骨粗隆。股直肌起自髂前下棘，该肌屈髋关节并伸膝关节。"},{"q":"参与构成距小腿关节的骨是","o":["胫骨、腓骨、跟骨","胫骨、腓骨、距骨","胫骨、距骨","腓骨、距骨","胫骨、跟骨"],"a":1,"e":"距小腿关节由胫、腓骨下端与距骨滑车构成，为近似单轴的屈戌关节。跟骨不参与构成该关节，而参与构成足弓。"},{"q":"关于前列腺的描述，正确的是","o":["与膀胱底相邻","有尿道穿过","为男性生殖腺之一","能分泌少量的雄激素","体的前面有一前列腺沟"],"a":1,"e":"尿道穿过前列腺，前列腺部为尿道穿过前列腺的部分。前列腺为男性附属腺而非生殖腺，其后面正中有一前列腺沟。"},{"q":"关于腹膜腔的描述，错误的是","o":["由脏、壁两层腹膜互相移行而成","腔内有少量的浆液","男性腹膜腔为封闭的腔隙","女性腹膜腔与体外相通","腹腔脏器、盆腔脏器均位于腹膜腔之内"],"a":4,"e":"腹膜腔由壁腹膜与脏腹膜互相移行围成，腔内仅含少量浆液；男性腹膜腔封闭，女性经输卵管腹腔口与体外相通。腹腔脏器位于腹膜腔之外，腹膜腔仅为腹腔内潜在间隙。"},{"q":"管理右下肢末端一般感觉的大脑皮质区位于","o":["左半球中央后回下部","右半球中央后回下部","左半球中央旁小叶后部","右半球中央旁小叶后部","左半球中央后回中部"],"a":2,"e":"右下肢末端一般感觉经脊髓丘脑束投射至对侧中央后回中、上部和中央旁小叶后部，故位于左半球中央旁小叶后部。中央后回下部管理头面部感觉。"},{"q":"不属于腹膜内位器官的是","o":["胃","乙状结肠","胆囊","空肠","横结肠"],"a":2,"e":"胆囊表面大部分被腹膜覆盖，属腹膜间位器官。胃、空肠、横结肠、乙状结肠表面几乎全部被腹膜覆盖，均为腹膜内位器官。"},{"q":"支配臂前群肌的神经为","o":["正中神经","尺神经","桡神经","肌皮神经","腋神经"],"a":3,"e":"肌皮神经穿喙肱肌后行于肱二头肌与肱肌之间，支配臂前群三肌。正中神经、尺神经、桡神经主要支配前臂肌，腋神经支配三角肌。"},{"q":"从颅底的眶上裂通过的脑神经为","o":["嗅神经","视神经","迷走神经","舌下神经","动眼神经"],"a":4,"e":"动眼神经自中脑发出后经眶上裂入眶。嗅神经经筛孔、视神经经视神经管、迷走神经经颈静脉孔、舌下神经经舌下神经管出入颅。"},{"q":"在脑干的腹侧面，延髓与脑桥的分界标志是","o":["锥体","橄榄","锥体交叉","延髓脑桥沟","基底沟"],"a":3,"e":"延髓上端借横行的延髓脑桥沟与脑桥分界，沟内自中线向外依次连有展神经、面神经和前庭蜗神经根。锥体、橄榄位于延髓腹侧，基底沟位于脑桥腹侧。"},{"q":"前臂的旋转运动","o":["由肘关节单独完成","由桡腕关节单独完成","由肘关节和桡腕关节共同完成","由桡尺近侧关节、前臂骨间膜和桡尺远侧关节共同完成","由肩关节和肘关节、腕关节共同完成"],"a":3,"e":"前臂旋转由桡尺近侧关节、桡尺远侧关节及前臂骨间膜共同完成，旋转轴为桡骨头中心至尺骨头中心的连线。桡骨头原位自转，桡骨下端连同关节盘绕尺骨头旋转。"},{"q":"以下对下颌神经的叙述，错误的是","o":["是三叉神经三大分支中最粗大的一支","为混合性神经","其自颅底的圆孔出颅","耳颞神经为其分支","其分支咀嚼肌神经属运动性神经"],"a":2,"e":"下颌神经为混合性神经，是三叉神经最粗大的分支，经卵圆孔出颅，耳颞神经为其分支，其咀嚼肌神经属运动性纤维。经圆孔出颅的是上颌神经。"},{"q":"组成喙肩弓的结构是","o":["喙突、喙肩韧带","喙突、喙肩韧带、肩峰","喙突、喙锁韧带、肩峰","喙突、喙肱韧带、肩峰","喙肩韧带、肩峰"],"a":1,"e":"喙肩韧带连于喙突与肩峰之间，与喙突、肩峰共同构成喙肩弓，架于肩关节上方，防止肱骨头向上脱位。喙锁韧带连于喙突与锁骨，不参与喙肩弓构成。"},{"q":"外踝位于","o":["胫骨下端","胫骨上端","腓骨上端","腓骨下端","股骨下端"],"a":3,"e":"腓骨下端膨大形成外踝，其内侧有外踝关节面与距骨相关节，腓骨头和外踝均可在体表扪及。内踝为胫骨下端的突起。"},{"q":"临床上确认空肠起始部的标志是","o":["十二指肠上曲","十二指肠纵襞","十二指肠悬肌","十二指肠升部","十二指肠下曲"],"a":2,"e":"十二指肠悬肌与包绕其下段表面的腹膜皱襞共同构成Treitz韧带，腹部外科手术中以此韧带作为确定空肠起始的重要标志。"},{"q":"关于小脑延髓池的描述错误的是","o":["位于小脑与延髓之间","位于硬膜外隙内","位于蛛网膜下隙内","临床上可在此进行穿刺，抽取脑脊液","是脑蛛网膜下隙扩大部分"],"a":1,"e":"小脑延髓池位于小脑与延髓之间，属脑蛛网膜下隙的扩大部分，临床可在此穿刺抽取脑脊液。硬膜外隙位于硬脑膜与颅骨内面之间，不含脑脊液。"},{"q":"关于肱骨形态的描述，何者错误","o":["位于臂部，分为一体两端","上端有球形的肱骨头","上端与体交界处稍细，称为外科颈","肱骨体后面有桡神经沟","内上髁后方有尺神经沟"],"a":1,"e":"肱骨上端有朝向上后内方呈半球形的肱骨头，并非球形；上端与体交界处稍细为外科颈，体后面有桡神经沟，内上髁后方有尺神经沟。"},{"q":"骶丛位于","o":["腰方肌深面","腰大肌深面","腰大肌浅层","梨状肌前面","梨状肌后面"],"a":3,"e":"骶丛位于盆腔内，恰在骶骨和梨状肌的前面、髂血管的后方。腰丛位于腰大肌深面，梨状肌后面无骶丛。"},{"q":"嗅神经通过颅底什么结构进入颅腔","o":["枕骨大孔","圆孔","棘孔","卵圆孔","筛孔"],"a":4,"e":"嗅神经由上鼻甲和鼻中隔上部黏膜内嗅细胞的中枢突聚集而成嗅丝，穿筛骨筛板的筛孔入颅前窝连于嗅球。圆孔、卵圆孔、棘孔分别通行上颌神经、下颌神经和脑膜中动脉。"},{"q":"子宫肿瘤的好发部位是","o":["子宫底","子宫体","子宫峡","子宫颈","子宫角"],"a":3,"e":"子宫颈在成人长约2.5～3.0cm，为肿瘤的好发部位；子宫底、体、峡均非肿瘤好发部位。"},{"q":"肝的左纵沟后半部容纳的是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","镰状韧带"],"a":1,"e":"静脉韧带由胎儿时期静脉导管闭锁而成，位于左纵沟后部的静脉韧带裂内。左纵沟前部容纳肝圆韧带，右纵沟前部为胆囊窝容纳胆囊。"},{"q":"可伸肘关节，并能协助伸肩关节的肌肉是","o":["肱二头肌","肱三头肌","喙肱肌","肱桡肌","桡侧腕屈肌"],"a":1,"e":"肱三头肌长头起自肩胛骨盂下结节，可伸肩关节；三个头共同止于尺骨鹰嘴，作用是伸肘关节。肱二头肌和肱肌只屈肘，喙肱肌使肩关节屈和内收。"},{"q":"下列关于蛛网膜下隙的描述，错误的是","o":["位于硬脊膜与蛛网膜之间","位于蛛网膜与软膜之间","脊髓蛛网膜下隙与脑蛛网膜下隙相通","内充满脑脊液","脊髓下端蛛网膜内有脊髓马尾"],"a":0,"e":"蛛网膜下隙位于蛛网膜与软膜之间，内充满脑脊液，脊髓与脑的蛛网膜下隙相通。硬脊膜与脊髓蛛网膜之间的间隙是硬膜下隙。"},{"q":"以下对白交通支的叙述正确的是","o":["发自椎旁神经节","发自椎前神经节","离开脊神经到交感干","属节后纤维","连于交感干与31对脊神经前支之间"],"a":2,"e":"白交通支由脊髓灰质侧角发出的节前纤维构成，经脊神经前根、脊神经离开脊神经进入交感干。灰交通支才是节后纤维，连于交感干与31对脊神经前支之间。"},{"q":"关于足背动脉的描述，不正确的是","o":["是胫前动脉的延续","行于拇长深肌腱内侧","在内、外踝连线中点处可摸其搏动","其足底深支参与形成足底动脉弓","中医学称之为“趺阳脉”"],"a":1,"e":"足背动脉经拇长伸肌腱和趾长伸肌腱之间前行，位于拇长伸肌腱外侧而非内侧。该动脉是胫前动脉的直接延续，足底深支与足底外侧动脉吻合形成足底弓。"},{"q":"下列关于射精管的描述，正确的是","o":["穿尿道膜部","穿前列腺实质","有贮存精子的功能","开口于尿道球部","开口于尿道海绵体部"],"a":1,"e":"射精管由输精管末端与精囊排出管汇合而成，向前下穿前列腺实质，开口于尿道前列腺部。贮存精子的是精囊，而非射精管。"},{"q":"牵拉肩胛骨向前的是","o":["胸大肌","肩胛下肌","前锯肌","斜方肌","菱形肌"],"a":2,"e":"前锯肌起自上位8或9个肋骨外面，止于肩胛骨内侧缘和下角，作用是拉肩胛骨向前并紧贴胸廓。胸大肌使肩关节内收、旋内和前屈，斜方肌和菱形肌使肩胛骨后缩。"},{"q":"有关动脉的描述，错误的是","o":["由心室发出","输送血液离心","越分越细","移行为毛细血管","腔内全是动脉血"],"a":4,"e":"肺动脉干由右心室发出，输送静脉血，故动脉腔内并非全为动脉血。动脉均由心室发出、输送血液离心，逐级分支变细，最终移行为毛细血管。"},{"q":"下列关于脊髓丘脑束的描述，正确的是","o":["起自脊髓灰质板层Ⅰ～Ⅴ","是后根外侧部细纤维的直接延续","经灰质连合至对侧外侧索和前索上行","传导同侧的痛、温觉和粗触压觉","一侧损伤时出现对侧痛、温觉障碍"],"a":4,"e":"脊髓丘脑束传导对侧痛、温觉和粗触压觉，一侧损伤时损伤平面1～2节段以下对侧身体痛、温觉减退或消失。该束起自脊髓灰质板层Ⅰ、Ⅳ～Ⅶ，经灰质前连合交叉至对侧外侧索上行。"},{"q":"腕桡侧副韧带和腕尺侧副韧带加强的关节是","o":["桡腕关节","腕骨间关节","腕掌关节","肘关节","腕中关节"],"a":0,"e":"桡腕关节由手舟骨、月骨、三角骨近侧关节面与桡骨腕关节面及尺骨下端关节盘构成，关节囊前后及两侧均有韧带加强，包括桡侧副韧带和尺侧副韧带。"},{"q":"关于胃的叙述，正确的是","o":["幽门管与角切迹之间的部分，称幽门窦","在中等充盈时，位于右季肋区","分为胃弯、胃体和胃窦","角切迹将胃窦分为幽门窦和幽门管","胃入口称幽门，出口称贲门"],"a":0,"e":"幽门部被大弯侧浅沟分为幽门管和幽门窦，幽门窦位于幽门管左侧、近角切迹处。胃分贲门部、胃底、胃体和幽门部四部，入口为贲门、出口为幽门。"},{"q":"可以维持子宫前倾位的主要结构是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":2,"e":"子宫圆韧带起于子宫体前面的上外侧，穿经腹股沟管止于阴阜和大阴唇前端皮下，向后上牵引子宫，维持子宫前倾位。子宫主韧带和子宫骶韧带协同维持前倾前屈位。"},{"q":"展神经通过颅底什么结构入眶","o":["筛孔","眶上裂","圆孔","卵圆孔","棘孔"],"a":1,"e":"展神经起于脑桥展神经核，自脑桥延髓沟出脑，前行穿海绵窦，经眶上裂入眶支配外直肌。筛孔通嗅丝，圆孔、卵圆孔分别通上颌神经、下颌神经。"},{"q":"关于食管的说法，正确的是","o":["分为颈、胸两部分","位于气管与甲状腺峡部之间","下端在第9胸椎处接胃","上端在第6颈椎下缘处与咽相续","颈部位于喉的后方"],"a":3,"e":"食管上端在第6颈椎椎体下缘平面与咽相续，下端约平第11胸椎高度接胃贲门。食管分颈、胸、腹三部，颈部位于气管后方。"},{"q":"视觉传导通路中节细胞发出的轴突不构成","o":["视神经","视交叉外侧部纤维","视交叉中间部纤维","视束","视辐射"],"a":4,"e":"节细胞轴突汇集成视神经，经视交叉后组成视束，止于外侧膝状体，再发出纤维组成视辐射投射至枕叶视区。视辐射由外侧膝状体神经元发出，非节细胞轴突。"},{"q":"卵巢固有韧带位于卵巢的","o":["上端","下端","内侧面","外侧面","前缘"],"a":1,"e":"卵巢固有韧带由结缔组织和平滑肌纤维构成，自卵巢下端连至输卵管与子宫结合处的后下方，固定卵巢下端。卵巢上端为输卵管端，与输卵管末端相接触。"},{"q":"对内脏神经系统内容描述错误的是","o":["内脏神经系统按照分布部位的不同可分为中枢部和周围部","内脏神经系统的周围部主要分布于内脏、心血管、平滑肌和腺体","内脏运动神经又分为交感神经和副交感神经两部分","内脏运动神经受人的意志控制","内脏感觉神经的初级神经元位于脑神经节和脊神经节内"],"a":3,"e":"内脏运动神经支配心肌、平滑肌和腺体，通常不受意志控制，属不随意神经。躯体运动神经才支配骨骼肌并受意志控制。"},{"q":"颅后窝占位性病变，或小脑幕下颅内压增高，可能导致部分小脑经枕骨大孔突出。下列哪一个小脑结构最有可能与此有关","o":["小脑蚓","小脑扁桃体","小脑上脚","小脑中脚","小脑下脚"],"a":1,"e":"小脑扁桃体紧邻延髓和枕骨大孔两侧，颅内压增高时可被挤入枕骨大孔形成小脑扁桃体疝，压迫延髓生命中枢。"},{"q":"眼上静脉和眼下静脉注入","o":["上矢状窦","下矢状窦","横窦","海绵窦","内眦静脉"],"a":3,"e":"眼上静脉向后经眶上裂注入海绵窦，眼下静脉一支经眶上裂注入眼上静脉、另一支汇入翼静脉丛，二者最终均与海绵窦相通。"},{"q":"一侧内侧丘系来自","o":["同侧脊神经节中枢突","对侧后角细胞轴突","对侧薄束核和楔束核轴突","薄束和楔束的纤维交叉后","白质前连合的纤维交叉后"],"a":2,"e":"内侧丘系由对侧薄束核和楔束核发出的二级感觉纤维经内侧丘系交叉后形成，上行终于丘脑腹后外侧核。"},{"q":"关于膀胱的叙述，正确的是","o":["位于骨盆腔内，在耻骨联合的后方","男性膀胱底邻前列腺","女性膀胱底邻接直肠","男性膀胱下方邻接盆膈","是腹膜外位器官"],"a":0,"e":"膀胱空虚时全部位于盆腔内，前方为耻骨联合，二者之间为膀胱前隙。男性膀胱底邻接精囊和输精管壶腹，女性膀胱底邻接子宫颈和阴道。"},{"q":"临床上关于子宫下段说法正确的是","o":["由非孕时的子宫峡部伸展形成","孕中期的子宫颈扩展为宫腔的一部分","临产后子宫颈伸展可达7～10cm","为临产后的子宫颈","孕16周扩展成宫腔的一部分"],"a":0,"e":"子宫峡在非孕时长约1cm，妊娠期间逐渐伸展变长形成子宫下段，妊娠末期可延长至7～11cm。"},{"q":"躯体运动中枢位于","o":["中央后回和中央旁小叶后部","中央前回和中央旁小叶前部","颞横回","额下回后部","角回"],"a":1,"e":"第Ⅰ躯体运动区位于中央前回和中央旁小叶前部（Brodmann 4、6区），管理对侧骨骼肌运动，上下颠倒但头部为正。"},{"q":"位于侧脑室下角底壁，严重受损时可导致记忆障碍的结构是","o":["杏仁体","豆状核","海马","外侧膝状体","尾状核尾"],"a":2,"e":"海马位于侧脑室下角底壁，属海马结构，与记忆功能密切相关，严重受损可致记忆障碍。"},{"q":"关于锁骨形态的描述，正确的是","o":["呈“～”形弯曲","内端扁平","外端粗大","内侧2/3凸向后","骨折多在中、内1/3交界处"],"a":0,"e":"正确答案是呈“～”形弯曲。锁骨呈“～”形弯曲，横架于胸廓前上方，内侧端圆钝、外侧端扁平，内侧2/3凸向前、外侧1/3凸向后，骨折多在中、外1/3交界处。"},{"q":"关于硬膜外隙的描述，正确的是","o":["位于硬脊膜与蛛网膜之间","位于椎管内面骨膜与硬脊膜之间","位于大脑脚之间","内有马尾和脑脊液","与颅腔相通"],"a":1,"e":"正确答案是位于椎管内面骨膜与硬脊膜之间。硬膜外隙为硬脊膜与椎管内面骨膜之间的间隙，内含疏松结缔组织、脂肪、静脉丛和脊神经根，略呈负压，不与颅腔相通。硬脊膜与脊髓蛛网膜之间为硬膜下隙。"},{"q":"位于颅腔内的内分泌器官是","o":["胸腺","甲状腺","松果体","肾上腺","甲状旁腺"],"a":2,"e":"正确答案是松果体。松果体位于颅腔内，为灰红色椭圆形内分泌腺，分泌褪黑素。甲状腺、甲状旁腺位于颈部，胸腺位于胸骨柄后方，肾上腺位于腹膜后，均不在颅腔内。"},{"q":"肋膈隐窝由下列哪些结构转折形成","o":["肋胸膜与膈胸膜","肋胸膜与纵隔胸膜","纵隔胸膜与膈胸膜","纵隔胸膜与脏胸膜","肋胸膜与胸膜顶"],"a":0,"e":"正确答案是肋胸膜与膈胸膜。肋膈隐窝由肋胸膜与膈胸膜返折形成半环形间隙，是诸胸膜隐窝中位置最低、容量最大者，胸膜腔积液常先积存于此。"},{"q":"关于喉的描述，正确的是","o":["环甲肌收缩时紧张声带","环甲肌由喉返神经支配","甲状软骨、环状软骨之间只借韧带连结","会厌位于喉的后方","喉室位于前庭襞上方"],"a":0,"e":"正确答案是环甲肌收缩时紧张声带。环甲肌收缩使甲状软骨前倾，加大甲状软骨前角与杓状软骨间距，紧张并拉长声带。环甲肌由喉上神经外支支配；环甲关节为关节连结；会厌位于喉口上方；喉室位于前庭襞与声襞之间。"},{"q":"由膝关节囊滑膜层形成的结构是","o":["前交叉韧带","后交叉韧带","翼状襞","胫侧副韧带","腓侧副韧带"],"a":2,"e":"正确答案是翼状襞。膝关节滑膜层在髌骨下方中线两侧突向关节腔形成翼状襞，襞内含脂肪组织。前、后交叉韧带及胫、腓侧副韧带均为韧带结构，非滑膜形成。"},{"q":"膈的主动脉裂孔位置高度","o":["平第8胸椎","平第9胸椎","平第10胸椎","平第11胸椎","平第12胸椎"],"a":4,"e":"正确答案是平第12胸椎。膈的主动脉裂孔位于第12胸椎高度，有降主动脉和胸导管通过。"},{"q":"有关静脉的描述，错误的是","o":["起于毛细血管网","引导血液回心","越合越粗","注入到心房","均有静脉瓣"],"a":4,"e":"正确答案是均有静脉瓣。静脉瓣常成对、半月形，利于血液向心流动并防止逆流，但在头颈、躯干处静脉内较少或缺如，并非所有静脉均有瓣膜。"},{"q":"关于胸椎的特点是","o":["横突上有横突孔","棘突分叉","上、下关节突不明显","棘突水平伸向后方","椎体侧面后部有肋凹"],"a":4,"e":"胸椎椎体两侧面后份上、下缘有半圆形肋凹，与肋头相关节。横突孔为颈椎特征，棘突分叉亦见于颈椎，胸椎棘突长而向后下倾斜。"},{"q":"关于脊髓的描述，错误的是","o":["上端在枕骨大孔处与小脑相连","有颈膨大和腰骶膨大","呈扁的圆柱形","脊髓表面有6条纵沟","新生儿脊髓下端平第3腰椎"],"a":0,"e":"脊髓上端在枕骨大孔处与延髓相连，并非与小脑相连。新生儿脊髓下端可达第3腰椎，脊髓有颈膨大和腰骶膨大，表面有6条纵沟。"},{"q":"膝关节后交叉韧带的作用是","o":["防止胫骨前移","防止胫骨后移","防止膝关节过伸","限制膝关节旋内","限制膝关节旋外"],"a":1,"e":"后交叉韧带在屈膝时最紧张，可防止胫骨后移；前交叉韧带在伸膝时最紧张，防止胫骨前移。"},{"q":"关于纵隔的描述，正确的是","o":["位于胸膜腔内","容纳心和肺","两侧界是纵隔胸膜","下界是壁腹膜","上宽下窄"],"a":2,"e":"纵隔是两侧纵隔胸膜间全部器官、结构和结缔组织的总称，两侧界为纵隔胸膜。纵隔位于胸腔内而非胸膜腔内，上窄下宽，下界为膈。"},{"q":"紧贴于肾实质表面的是","o":["肾筋膜前层","肾筋膜后层","肾纤维囊","肾脂肪囊","脏腹膜"],"a":2,"e":"肾的被膜由内向外依次为纤维囊、脂肪囊和肾筋膜，紧贴肾实质表面的是纤维囊，坚韧致密，肾破裂时需缝合此膜。"},{"q":"腹腔干及其分支不分布到","o":["肝、胆囊","胰和脾","胃和部分十二指肠","大网膜和小网膜及食管腹段","空肠和回肠"],"a":4,"e":"空肠和回肠由肠系膜上动脉发出的空肠动脉和回肠动脉供血，不属腹腔干分布范围。腹腔干分支分布于肝、胆囊、胰、脾、胃、部分十二指肠及大网膜等。"},{"q":"关于回肠的叙述，正确的是","o":["黏膜内有孤立、集合淋巴滤泡","血管较丰富，颜色较红润","黏膜环状皱襞密而高","占小肠远侧的2/3","管径细、壁厚"],"a":0,"e":"回肠黏膜固有层和黏膜下组织内含有孤立淋巴滤泡和集合淋巴滤泡，后者多见于回肠下部。空肠血管较丰富、环状皱襞密而高，回肠管径较细、壁较薄。"},{"q":"关于甲状腺的动脉正确的是","o":["甲状腺上动脉发自颈外动脉","甲状腺下动脉直接发自锁骨下动脉","甲状腺中动脉发自颈内动脉","甲状腺最下动脉发自主动脉","两侧甲状腺的动脉间无吻合"],"a":0,"e":"甲状腺上动脉自颈外动脉起始部发出，分布于甲状腺和喉。甲状腺下动脉发自甲状颈干，并非直接起自锁骨下动脉。"},{"q":"组成射精管的是","o":["输精管末端和附睾管","输精管末端和睾丸输出小管","输精管末端和前列腺排泄管","输精管末端和精囊排泄管","输精管末端和尿道球腺排泄管"],"a":3,"e":"射精管由输精管末端与精囊的排出管汇合而成，长约2cm，穿前列腺开口于尿道前列腺部。附睾管、睾丸输出小管属输精管道，前列腺排泄管直接开口于尿道。"},{"q":"有关红骨髓的描述，正确的是","o":["成人存在于髓腔内","不存在于板障内","胎儿期造血，成年期不造血","髂骨、胸骨、椎骨内终生保存红骨髓","各个年龄都可转化为黄骨髓"],"a":3,"e":"椎骨、髂骨、肋骨、胸骨及长骨骺内终身存在红骨髓，临床常选髂前上棘或髂后上棘行骨髓穿刺。5岁后长骨骨干红骨髓被脂肪代替为黄骨髓，黄骨髓在失血或重度贫血时可转化为红骨髓。"},{"q":"成年后失去功能的内分泌器官是","o":["睾丸","垂体","胰腺","肾上腺","松果体"],"a":4,"e":"松果体合成和分泌褪黑素，抑制垂体促性腺激素释放，16岁以后逐渐钙化，功能减退。睾丸、垂体、肾上腺、胰岛成年后仍分泌激素发挥作用。"},{"q":"关于胰的描述，正确的是","o":["是人体最大的消化腺","可分为头、颈、体","只有外分泌功能","胰头被十二指肠包绕","胰管与肝总管汇合，开口十二指肠大乳头"],"a":3,"e":"胰头为胰右端膨大部分，其上、下方和右侧被十二指肠包绕。人体最大的消化腺是肝；胰分头、颈、体、尾四部；胰兼有外分泌和内分泌功能；胰管与胆总管汇合成肝胰壶腹。"},{"q":"肾实质包括","o":["肾盂","肾窦","肾皮质","肾动脉","肾大盏"],"a":2,"e":"肾实质分为肾皮质和肾髓质，肾皮质位于浅层，由肾小体和肾小管组成。肾盂、肾大盏、肾小盏属肾的排尿管道，肾窦为肾门内的腔隙。"},{"q":"椎前神经节不包括","o":["颈胸神经节","主动脉肾神经节","腹腔神经节","肠系膜下神经节","肠系膜上神经节"],"a":0,"e":"椎前神经节位于脊柱前方，包括腹腔神经节、主动脉肾神经节、肠系膜上神经节和肠系膜下神经节。颈胸神经节由颈下神经节与第1胸神经节合并而成，属椎旁神经节。"},{"q":"对视网膜具有支撑作用的结构是","o":["房水","巩膜","晶状体","玻璃体","角膜"],"a":3,"e":"玻璃体填充于晶状体与视网膜之间，对视网膜起支撑作用，使视网膜神经层与色素上皮紧贴，支撑作用减弱可致视网膜脱离。"},{"q":"使髋关节后伸并旋外的肌肉是","o":["臀大肌","髂腰肌","臀中肌","股直肌","股二头肌"],"a":0,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和臀肌粗隆，收缩时使髋关节伸和旋外。髂腰肌、股直肌屈髋，臀中肌外展髋，股二头肌屈膝。"},{"q":"关于甲状旁腺，错误的是","o":["左、右各1个","扁椭圆形小体","位于甲状腺侧叶后面","分泌激素可调节钙磷代谢","不慎被切除后，会经常出现手足抽搐"],"a":0,"e":"甲状旁腺通常有上、下两对，共4个，左、右各1个的表述错误。甲状旁腺为扁椭圆形小体，位于甲状腺侧叶后面，分泌甲状旁腺激素调节钙磷代谢；切除后血钙降低，可致手足抽搐。"},{"q":"全身最粗大的淋巴管道是","o":["胸导管","左、右颈干","右淋巴导管","左、右锁骨下干","左、右支气管纵隔干"],"a":0,"e":"胸导管是全身最粗大的淋巴管道，起自乳糜池，注入左静脉角，引流全身约3/4部位的淋巴。右淋巴导管仅引流右上肢、右胸部和右头颈部约1/4部位的淋巴。"},{"q":"关于盲肠的说法，错误的是","o":["是大肠的起始部","具有结肠带、结肠袋和肠脂垂","是腹膜间位器官","在回盲口的下方有阑尾的开口","一般位于右髂窝内"],"a":2,"e":"盲肠属腹膜内位器官，表面几乎全部被腹膜覆盖，并非腹膜间位器官。盲肠是大肠起始部，具结肠带、结肠袋和肠脂垂，一般位于右髂窝内，回盲口下方有阑尾开口。"},{"q":"关于内脏学的描述，正确的是","o":["各系统与外界不相通","包括消化、呼吸、泌尿、生殖四大系统","大部分内脏器官位于胸膜腔、腹膜腔内","消化管的管壁由3层组织构成","胸膜、腹膜与会阴不属内脏学范畴"],"a":1,"e":"内脏包括消化、呼吸、泌尿和生殖四大系统，大部分器官位于胸腔、腹腔和盆腔内。内脏器官借管道与外界相通，消化管壁由黏膜、黏膜下层、肌层和外膜4层构成。"},{"q":"脊髓中间外侧核的叙述，正确的是","o":["是交感神经节后神经元胞体","存在于脊髓全长","是交感神经低级中枢","位于板层Ⅷ","发出纤维组成盆内脏神经"],"a":2,"e":"脊髓中间带外侧核（T1～L3节段）是交感神经节前神经元胞体所在部位，即交感神经的低级中枢。其发出纤维经前根、白交通支至交感干，并非节后神经元；骶副交感核发出盆内脏神经。"},{"q":"动脉圆锥位于","o":["左心室入口下方","右心室入口下方","主动脉口下方","肺动脉口下方","肺动脉口上方"],"a":3,"e":"动脉圆锥又称右心室流出道，位于右心室前上方，内壁光滑无肉柱，其上端借肺动脉口通肺动脉干，故位于肺动脉口下方。"},{"q":"下列哪条不是肠系膜上动脉的分支","o":["空、回肠动脉","回结肠动脉","左结肠动脉","右结肠动脉","中结肠动脉"],"a":2,"e":"左结肠动脉起自肠系膜下动脉，分布于降结肠。肠系膜上动脉的分支包括空、回肠动脉，回结肠动脉、右结肠动脉和中结肠动脉。"},{"q":"主动脉的第1个分支为","o":["支气管动脉","头臂动脉","左颈总动脉","冠状动脉","肋间后动脉"],"a":3,"e":"升主动脉起始部发出左、右冠状动脉，为主动脉的第1个分支。头臂动脉、左颈总动脉和左锁骨下动脉为主动脉弓的分支。"},{"q":"听觉感受器是下列哪个结构","o":["椭圆囊斑","球囊斑","膜壶腹","螺旋器","耳蜗"],"a":3,"e":"螺旋器又称Corti器，位于蜗管基底膜上，是听觉感受器。椭圆囊斑、球囊斑和膜壶腹为前庭器官的平衡觉感受器。"},{"q":"位于中脑内的脑神经核是","o":["动眼神经副核","三叉神经运动核","疑核","红核","黑质"],"a":0,"e":"动眼神经副核（E-W核）位于中脑上丘高度，属一般内脏运动核。三叉神经运动核在脑桥，疑核在延髓；红核、黑质属中脑非脑神经核。"},{"q":"属于肾髓质的结构是","o":["肾柱","肾小盏","肾锥体","肾小球","肾盂"],"a":2,"e":"肾髓质由15～20个肾锥体构成，肾锥体底朝皮质、尖向肾窦。肾柱为伸入肾锥体间的肾皮质，肾小盏、肾盂属排尿管道。"},{"q":"输精管结扎术最常选择的部位是","o":["沿睾丸后缘行走的一段","附睾头与腹股沟浅环之间的部位","行经腹股沟管内","在盆腔中行走的部分","输精管壶腹"],"a":1,"e":"精索部介于睾丸上端与腹股沟管皮下环之间，位置表浅、易于触及，为结扎输精管的理想部位。"},{"q":"关于掌深弓的描述，错误的是","o":["位于骨间肌的浅面","位于指深屈肌腱的深面","由桡动脉的终支和尺动脉的掌深支组成","发出掌心动脉与掌浅弓相吻合","位于指浅屈肌腱的浅面"],"a":4,"e":"掌深弓位于指深屈肌腱深面，由桡动脉终支与尺动脉掌深支吻合而成，发出掌心动脉与掌浅弓吻合。指浅屈肌腱位于其浅面，故“位于指浅屈肌腱的浅面”错误。"},{"q":"关于气管杈的叙述，正确的是","o":["位于左主支气管分支的分叉处","气管杈位于第7气管软骨环","位于右主支气管分支的分叉处","气管至胸骨角平面分为左、右主支气管，其分杈处称气管杈","位于肺叶支气管的分叉处"],"a":3,"e":"气管起自环状软骨下缘，至胸骨角平面（平第4胸椎体下缘）分为左、右主支气管，分叉处称气管杈。"},{"q":"何层结构可以缓冲外力对肾的震荡","o":["肾筋膜前层","脂肪囊","肾筋膜后层","纤维囊","脏腹膜"],"a":1,"e":"脂肪囊又称肾床，为包裹肾的脂肪层，可缓冲外力对肾的震荡，临床肾囊封闭即注入此层。纤维囊紧贴肾实质，肾筋膜位于脂肪囊外面。"},{"q":"不属于肌的辅助装置的是","o":["筋膜","滑膜囊","肌间隔","籽骨","腱鞘"],"a":3,"e":"骨骼肌辅助装置包括筋膜、滑膜囊、腱鞘和籽骨。肌间隔属深筋膜结构，不属于肌的辅助装置。"},{"q":"喉腔可分为","o":["喉前庭、喉室、声门下腔","喉室、喉中间腔、声门下腔","前庭裂、喉中间腔、声门下腔","喉口、喉中间腔、声门下腔","喉前庭、喉中间腔、声门下腔"],"a":4,"e":"喉腔以前庭襞和声襞为界分为三部分：前庭襞上方为喉前庭，前庭襞与声襞之间为喉中间腔，声襞下方为声门下腔。喉室是喉中间腔向两侧的裂隙，不属独立分部。"},{"q":"关于肱动脉描述正确的是","o":["在胸大肌下缘续腋动脉","沿肱二头肌深方下行","沿肱二头肌外侧缘下行","至桡骨颈平面分为尺动脉和桡动脉","在肱二头肌腱的外侧可摸到肱动脉的搏动"],"a":3,"e":"肱动脉沿肱二头肌内侧下行至肘窝，在平桡骨颈高度分为桡动脉和尺动脉。肱动脉在肱二头肌内侧沟可触及搏动，位置表浅。"},{"q":"骶骨的正确描述是","o":["有5对骶前孔","由4块骶椎融合而成","与第4腰椎相关节","骶管内有脊髓通过","于骶角处可寻骶管裂孔进行神经阻滞麻醉"],"a":4,"e":"骶管裂孔两侧有向下突出的骶角，骶管麻醉常以骶角作为定位标志。骶骨由5块骶椎融合而成，有4对骶前孔，上接第5腰椎。"},{"q":"下列静脉，直接汇入肝门静脉的是","o":["肾静脉","胃左静脉","精索内静脉","直肠上静脉","奇静脉"],"a":1,"e":"胃左静脉是肝门静脉的属支，直接注入肝门静脉，并接受食管腹段静脉血。直肠上静脉汇入肠系膜下静脉，奇静脉属上腔静脉系。"},{"q":"颈内动脉系与基底动脉系的吻合支是","o":["大脑后动脉","前交通动脉","后交通动脉","大脑中动脉","大脑前动脉"],"a":2,"e":"后交通动脉在视束下面向后行，与大脑后动脉吻合，是颈内动脉系与椎-基底动脉系的吻合支。前交通动脉连接两侧大脑前动脉。"},{"q":"心的体表投影描述正确的是","o":["左上点在左侧第2肋软骨下缘1cm处","右上点在右侧第3肋软骨下缘1cm处","左下点在左侧第5肋间隙距胸骨左侧缘7～9cm处","左下点在左侧第5肋间隙，左侧锁骨中线内侧1～2cm处","右下点在右侧第5胸肋关节处"],"a":3,"e":"心体表投影左下点位于左侧第5肋间隙，距前正中线约7～9cm，即左锁骨中线内侧1～2cm处。左上点在左第2肋软骨下缘，右上点在右第3肋软骨上缘。"},{"q":"男性尿道的外括约肌位于","o":["尿道内口周围","尿道前列腺部周围","尿道膜部周围","尿道海绵体部周围","尿道外口周围"],"a":2,"e":"尿道膜部为尿道穿过尿生殖膈的部分，周围有横纹肌性的尿道外括约肌环绕，控制排尿。膜部位置固定，骨盆骨折时易损伤。"},{"q":"手术中寻找阑尾的可靠方法","o":["沿盲肠内侧缘寻找","沿回肠末端寻找","沿结肠带寻找","以McBurney点为标志","沿大网膜移动的方向寻找"],"a":2,"e":"3条结肠带会聚于阑尾根部，沿结肠带向下追踪是寻找阑尾的可靠方法。McBurney点仅为阑尾根部的体表投影点，不能指导术中寻找。"},{"q":"关于鼻咽的说法，下列选项中正确的是","o":["上达颅底，下至咽峡","后壁上有咽鼓管咽口连鼓室","咽隐窝是鼻咽癌的好发部位","咽鼓管圆枕与下鼻甲续连","咽隐窝是蝶窦的开口"],"a":2,"e":"咽隐窝为咽鼓管圆枕后方与咽后壁之间的纵行深窝，是鼻咽癌的好发部位。咽鼓管咽口位于鼻咽侧壁而非后壁，咽鼓管圆枕是寻找咽鼓管咽口的标志。"},{"q":"锁骨下静脉直接汇入下列何静脉","o":["颈总静脉","头臂静脉","颈内静脉","上腔静脉","颈外静脉"],"a":1,"e":"锁骨下静脉在第1肋外侧缘续于腋静脉，向内至胸锁关节后方与颈内静脉汇合成头臂静脉。颈内静脉与锁骨下静脉汇合处称静脉角，是淋巴导管注入部位。"},{"q":"临床上采血，常在下列耳的哪个部位","o":["耳屏","耳轮","耳垂","对耳屏","以上都不对"],"a":2,"e":"耳垂无软骨，仅含结缔组织和脂肪，为临床常用采血部位。耳郭外部形态为耳针定穴标志，耳垂下方即对耳屏下方。"},{"q":"屈肘并能屈肩的肌肉是","o":["三角肌","胸小肌","肱二头肌","肱肌","肱三头肌"],"a":2,"e":"肱二头肌长头起自肩胛骨盂上结节，可协助肩关节伸及内收，短头止于桡骨粗隆，能屈肘并使前臂旋后。肱肌仅屈肘，三角肌主要外展肩关节。"},{"q":"腓深神经支配","o":["股二头肌","胫骨后肌","胫骨前肌","腓骨长肌","腓骨短肌"],"a":2,"e":"腓深神经沿途分支分布于小腿前群肌、足背肌及第1、2趾相对缘皮肤，胫骨前肌属小腿前群，由腓深神经支配。腓骨长、短肌由腓浅神经支配，胫骨后肌由胫神经支配。"},{"q":"喉室位于","o":["喉中间腔内","喉前庭内","声门下腔","声门裂","喉口两侧"],"a":0,"e":"喉中间腔是喉腔中声襞与前庭襞之间的部分，向两侧经前庭襞与声襞间的裂隙至喉室。喉前庭位于喉口与前庭襞之间，声门下腔位于声襞下方。"},{"q":"椎弓的结构不包括","o":["椎弓根","关节突","横突","椎孔","棘突"],"a":3,"e":"椎弓由椎弓根、椎弓板及由此伸出的棘突、横突和关节突构成。椎孔由椎体后面与椎弓共同围成，容纳脊髓，不属椎弓结构。"},{"q":"关于第四脑室的叙述，错误的是","o":["内充满脑脊液","位于脑桥、延髓和小脑之间","借正中孔和外侧孔通蛛网膜下腔","经中脑水管通第三脑室","是最大的脑室"],"a":4,"e":"第四脑室位于延髓、脑桥和小脑之间，呈四棱锥形，内充满脑脊液，经正中孔和外侧孔通蛛网膜下隙，经中脑水管通第三脑室。侧脑室才是最大的脑室。"},{"q":"在记录牙式时，L5代表的是","o":["左上颌第2乳磨牙","左上颌第2前磨牙","右上颌第3磨牙","右上颌第2磨牙","左上颌第2磨牙"],"a":1,"e":"牙式记录中L表示左、上颌，阿拉伯数字5表示第2前磨牙，故L5为左上颌第2前磨牙。乳牙用罗马数字Ⅰ～Ⅴ标示，恒牙用阿拉伯数字1～8标示。"},{"q":"下列骨连结中，不属于间接连结的是","o":["椎间盘","肩关节","肘关节","髋关节","膝关节"],"a":0,"e":"间接连结即滑膜关节，肩、肘、髋、膝关节均属滑膜关节。椎间盘是连结相邻椎体的纤维软骨盘，属软骨连结，不具关节腔。"},{"q":"关于左肺的描述，正确的是","o":["较右肺粗大","较右肺粗短","较右肺狭长","与右肺等大","分为三叶"],"a":2,"e":"左肺狭而长，右肺宽而短，故左肺较右肺狭长。左肺借斜裂分为上、下两叶，右肺分上、中、下三叶。"},{"q":"具有屈髋关节和伸膝关节作用的肌是","o":["长收肌","半膜肌","股二头肌","股直肌","腓肠肌"],"a":3,"e":"股直肌为股四头肌的一部分，起自髂前下棘，止于胫骨粗隆，作用是屈髋关节和伸膝关节。半膜肌、股二头肌属大腿后群，作用为伸髋、屈膝。"},{"q":"下列关于输精管的描述，正确的是","o":["起于睾丸下端","全程位于精索内","是粗细一致的横纹肌性管道","末端膨大为输精管壶腹","开口于前列腺"],"a":3,"e":"输精管末端膨大形成输精管壶腹，与精囊排出管汇合成射精管。输精管起于睾丸上端，分睾丸部、精索部、腹股沟管部和盆部，并非全程位于精索内。"},{"q":"关于颏舌肌，下列说法中正确的是","o":["是成对的舌内肌","起于下颌骨的颏结节","止于舌的两侧","单侧收缩时，使舌尖伸向同侧","两侧收缩可拉舌向前下"],"a":4,"e":"颏舌肌属舌外肌，起自下颌骨颏棘，止于舌体中线两侧，两侧同时收缩拉舌向前下方即伸舌。单侧收缩使舌尖伸向对侧，一侧瘫痪时舌尖偏向瘫痪侧。"},{"q":"神经节是神经元胞体集中形成的团块，通常的位置是","o":["在中枢神经系统","在周围神经系统","中枢和周围神经系统都存在","只存在于植物神经周围部","只存在于躯体神经周围部"],"a":1,"e":"在周围神经系统中，神经元胞体聚集处称神经节，可分为脑神经节、脊神经节和内脏运动神经节。中枢部神经元胞体及树突聚集处称灰质。"},{"q":"不能限制脊柱过度前屈的结构是","o":["棘上韧带","棘间韧带","黄韧带","后纵韧带","前纵韧带"],"a":4,"e":"前纵韧带位于椎体前面，有限制脊柱过度后伸的作用；后纵韧带、黄韧带、棘间韧带和棘上韧带均有限制脊柱过度前屈的作用。"},{"q":"位于髋关节囊前部，限制大腿过度后伸的韧带是","o":["髂股韧带","耻股韧带","坐股韧带","股骨头韧带","骶结节韧带"],"a":0,"e":"髂股韧带最为坚韧，呈“人”字形经关节囊前方止于转子间线，可限制大腿过伸，对维持直立姿势有重要作用。耻股韧带限制大腿外展及旋外，坐股韧带限制旋内。"},{"q":"正常情况下，声波从外耳道传至内耳，下列途径正确的是","o":["外耳道→鼓膜→听小骨→蜗窗→外淋巴","外耳道→鼓膜→听小骨→蜗窗→内淋巴","外耳道→鼓膜一听小骨→前庭窗→外淋巴","外耳道→鼓膜→听小骨→前庭窗→内淋巴","上述都不对"],"a":2,"e":"正常空气传导为声波经外耳道引起鼓膜振动，经听小骨链放大后由镫骨底传至前庭窗，引起前庭阶外淋巴波动。蜗窗为第二鼓膜，是振动逸出部位而非传入途径。"},{"q":"下列结构接受头部变速旋转运动的刺激的是","o":["螺旋器","球囊斑和椭圆囊斑","蜗管","壶腹嵴","内淋巴"],"a":3,"e":"壶腹嵴是位于膜壶腹壁上的位置觉感受器，能感受头部旋转变速运动的刺激，冲动经前庭神经壶腹支传入。球囊斑和椭圆囊斑感受直线变速运动。"},{"q":"关于脊神经的描述哪项是错误的","o":["全身共31对","由前根和后根在椎间孔处汇合而成","均从同序数椎骨下方穿出","主要分布于躯干和四肢部位","均为混合性神经，内有四种神经纤维成分"],"a":2,"e":"脊神经穿出部位因节段而异：第2～7颈神经经同序数颈椎上方的椎间孔穿出，第8颈神经在第7颈椎下方穿出，胸、腰神经才经同序数椎骨下方椎间孔穿出。"},{"q":"关于头静脉，说法正确的是","o":["起自手背静脉网的桡侧","起自手背静脉网的尺侧","起自手掌静脉网的尺侧","起自手掌静脉网的桡侧","起自前臂静脉网的尺侧"],"a":0,"e":"头静脉起自手背静脉网的桡侧，沿前臂桡侧及肱二头肌外侧沟上行，经三角肌胸大肌间沟注入腋静脉或锁骨下静脉。贵要静脉起自手背静脉网尺侧。"},{"q":"属于上肢带骨的连结是","o":["肩锁关节","肩关节","肘关节","桡腕关节","桡尺远侧关节"],"a":0,"e":"上肢带骨连结包括胸锁关节和肩锁关节，肩锁关节由锁骨肩峰端与肩峰关节面构成，属平面关节。肩关节、肘关节、桡腕关节均属自由上肢骨连结。"},{"q":"有关尺动脉的描述，何者为错","o":["发出拇主要动脉","发出骨间总动脉至前臂深层","发掌深支参与掌深弓的组成","尺动脉与桡动脉有着广泛吻合","终支参与掌浅弓的组成"],"a":0,"e":"拇主要动脉发自桡动脉，分布于拇指两侧缘及示指桡侧缘。尺动脉发出骨间总动脉，其掌深支参与构成掌深弓，末端与桡动脉掌浅支吻合形成掌浅弓。"},{"q":"以下关于小腿三头肌的描述，正确的是","o":["由腓骨长肌和比目鱼肌构成","比目鱼肌起自胫骨的内、外侧髁后面","跟腱止于跟骨结节","可使足跖屈并内翻","可伸踝"],"a":2,"e":"腓肠肌与比目鱼肌合成粗大的跟腱，止于跟骨结节。比目鱼肌起自腓骨后面上部和胫骨比目鱼肌线，小腿三头肌可屈踝使足跖屈，并协助屈膝。"},{"q":"左肾上端约平","o":["第11胸椎体下缘","第12胸椎体中份","第1腰椎体上端","第2腰椎体下缘","第3腰椎体中份"],"a":0,"e":"左肾位于第11胸椎椎体下缘至第2～3腰椎椎间盘之间，故左肾上端约平第11胸椎体下缘。右肾上端约平第12胸椎体上缘，位置低于左肾。"},{"q":"位于延髓的结构是","o":["锥体","大脑脚","基底沟","上丘","红核"],"a":0,"e":"锥体位于延髓腹侧，锥体束在此下行并形成锥体交叉。大脑脚、上丘、红核均属中脑结构，基底沟位于脑桥。"},{"q":"支配上睑提肌的神经为","o":["视神经","眼神经","滑车神经","动眼神经","展神经"],"a":3,"e":"上睑提肌由动眼神经支配，收缩时提上睑、开大眼裂。滑车神经支配上斜肌，展神经支配外直肌，视神经司视觉。"},{"q":"不属于腹膜形成的韧带是","o":["肝圆韧带","肝胃韧带","肝十二指肠韧带","小网膜","大网膜"],"a":0,"e":"肝圆韧带由胎儿时期脐静脉闭锁而成，位于镰状韧带游离缘内，属韧带遗迹而非腹膜形成。肝胃韧带、肝十二指肠韧带、小网膜和大网膜均由腹膜构成。"},{"q":"使瞳孔转向内侧的肌是","o":["外直肌","内直肌","下直肌","上直肌","上斜肌"],"a":1,"e":"内直肌收缩使瞳孔转向内侧。外直肌使瞳孔转向外侧，下直肌转向下内，上直肌转向上内，上斜肌转向下外。"},{"q":"出入肾门的结构被结缔组织包绕称为","o":["肾柱","肾大盏","肾盂","肾蒂","肾窦"],"a":3,"e":"出入肾门的诸结构被结缔组织包裹，称肾蒂。肾窦为肾门伸入肾实质的腔隙，肾柱为肾皮质伸入髓质的部分。"},{"q":"属于腹膜外位器官的是","o":["脾","直肠上段","输尿管","胆囊","子宫"],"a":2,"e":"输尿管仅一面被腹膜覆盖，属腹膜外位器官。脾为腹膜内位器官，胆囊、子宫、直肠上段为腹膜间位器官。"},{"q":"在头面部，能活动的颅骨是","o":["下鼻甲","上颌骨","腭骨","下颌骨","上鼻甲"],"a":3,"e":"下颌骨借颞下颌关节与颞骨相连，是头面部唯一能活动的颅骨。上颌骨、腭骨、下鼻甲等均以骨缝或骨性结合固定。"},{"q":"有关十二指肠的叙述，正确的是","o":["升部即十二指肠球部，是溃疡好发部位","分为升部、降部、水平部三部分","全为腹膜内位器官","降部的前壁有十二指肠小乳头","降部的后内壁有十二指肠大乳头"],"a":4,"e":"十二指肠降部后内侧壁内与胰管汇合成肝胰壶腹，开口于十二指肠大乳头。十二指肠分上部、降部、水平部和升部，上部又称十二指肠球部，为溃疡好发部位。"},{"q":"腰丛位于","o":["腰方肌深面","腰大肌深面","腰大肌浅层","梨状肌浅层","梨状肌深面"],"a":1,"e":"腰丛位于腰大肌深面、腰椎横突前方，由此发出髂腹下神经等分支。腰方肌位于腰大肌后方，并非腰丛所在部位。"},{"q":"关于肩胛骨形态的描述，错误的是","o":["为三角形扁骨","位于胸廓后外侧的上份","可分为内、外面","内侧缘薄而锐利","关节盂位于外侧角"],"a":2,"e":"肩胛骨为三角形扁骨，分前面和后面两面，前面为肩胛下窝，后面被肩胛冈分为冈上窝和冈下窝。关节盂位于外侧角，内侧缘薄而锐利。"},{"q":"关于输胆管道的描述，正确的是","o":["胆总管长4～8cm","胆总管走行于肝胃韧带内","胆总管走行于肝固有动脉的左侧","肝左管与肝右管汇合成胆总管","胆囊管与胰管汇合成肝胰壶腹"],"a":0,"e":"胆总管由肝总管与胆囊管汇合而成，长约4～8cm，直径0.6～0.8cm。其行于肝十二指肠韧带内，位于肝固有动脉右侧、肝门静脉前方。"},{"q":"可以固定子宫颈，防止子宫向下脱垂的韧带是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":3,"e":"子宫主韧带位于阔韧带基部，从子宫颈两侧缘延伸至盆侧壁，是维持子宫颈正常位置、防止子宫脱垂的重要结构。子宫圆韧带主要维持子宫前倾。"},{"q":"产生房水的结构是","o":["睫状体","晶状体","虹膜","脉络膜","视网膜"],"a":0,"e":"房水由睫状体产生，进入眼后房，经瞳孔至眼前房，再经虹膜角膜角进入巩膜静脉窦。睫状体还通过睫状小带调节晶状体曲度。"},{"q":"连结下肢骨与躯干骨的关节是","o":["腰骶关节","骶髂关节","耻骨联合","髋关节","关节突关节"],"a":1,"e":"骶髂关节由骶骨与髂骨的耳状面构成，是下肢骨与躯干骨之间的连结，关节囊紧张并有韧带加强，稳固性强。"},{"q":"膈的食管裂孔位置高度","o":["平第8胸椎","平第9胸椎","平第10胸椎","平第11胸椎","平第12胸椎"],"a":2,"e":"食管裂孔位于主动脉裂孔左前上方，约平第10胸椎水平，有食管和迷走神经通过。腔静脉孔平第8胸椎，主动脉裂孔平第12胸椎。"},{"q":"颅中窝骨折患者，血性脑脊液经鼻腔流出，可能伤及的鼻旁窦是","o":["额窦","筛窦","上颌窦","蝶窦","上颌窦和额窦"],"a":3,"e":"蝶窦位于蝶骨体内、鼻腔上部后方，其窦口开口于蝶筛隐窝，与颅中窝相邻，颅中窝骨折时硬脑膜与蛛网膜撕裂，脑脊液可经蝶窦由鼻腔流出形成鼻漏。额窦、筛窦、上颌窦均不直接与颅中窝相邻。"},{"q":"以下对舌下神经的描述，正确的是","o":["为第Ⅺ对脑神经","支配舌肌运动","管理舌的味觉","管理舌的一般感觉","一侧舌下神经损伤，伸舌时舌尖偏向健侧"],"a":1,"e":"舌下神经为第Ⅻ对脑神经，由舌下神经核发出一般躯体运动纤维，支配舌内、外肌的随意运动。味觉由面神经和舌咽神经管理，一般感觉由三叉神经管理；一侧损伤伸舌时舌尖偏向患侧。"},{"q":"运动性语言中枢多位于左大脑半球的","o":["缘上回","角回","扣带回","颞横回","额下回后部"],"a":4,"e":"运动性语言中枢即Broca区，位于额下回后1/3部（44、45区），即三角部后部和岛盖部，受损出现运动性失语症。缘上回、角回属Wernicke区，颞横回为听觉中枢。"},{"q":"交感神经的低级中枢位于","o":["脊髓T1～L3节段的灰质侧柱的中间外侧核","交感神经节","腹腔神经节","椎前神经节","脑干的一般内脏运动核"],"a":0,"e":"交感神经节前神经元胞体位于脊髓T1～L3节段灰质侧柱的中间带外侧核，故称胸腰部，发出纤维经前根、白交通支入交感干。交感神经节、椎前神经节为节后神经元胞体所在部位。"},{"q":"下列关于上矢状窦的描述，正确的是","o":["成对","穿过颈静脉孔","产生脑脊液","位于硬脑膜与颅盖骨之间","接受脑脊液"],"a":4,"e":"脑脊液经蛛网膜粒渗透入上矢状窦回流入血液，故上矢状窦接受脑脊液。上矢状窦为单一硬脑膜窦，位于颅盖骨内面硬脑膜内，不产生脑脊液，脑脊液由脉络丛产生。"},{"q":"关于贵要静脉的叙述正确的是","o":["起自手背静脉网的桡侧","于肘关节后方接受肘正中静脉","注入肱静脉","收集前臂桡侧的浅静脉血","沿肱二头肌外侧沟上行"],"a":2,"e":"贵要静脉起自手背静脉网尺侧，沿前臂尺侧上行，经肱二头肌内侧沟至臂中点穿深筋膜注入肱静脉或伴肱静脉上行注入腋静脉。肘正中静脉在肘窝处注入贵要静脉，其收集尺侧浅静脉血。"},{"q":"下列关于椎间盘的叙述中，正确的是","o":["在成人共有25块","椎间盘突出时，多突向后外方","脊柱运动时，椎间盘形状不发生改变","椎间盘突出多发生脊柱胸段","黄韧带可防止椎间盘向后突出"],"a":1,"e":"纤维环破裂时髓核易向后外侧脱出，突入椎管或椎间孔压迫脊髓或脊神经根，故椎间盘突出多向后外方。成人椎间盘共23个，腰部最厚活动度大故突出多见，黄韧带位于椎弓板间不防椎间盘后突。"},{"q":"下面结构中通过腕管的是","o":["尺侧腕屈肌","正中神经","掌长肌腱","桡侧腕屈肌腱","桡侧腕长伸肌"],"a":1,"e":"腕管由腕骨沟与屈肌支持带围成，正中神经与指浅、指深屈肌腱及拇长屈肌腱通过其中，正中神经受压出现腕管综合征。尺侧腕屈肌、掌长肌腱、桡侧腕屈肌腱均位于腕管之外。"},{"q":"对膀胱的描述，错误的是","o":["是储尿的器官","男性膀胱下方邻接尿生殖膈","空虚时，膀胱尖不超过耻骨联合上缘","肌层由平滑肌构成","是腹膜间位器官"],"a":1,"e":"膀胱是腹膜间位器官，空虚时膀胱尖不超过耻骨联合上缘，肌层由平滑肌构成，功能为储尿。男性膀胱下方邻接前列腺，而非尿生殖膈。"},{"q":"营养内囊的动脉主要是","o":["椎动脉","大脑中动脉","大脑后动脉","颈内动脉","基底动脉"],"a":1,"e":"大脑中动脉发出豆纹动脉，垂直穿前穿质进入脑实质，营养尾状核、豆状核及内囊膝和后肢前部。椎动脉、基底动脉和大脑后动脉不供应内囊。"},{"q":"前庭蜗器包括","o":["骨半规管、前庭和耳蜗","鼓室、咽鼓管和乳突小房","外耳、中耳和内耳","外耳道、鼓膜和鼓室","骨迷路和膜迷路"],"a":2,"e":"前庭蜗器又称耳，包括外耳、中耳和内耳三部分。骨迷路与膜迷路属内耳结构，鼓室、咽鼓管和乳突小房属中耳结构。"},{"q":"下列结构中不含脑脊液的是","o":["蛛网膜下腔","小脑延髓池","终池","硬膜外隙","脊髓中央管"],"a":3,"e":"脑脊液充满脑室系统、蛛网膜下隙和脊髓中央管，蛛网膜下腔、小脑延髓池、终池均属蛛网膜下隙。硬膜外隙位于硬脊膜与椎管骨膜之间，内含脂肪、静脉丛等，不含脑脊液。"},{"q":"支配躯干四肢骨骼肌随意运动的下运动神经元是","o":["锥体细胞","前角运动细胞","后角细胞","侧角细胞","双极细胞"],"a":1,"e":"脊髓前角运动神经元发出躯体运动纤维，分布于躯干和四肢骨骼肌，支配随意运动。锥体细胞是上运动神经元，后角、侧角细胞分别与感觉、内脏运动有关。"},{"q":"下列结构中属于关节辅助结构的是","o":["关节头","关节窝","关节唇","关节腔","关节囊"],"a":2,"e":"关节的辅助结构包括韧带、关节盘、关节唇、滑膜襞和滑膜囊，关节唇可加深关节窝、增加稳固性。关节头、关节窝、关节腔和关节囊属关节基本结构。"},{"q":"在呼吸道中，唯一具有完整软骨环的软骨是","o":["甲状软骨","环状软骨","会厌软骨","气管软骨环","杓状软骨"],"a":1,"e":"环状软骨是喉软骨中唯一完整的软骨环，位于甲状软骨下方。甲状软骨、会厌软骨和杓状软骨均不完整，气管软骨环呈马蹄形，后壁不完整。"},{"q":"关于椎动脉的叙述，正确的是","o":["穿行第1～7颈椎横突孔","发自颈总动脉","经枕骨大孔入颅腔","参与构成大脑动脉环","发自大脑中动脉"],"a":2,"e":"椎动脉起自锁骨下动脉，穿第6至第1颈椎横突孔，经枕骨大孔入颅腔，左右汇合成基底动脉。椎动脉不穿第7颈椎横突孔，也不直接参与构成大脑动脉环。"},{"q":"喉腔内最狭窄的部位是","o":["声门下腔","前庭裂","喉室","声门裂","喉前庭"],"a":3,"e":"声门裂是两侧声襞与杓状软骨底和声带突之间的裂隙，较前庭裂长而窄，为喉腔最狭窄之处。"},{"q":"关于食管的第一个狭窄，下列选项说法正确的是","o":["食管与左主支气管交叉处","约平第6颈椎体的上缘","距中切牙约15cm","平对胸骨角","距中切牙约25cm"],"a":2,"e":"食管第1狭窄位于食管起始处，相当于第6颈椎椎体下缘水平，距中切牙约15cm。第2狭窄位于左主支气管后方交叉处，距中切牙约25cm。"},{"q":"乳突是下面哪块骨上的结构","o":["蝶骨","颞骨","颧骨","枕骨","额骨"],"a":1,"e":"乳突位于颞骨，中耳炎可经乳突窦侵犯乳突小房引起乳突炎。颞骨参与构成颅腔底和颅盖。"},{"q":"使瞳孔转向下外的肌是","o":["上斜肌","下斜肌","外直肌","内直肌","下直肌"],"a":0,"e":"上斜肌起于蝶骨体，经滑车转向后外止于眼球赤道后方巩膜，收缩使瞳孔转向下外。下斜肌使瞳孔转向上外。"},{"q":"可以做环转运动的关节是","o":["肩关节","肘关节","指骨间关节","骶髂关节","关节突关节"],"a":0,"e":"环转运动是屈、展、伸、收依次结合的连续动作，能沿两轴以上运动的关节方可完成，肩关节为球窝关节，可作环转运动。"},{"q":"关于十二指肠，下列说法正确的是","o":["呈“C”形包绕胰头","只接受胃液和胆汁注入","全部由腹腔干分支供血","为腹膜外位器官","分为三部"],"a":0,"e":"十二指肠整体呈C形，包绕胰头，分为上部、降部、水平部和升部四部。"},{"q":"上消化道是指","o":["口腔至食管","口腔至回肠","口腔至空肠","口腔至十二指肠","口腔至胃"],"a":3,"e":"临床上通常把从口腔到十二指肠的这部分管道称上消化道，空肠以下的部分称下消化道。"},{"q":"关于颈椎，正确的是","o":["均有椎体及椎弓","第1～2颈椎无横突孔","棘突末端都分叉","第6颈椎棘突末端膨大成颈动脉结节","第7颈椎又名隆椎"],"a":4,"e":"第7颈椎又名隆椎，棘突长，末端不分叉，活体易于触及，常作为计数椎骨序数的标志。寰椎无椎体，第1～7颈椎均有横突孔。"},{"q":"以下属于副交感神经核的是","o":["面神经核","舌下神经","动眼神经核","迷走神经背核","展神经核"],"a":3,"e":"迷走神经背核属副交感神经核，发出副交感节前纤维随迷走神经分布于胸、腹腔脏器。面神经核、动眼神经核、舌下神经核及展神经核均为躯体运动核。"},{"q":"与脑的血供无关的动脉是","o":["颈内动脉","椎动脉","基底动脉","脑膜中动脉","前、后交通动脉"],"a":3,"e":"脑膜中动脉穿棘孔入颅，分布于颅骨和硬脑膜，不参与脑的血液供应。颈内动脉、椎动脉及基底动脉、前后交通动脉均属脑的供血动脉。"},{"q":"上颌窦开口于","o":["上鼻道","中鼻道","下鼻道","咽隐窝","蝶筛隐窝"],"a":1,"e":"上颌窦开口于中鼻道的半月裂孔，因开口位置较高，窦腔积液时需体位引流。前、中筛窦开口于中鼻道，后筛窦开口于上鼻道，蝶窦开口于蝶筛隐窝。"},{"q":"受桡神经支配的骨骼肌为","o":["三角肌","肱三头肌","肱肌","喙肱肌","背阔肌"],"a":1,"e":"桡神经肌支主要分布于肱三头肌、肘肌、肱桡肌和桡侧腕长伸肌。三角肌由腋神经支配，肱肌和喙肱肌由肌皮神经支配，背阔肌由胸背神经支配。"},{"q":"做外耳道检查时，在成人应将耳廓拉向","o":["前上方","后上方","前下方","后下方","后方"],"a":1,"e":"成人外耳道呈弯曲状，检查鼓膜时需将耳郭向后上方牵拉，使外耳道变直方可窥见。婴儿外耳道短而直，须将耳郭拉向后下方。"},{"q":"关于心的位置，下列说法正确的是","o":["位于上纵隔","2/3在正中线的右侧","1/3在正中线的左侧","前面和两侧被肺与胸膜包裹","外面包有心包"],"a":4,"e":"心位于中纵隔，外面包有心包。约2/3位于正中线左侧、1/3位于右侧，前面大部分被肺和胸膜遮盖，两侧为肺与胸膜。"},{"q":"体循环起始于","o":["左心室","右心室","左心房","右心房","毛细血管"],"a":0,"e":"体循环起于左心室，动脉血经主动脉及其分支流向全身，经毛细血管交换后由静脉回流入右心房。肺循环起于右心室。"},{"q":"乳腺脓肿切开引流应采用的切口","o":["横切口","纵切口","斜切口","放射状切口","乳房下切口"],"a":3,"e":"乳腺叶和输乳管均以乳头为中心呈放射状排列，故脓肿切开引流宜做放射状切口，以免损伤输乳管。乳房后间隙脓肿宜在乳房下缘做弧形切口。"},{"q":"关于横结肠的说法，正确的是","o":["与小网膜相连","无肠脂垂","位于左上腹部","属于腹膜间位器官","有系膜"],"a":4,"e":"横结肠由横结肠系膜连于腹后壁，属腹膜内位器官，系膜根部自结肠右曲跨至结肠左曲。横结肠表面有肠脂垂，位于结肠上区而非左上腹，与小网膜相连的是胃。"},{"q":"关于垂体的描述，正确的是","o":["位于颅前窝的垂体窝内","神经垂体分泌抗利尿激素","一般女性的垂体较男性的大","腺垂体和神经垂体都具有内分泌功能","腺垂体分泌的促甲状腺素由神经垂体释放"],"a":2,"e":"教材载成年人垂体重约0.5～0.6g，女性略大于男性，妊娠期显著增大。垂体位于颅底蝶鞍垂体窝内；神经垂体储存并释放下丘脑合成的抗利尿激素；促甲状腺素由腺垂体分泌释放。"},{"q":"鼻咽侧壁上的结构是","o":["咽鼓管咽口","舌扁桃体","腭扁桃体","蝶筛隐窝","梨状隐窝"],"a":0,"e":"鼻咽侧壁下鼻甲后方约1cm处有咽鼓管咽口，经咽鼓管通鼓室。舌扁桃体位于舌根，腭扁桃体位于口咽侧壁扁桃体窝，蝶筛隐窝位于鼻腔，梨状隐窝位于喉咽。"},{"q":"肝的右纵沟后半部通过的结构是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","动脉导管"],"a":3,"e":"肝的右纵沟后半部为腔静脉沟，容纳下腔静脉，沟上端有肝左、中、右静脉注入下腔静脉处即第二肝门。肝圆韧带和静脉韧带分别位于左纵沟的前、后部。"},{"q":"关于乳糜池的描述，正确的是","o":["为成对的梭形膨大","位于第2腰椎体前方","由左、右腰干汇合而成","右淋巴导管起始于乳糜池","由左、右腰干和肠干汇合而成"],"a":4,"e":"乳糜池位于第1腰椎前方，呈囊状膨大，接受左、右腰干和肠干的淋巴，为胸导管的起始部。右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成。"},{"q":"下列关于脊髓内部结构的说法，正确的是","o":["中央管向上直接通第三脑室，内有脑脊液","由灰质、白质、神经核和神经纤维组成","中央管位于灰质连合的中央","前角基部外侧有网状结构","灰质连合与前正中裂之间的白质为白质连合"],"a":2,"e":"脊髓横切面中央有细小的中央管，位于H形灰质连合的中央，内含脑脊液，向上通第四脑室。白质连合位于灰质连合与前正中裂之间，由交叉纤维构成。"},{"q":"锁骨下静脉的收集范围包括","o":["甲状腺静脉","面静脉","舌静脉","颈外静脉","颈内静脉"],"a":3,"e":"锁骨下静脉的主要属支是腋静脉和颈外静脉，故其收集范围包括颈外静脉。颈内静脉收集颅内及面、舌、甲状腺等处的静脉血，面静脉、舌静脉、甲状腺静脉均属颈内静脉属支。"},{"q":"关于牙的叙述，正确的是","o":["每个牙分为牙冠、牙根和牙腔三部分","乳牙分为切牙、尖牙和磨牙三种类型","幼儿3岁乳牙开始脱落","牙髓由血管、淋巴管和结缔组织构成","是人体中唯一没有血管的器官"],"a":1,"e":"乳牙和恒牙均按形状和功能分为切牙、尖牙和磨牙，恒牙另有前磨牙。每个牙分为牙冠、牙颈和牙根三部分；乳牙约6岁开始脱落；牙髓含血管、淋巴管和结缔组织，牙本质等无血管。"},{"q":"下列关于精囊腺的描述，正确的是","o":["为囊状不成对器官","位于输精管壶腹的内侧","位于膀胱底的上方","通过直肠前壁可以触及","前邻前列腺"],"a":3,"e":"精囊腺位于膀胱底后方、输精管壶腹外侧，前邻膀胱底，直肠指检可经直肠前壁触及。精囊腺为成对囊状器官，位于输精管壶腹外侧而非内侧。"},{"q":"有关腱鞘的描述，正确的是","o":["腱位于滑液鞘内","由腱纤维鞘和腱滑膜鞘组成","腱系膜由腱纤维鞘形成","腱纤维鞘分为壁层和脏层","腱滑膜鞘由深筋膜增厚形成"],"a":1,"e":"腱鞘由外层的腱纤维鞘和内层的腱滑膜鞘构成。腱滑膜鞘分脏层和壁层，腱系膜由滑膜层移行形成；腱纤维鞘由深筋膜增厚形成。"},{"q":"和中脑脚间窝相连的神经根为","o":["视神经","动眼神经","滑车神经","展神经","面神经"],"a":1,"e":"动眼神经根连于脚间窝下部、大脑脚内侧，由动眼神经核和动眼神经副核发出的纤维组成。滑车神经根连于下丘下方，展神经根连于延髓脑桥沟。"},{"q":"下列骨骼肌中不受正中神经支配的为","o":["肱桡肌","旋前圆肌","桡侧腕屈肌","指浅屈肌","旋前方肌"],"a":0,"e":"肱桡肌由桡神经支配，正中神经支配旋前圆肌、桡侧腕屈肌、指浅屈肌和旋前方肌等前臂屈肌及旋前肌。"},{"q":"有关节内软骨的关节是","o":["肩关节","肘关节","髋关节","膝关节","距小腿关节"],"a":3,"e":"膝关节内有前、后交叉韧带及内、外侧半月板等关节内软骨结构。肩、肘、髋、距小腿关节均无关节内软骨。"},{"q":"主动脉弓的描述何者有误","o":["是主动脉的第2段","位于胸骨柄的后方","弓形弯向左后方","凸缘的分支自右至左是头臂干、左锁骨下动脉、左颈总动脉","至第4胸椎体下缘平面与胸主动脉相续"],"a":3,"e":"主动脉弓凸缘分支自右向左依次为头臂干、左颈总动脉、左锁骨下动脉。主动脉弓位于胸骨柄后方，呈弓形弯向左后方，至第4胸椎体下缘续为胸主动脉。"},{"q":"使瞳孔转向上外的肌是","o":["上斜肌","下斜肌","外直肌","内直肌","上直肌"],"a":1,"e":"下斜肌起自眶下壁前内侧，止于眼球下面赤道后方巩膜，收缩使瞳孔转向上外。上斜肌使瞳孔转向下外，上直肌使瞳孔转向上内。"},{"q":"中枢神经系统中，神经元胞体聚集构成的结构是","o":["神经核","纤维束","网状结构","神经节","神经"],"a":0,"e":"中枢神经系统内形态和功能相似的神经元胞体聚集成团或柱称神经核。神经节为周围部神经元胞体聚集，纤维束为中枢部神经纤维聚集。"},{"q":"肝的左纵沟前半部容纳的是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","镰状韧带"],"a":0,"e":"肝圆韧带由胎儿期脐静脉闭锁而成，经镰状韧带游离缘行至脐，位于左纵沟前部的肝圆韧带裂内。静脉韧带位于左纵沟后部。"},{"q":"下列关于附睾的描述，正确的是","o":["为男性生殖腺","全部由附睾管构成","贴附于睾丸前缘","为附属腺之一","下连输精管"],"a":4,"e":"附睾是生殖管道的一部分，上端连睾丸，下端续接输精管，为附睾管的直接延续。睾丸才是男性生殖腺，附睾贴附于睾丸后缘。"},{"q":"有关心的后方，何者为错","o":["平对第5～8胸椎","有胸主动脉","有食管","有迷走神经","主要是右心房"],"a":4,"e":"心的后方平对第5～8胸椎，隔心包有胸主动脉、食管、迷走神经等结构；而构成心底的主要是左心房，右心房位于心的右上部。"},{"q":"下列关于肩关节的叙述中，正确的是","o":["由肱骨头和肩胛骨关节盂构成","关节盂较大而深","关节内有关节盘","关节囊内有肱三头肌长头肌腱通过","只能做屈伸、旋转运动"],"a":0,"e":"肩关节由肱骨头与肩胛骨关节盂构成，属典型多轴球窝关节。关节盂浅小仅容纳关节头1/4～1/3，囊内无关节盘，可作屈伸、收展、旋转和环转运动。"},{"q":"组成臂丛的纤维是","o":["第5～8颈神经前支和第1胸神经前支的大部分纤维","第5～8颈神经前支和第1胸神经前支的小部分纤维","第5～8颈神经和第1胸神经的大部分纤维","第5～7颈神经前支和第1胸神经前支的大部分纤维","第5～7颈神经前支和第1胸神经前支的小部分纤维"],"a":0,"e":"臂丛由第5～8颈神经前支和第1胸神经前支的大部分纤维交织而成，经斜角肌间隙、锁骨后方进入腋窝。"},{"q":"位于前臂肌前群浅层最外侧的肌肉是","o":["肱二头肌","肱三头肌","喙肱肌","肱桡肌","桡侧腕屈肌"],"a":3,"e":"前臂肌前群浅层自桡侧向尺侧依次为肱桡肌、旋前圆肌、桡侧腕屈肌、掌长肌、尺侧腕屈肌，故最外侧为肱桡肌。肱二头肌、肱三头肌、喙肱肌均属臂肌。"},{"q":"临床上后尿道是指","o":["尿道海绵体部","尿道膜部和前列腺部","尿道膜部","尿道膜部和海绵体部","尿道海绵体部和前列腺部"],"a":1,"e":"男性尿道分前列腺部、膜部和海绵体部，临床上将尿道前列腺部和膜部合称后尿道，海绵体部称前尿道。"},{"q":"支配股四头肌的神经为","o":["闭孔神经","坐骨神经","股神经","髂腹下神经","髂腹股沟神经"],"a":2,"e":"股四头肌由股神经支配，股神经肌支分布于髂肌、耻骨肌、股四头肌和缝匠肌。闭孔神经支配大腿内侧群肌，坐骨神经支配大腿后群肌。"},{"q":"近侧列腕骨不包括","o":["手舟骨","月骨","三角骨","钩骨","豌豆骨"],"a":3,"e":"钩骨属远侧列腕骨。近侧列由桡侧向尺侧依次为手舟骨、月骨、三角骨和豌豆骨，远侧列为大多角骨、小多角骨、头状骨和钩骨。"},{"q":"关于椎体的说法，错误的是","o":["呈短圆柱状","位于椎骨前部","主要由松质构成","表面有一层密质","椎体中央有椎孔"],"a":4,"e":"椎孔由椎体后面与椎弓共同围成，各椎孔上下贯通构成椎管，椎体中央并无椎孔。椎体呈短圆柱状，位于椎骨前部，内部充满松质，表面密质较薄。"},{"q":"肝上界与右锁骨中线相交的肋是","o":["第7肋","第5肋","第6肋","第8肋","第9肋"],"a":1,"e":"肝上界与膈穹窿一致，右锁骨中线与第5肋的交点为其标志点之一。肝下界右侧与右肋弓一致。"},{"q":"以下哪项属于内分泌组织","o":["胸腺","垂体","胰岛","松果体","肾上腺"],"a":2,"e":"胰岛为散在于胰实质内的细胞团，属内分泌组织。胸腺、垂体、松果体和肾上腺均为独立的内分泌腺器官。"},{"q":"关于海绵窦的叙述中，错误的是","o":["位于垂体窝两侧","窦内充满静脉血","窦内充满脑脊液","外侧壁有动眼神经、滑车神经通过","内侧壁有展神经通过"],"a":2,"e":"海绵窦属硬脑膜窦，窦内充满静脉血而非脑脊液。脑脊液位于蛛网膜下隙和脑室系统内，经蛛网膜粒回流入硬脑膜窦。"},{"q":"拇指腕掌关节由第1掌骨与哪块骨构成","o":["手舟骨","桡骨下端","尺骨下端","大多角骨","小多角骨"],"a":3,"e":"拇指腕掌关节由大多角骨与第1掌骨底构成，属鞍状关节，可作屈、伸、收、展、环转和对掌运动。"},{"q":"下列颈丛组成的描述，正确的是","o":["第1～4颈神经全部","第1～4颈神经前支","第1～4颈神经后支","第1～3颈神经前支全部和第4颈神经前支大部分","第1～3颈神经前支全部和第4颈神经前支小部分"],"a":1,"e":"颈丛由第1～4颈神经前支相互交织构成，位于胸锁乳突肌上部深面。脊神经前支构成神经丛，后支不参与。"},{"q":"头面部浅感觉传导通路的第3级神经元是","o":["锥体细胞","三叉神经脊束核","三叉神经脑桥核","丘脑腹后内侧核","丘脑腹后外侧核"],"a":3,"e":"头面部浅感觉传导通路第3级神经元胞体位于背侧丘脑腹后内侧核，发出纤维经内囊后肢投射至中央后回下部。腹后外侧核接受躯干四肢的感觉纤维。"},{"q":"有关前、中、后斜角肌的描述，正确的是","o":["构成颈深肌群的外侧群","起自颈椎椎体的前面","止于第1肋","斜角肌间隙内通过锁骨下动脉和静脉","收缩可助呼气"],"a":0,"e":"前、中、后斜角肌位于脊柱颈段两侧，共同构成颈深肌群的外侧群。三肌分别止于第1肋上面、第1肋上面和第2肋上面，收缩可上提肋助吸气。斜角肌间隙内有锁骨下动脉和臂丛通过，锁骨下静脉位于前斜角肌前方。"},{"q":"可以维持子宫前屈位的韧带是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":4,"e":"子宫骶韧带由平滑肌和结缔组织构成，从子宫颈后面向后绕过直肠止于第2、3骶椎前面，向后上牵引子宫颈，协同子宫圆韧带维持子宫前倾前屈位。子宫主韧带维持子宫颈位置、防止子宫脱垂，子宫圆韧带维持前倾。"},{"q":"垂体窝位于下面哪块颅骨上","o":["额骨","颞骨","顶骨","筛骨","蝶骨"],"a":4,"e":"垂体窝位于蝶骨体上面，呈马鞍状，中央凹陷容纳垂体。蝶骨体两侧有颈动脉沟，颈内动脉经颈动脉管入颅后行于此沟。"},{"q":"一侧皮质核束不支配","o":["同侧的动眼神经核","对侧的三叉神经运动核","对侧的滑车神经核","同侧的舌下神经核","对侧的疑核"],"a":3,"e":"舌下神经核仅接受对侧皮质核束纤维的传入，故一侧皮质核束不支配同侧舌下神经核。动眼神经核、滑车神经核、三叉神经运动核和疑核均接受双侧皮质核束纤维。"},{"q":"关于骶骨描述，正确的是","o":["由3块骶椎组成","骶前孔、骶后孔均与骶管相通","骶骨的耳状面与髋骨的耳状面相连，属直接连接","骶管与椎管不通","女性骶岬较男性突出"],"a":1,"e":"骶前孔、骶后孔分别有骶神经前、后支通过，均与骶管相通。骶骨由5块骶椎融合而成；耳状面与髋骨耳状面构成骶髂关节，属间接连接；骶管上端通连椎管。"},{"q":"上颌神经通过颅底什么结构出颅","o":["眶上裂","圆孔","卵圆孔","棘孔","颈静脉孔"],"a":1,"e":"上颌神经含一般躯体感觉纤维，经海绵窦外侧壁穿圆孔出颅进入翼腭窝。眶上裂通过眼神经，卵圆孔通过下颌神经，棘孔通过脑膜中动脉，颈静脉孔通过舌咽、迷走、副神经。"},{"q":"关于主支气管描述正确的是","o":["左主支气管短、粗且走向较垂直","是喉至肺之间的管道","是气管杈至肺门之间的管道","右主支气管长、细且走向较垂直","右主支气管短、细且走向较水平"],"a":2,"e":"主支气管是气管杈与肺门之间的通气管道。左主支气管细长、走向较水平；右主支气管短粗、走向较垂直，异物易坠入右侧。气管是喉至气管杈之间的管道。"},{"q":"有关面神经的叙述，错误的是","o":["为第Ⅶ对脑神经","管理舌前2/3黏膜的味觉","控制腮腺的分泌","支配面肌的运动","控制泪腺的分泌"],"a":2,"e":"腮腺的分泌由舌咽神经的副交感纤维经耳神经节换元后控制，面神经不控制腮腺分泌。面神经为第Ⅶ对脑神经，其纤维管理舌前2/3味觉、支配面肌运动并控制泪腺等分泌。"},{"q":"关于肺下界的体表投影，下列说法正确的是","o":["在锁骨中线与第8肋相交","在腋中线与第10肋相交","在腋前线与第10肋相交","在肩胛线与第11肋相交","近后正中线处平第10胸椎棘突"],"a":4,"e":"肺下缘在锁骨中线与第6肋相交，腋中线与第8肋相交，肩胛线与第10肋相交，近后正中线处平第10胸椎棘突。"},{"q":"头臂静脉的收集范围不包括","o":["心脏","颅骨","颈部","上肢","脑"],"a":0,"e":"头臂静脉由颈内静脉和锁骨下静脉汇合而成，收集颅骨、脑、颈部及上肢的静脉血。心脏的静脉血经冠状窦等直接回流入右心房，不属头臂静脉收集范围。"},{"q":"新纹状体是指","o":["豆状核","尾状核和壳","尾状核和苍白球","壳","苍白球"],"a":1,"e":"尾状核和壳在种系发生上较新，合称新纹状体；苍白球较旧，称旧纹状体。"},{"q":"从侧面观察，脊柱有","o":["向后凸的颈曲","向前凸的胸曲","向后凸的腰曲","向前凸的骶曲","23对椎间孔"],"a":4,"e":"成人脊柱侧面观有颈、胸、腰、骶4个生理性弯曲，颈曲和腰曲凸向前，胸曲和骶曲凸向后。"},{"q":"翼腭神经节发出的节后纤维支配","o":["瞳孔括约肌","睫状肌","腮腺","泪腺","瞳孔开大肌"],"a":3,"e":"翼腭神经节为副交感神经节，其节后纤维分布于泪腺及鼻腔、腭的黏膜腺。瞳孔括约肌和睫状肌由睫状神经节支配，腮腺由耳神经节支配。"},{"q":"躯干骨在体表易摸到的骨性标志是","o":["肋凹","肋沟","胸椎横突","胸骨角","骶岬"],"a":3,"e":"胸骨角位于胸骨柄与胸骨体连接处，微向前突，体表可扪及，两侧平对第2肋，是计数肋的重要标志。肋凹、肋沟、胸椎横突及骶岬均位置深在，体表不易触及。"},{"q":"关于胃分部的叙述，不正确的是","o":["胃底在临床上有时称为胃穹窿","通常将胃分为4部分","贲门附近的区域称为贲门部","自胃底至角切迹的部分称胃体","幽门部的左侧部分称为幽门管"],"a":4,"e":"幽门部借中间沟分为右侧的幽门管和左侧的幽门窦，故“左侧部分为幽门管”错误。通常胃分贲门部、胃底、胃体和幽门部4部。"},{"q":"有结肠带的肠管是","o":["直肠","盲肠","回肠","阑尾","肛管"],"a":1,"e":"结肠和盲肠具有结肠带、结肠袋和肠脂垂3个特征性结构，结肠带由纵行肌增厚形成。直肠、阑尾和肛管无结肠带。"},{"q":"下列关于肩关节的叙述中，错误的是","o":["由肱骨头和肩胛骨关节盂构成","肱骨头大，关节盂小而浅","关节内有关节盘","关节囊内有肱二头肌长头肌腱通过","是全身运动最灵活的关节"],"a":2,"e":"肩关节由肱骨头与肩胛骨关节盂构成，关节盂小而浅，囊内有肱二头肌长头腱通过，是全身最灵活的关节。肩关节囊内无关节盘，关节盘见于下颌关节、胸锁关节等。"},{"q":"臂丛由何处穿出经锁骨后方进入腋窝","o":["胸锁乳突肌浅层","中斜角肌后方","前斜角肌前方","斜角肌间隙","后斜角肌后方"],"a":3,"e":"臂丛由第5～8颈神经前支和第1胸神经前支大部分纤维组成，经斜角肌间隙向外侧穿出，再经锁骨后方进入腋窝。斜角肌间隙位于前、中斜角肌与第1肋之间。"},{"q":"支配眼轮匝肌的神经为","o":["动眼神经","眼神经","面神经","视神经","滑车神经"],"a":2,"e":"眼轮匝肌属面肌，由面神经的特殊内脏运动纤维支配，收缩时闭合眼裂。动眼神经支配眼球外肌及瞳孔括约肌等，不支配眼轮匝肌。"},{"q":"自脊髓骶部第2～4节段灰质的骶副交感核发出的纤维最终支配的器官为","o":["肾","空肠","横结肠","回肠","降结肠"],"a":4,"e":"骶副交感核位于脊髓S2～S4节段，节前纤维组成盆内脏神经，节后纤维支配结肠左曲以下的消化管及盆腔脏器，降结肠属此范围。空肠、回肠、横结肠由迷走神经支配。"},{"q":"椎骨的描述，正确的是","o":["所有颈椎棘突分叉","第6颈椎称隆椎","腰椎关节呈冠状位","腰椎棘突宽而短呈板状","胸椎椎体都有一完整肋凹"],"a":3,"e":"腰椎棘突宽短呈板状，水平伸向后方，各棘突间隙较宽，可于此行腰椎穿刺术。隆椎为第7颈椎，颈椎棘突并非全部分叉，胸椎下位椎体可无完整肋凹。"},{"q":"关于牙的说法，正确的是","o":["磨牙萌出晚，故又称迟牙或智牙","牙包括牙冠、牙颈、牙根和牙龈","牙内的腔隙称牙腔，牙腔内充满牙髓","牙周组织包括牙质、牙槽和牙周膜","牙由釉质和牙质构成"],"a":2,"e":"牙冠与牙颈内部的腔隙称牙冠腔，与牙根管合称牙腔，腔内充满牙髓，含丰富感觉神经末梢。牙由牙质、釉质、牙骨质和牙髓构成，牙周组织包括牙周膜、牙槽骨和牙龈。"},{"q":"椎前节不包括","o":["奇神经节","腹腔神经节","肠系膜上神经节","肠系膜下神经节","主动脉肾神经节"],"a":0,"e":"椎前节位于脊柱前方，包括腹腔神经节、主动脉肾神经节、肠系膜上神经节和肠系膜下神经节。奇神经节为两侧交感干下端在尾椎前方相连的椎旁神经节。"},{"q":"关于空肠特点的叙述，不正确的是","o":["血供丰富、颜色呈粉红色","空肠常位于左腰区和脐区","空肠系膜内动脉弓数多、直血管短","黏膜内主要有孤立淋巴滤泡","管径粗、壁厚"],"a":2,"e":"空肠动脉弓级数较少（1～2级），直血管较长；回肠动脉弓级数多（3～5级），直血管短。空肠管径粗、壁厚、血供丰富呈粉红色，黏膜内主要为环状襞和孤立淋巴滤泡。"},{"q":"迷走神经背核支配的器官不包括","o":["心","肾","直肠","小肠","横结肠"],"a":2,"e":"迷走神经背核发出的副交感节前纤维随迷走神经分布至颈、胸及腹腔大部分脏器，结肠左曲以下的消化管（含直肠）由骶副交感核支配。肾、心、小肠、横结肠均受迷走神经背核支配。"},{"q":"关于输尿管的描述，正确的是","o":["起于肾大盏终于膀胱","有两个弯曲","穿过尿生殖膈","沿腰大肌前面下降","肌层由骨骼肌构成"],"a":3,"e":"输尿管腹部起自肾盂下端，经腰大肌前面下行，至腰大肌中点附近走行于睾丸血管或卵巢血管后方。输尿管起于肾盂而非肾大盏，穿过盆膈而非尿生殖膈，肌层为平滑肌。"},{"q":"肱骨上端骨折的最易发部位是","o":["解剖颈","外科颈","肱骨干","肱骨下端","外侧髁"],"a":1,"e":"外科颈为肱骨头骨松质与肱骨干骨皮质交界处，骨质薄弱，是肱骨上端骨折的最易发部位。解剖颈为肩关节囊肱骨端附着处，非骨折好发部位。"},{"q":"下列哪个静脉是浅静脉","o":["肱静脉","股静脉","头静脉","尺静脉","桡静脉"],"a":2,"e":"头静脉起自手背静脉网桡侧，经三角肌胸大肌间沟上行注入腋静脉或锁骨下静脉，属上肢浅静脉。肱静脉、尺静脉、桡静脉、股静脉均与同名动脉伴行，属深静脉。"},{"q":"关于直肠的叙述，错误的是","o":["在第5腰椎高度续于乙状结肠","下段膨大为直肠壶腹","直肠指诊，男性可触及前列腺、精囊","直肠指诊，女性可触及或子宫和阴道","穿盆膈续于肛管"],"a":0,"e":"直肠在第3骶椎平面续于乙状结肠，而非第5腰椎高度。直肠下段膨大为直肠壶腹，穿盆膈续于肛管；直肠指诊男性可触及前列腺、精囊，女性可触及子宫和阴道。"},{"q":"支配臀大肌的神经是","o":["阴部神经","臀上神经","臀下神经","髂腹下神经","髂腹股沟神经"],"a":2,"e":"臀下神经经梨状肌下孔出盆腔，行于臀大肌深面并支配该肌。臀上神经支配臀中肌、臀小肌和阔筋膜张肌，不支配臀大肌。"},{"q":"下列结构中属于关节主要结构的是","o":["关节唇","关节盘","关节半月板","关节囊","滑膜囊"],"a":3,"e":"关节的主要结构包括关节面、关节囊和关节腔。关节唇、关节盘、关节半月板及滑膜囊均属关节的辅助结构。"},{"q":"关于肝门的描述，正确的是","o":["出肝门的是肝门静脉","入肝门的是肝左管","出肝门的是下腔静脉","入肝门的是肝固有动脉","出肝门的是静脉导管"],"a":3,"e":"肝门有肝左、右管，肝固有动脉左、右支，肝门静脉左、右支及神经、淋巴管出入；其中肝固有动脉入肝，肝左管、肝门静脉属出肝结构。下腔静脉不经过肝门。"},{"q":"下列何者不是颈外动脉的分支","o":["甲状腺上动脉","舌动脉","面动脉","椎动脉","枕动脉"],"a":3,"e":"颈外动脉分支包括甲状腺上动脉、舌动脉、面动脉和枕动脉。椎动脉起自锁骨下动脉，上行穿颈椎横突孔入颅，不属于颈外动脉分支。"},{"q":"在消化管壁上，由平滑肌增厚所形成的环行肌不包括","o":["贲门括约肌","肝胰壶腹括约肌","肛门外括约肌","肛门内括约肌","幽门括约肌"],"a":2,"e":"肛门外括约肌为骨骼肌，位于肛管平滑肌层之外，不属于消化管壁平滑肌增厚形成的括约肌。肛门内括约肌、贲门括约肌、幽门括约肌和肝胰壶腹括约肌均由平滑肌增厚构成。"},{"q":"延髓脑桥沟处有三对脑神经穿过，其中，最靠近中线的脑神经是","o":["三叉神经","展神经","面神经","前庭蜗神经","舌咽神经"],"a":1,"e":"延髓脑桥沟内自中线向外侧依次连有展神经、面神经和前庭蜗神经根，故最靠近中线的是展神经。三叉神经根连于脑桥基底部与小脑中脚交界处。"},{"q":"肾动脉的描述何者有误","o":["肾动脉直接起自腹主动脉","左肾动脉短","右肾动脉长","肾副动脉不经肾门入肾","右肾动脉经下腔静脉的前面至右肾"],"a":4,"e":"右肾动脉经下腔静脉后方至右肾，而非经其前面。左肾静脉较长并跨越腹主动脉前面，右肾静脉较短；肾副动脉可经肾下极入肾而不经肾门。"},{"q":"有关颈总动脉的描述，错误的是","o":["左侧起自主动脉弓","右侧起自头臂动脉","至舌骨大角平面分为颈内、颈外动脉","颈动脉结节是颈总动脉的压迫止血点","分叉处有颈动脉球"],"a":2,"e":"颈总动脉在甲状软骨上缘高度分为颈内动脉和颈外动脉，而非舌骨大角平面。左颈总动脉起自主动脉弓，右颈总动脉起自头臂干，颈动脉结节为压迫止血点。"},{"q":"包绕于肾和肾上腺周围的是","o":["肾筋膜前层","肾筋膜后层","肾纤维囊","肾脂肪囊","脏腹膜"],"a":3,"e":"脂肪囊又称肾床，位于纤维囊外周，紧密包裹肾和肾上腺，临床肾囊封闭即注入此囊。肾筋膜位于脂肪囊外面，纤维囊紧贴肾实质表面。"},{"q":"伸膝时，防止胫骨前移的结构是","o":["胫侧副韧带","腓侧副韧带","髌韧带","前交叉韧带","后交叉韧带"],"a":3,"e":"前交叉韧带起自胫骨髁间隆起前方，斜向后外上附着于股骨外侧髁，伸膝时最紧张，可防止胫骨前移。后交叉韧带在屈膝时紧张，防止胫骨后移。"},{"q":"不成对的脑颅骨是","o":["顶骨","蝶骨","颞骨","犁骨","下颌骨"],"a":1,"e":"脑颅骨中不成对的有额骨、筛骨、蝶骨和枕骨，成对的有颞骨和顶骨。犁骨和下颌骨属面颅骨，不参与构成脑颅。"},{"q":"胸膜下界在腋中线处相交于","o":["第8肋","第9肋","第10肋","第11肋","第12肋"],"a":2,"e":"胸膜下界在锁骨中线与第8肋相交，在腋中线与第10肋相交，在肩胛线与第11肋相交。肺下界较胸膜下界高两个肋，腋中线处为第8肋。"},{"q":"属于肋骨的结构是","o":["肋凹","横突肋凹","肋切迹","锁切迹","肋沟"],"a":4,"e":"肋沟为肋骨下缘内面的沟，容纳肋间血管和神经，属肋骨的结构。肋凹、横突肋凹位于胸椎，肋切迹位于胸骨，锁切迹为胸骨柄的关节面。"},{"q":"视觉传导通路的第2级神经元是","o":["视杆细胞","视锥细胞","双极细胞","神经节细胞","锥体细胞"],"a":3,"e":"视觉传导通路中，视锥细胞和视杆细胞为感受器，双极细胞为第1级神经元，节细胞为第2级神经元，其轴突汇集成视神经。"},{"q":"关于右淋巴导管的描述，正确的是","o":["亦称胸导管","长约30～40cm","注入右静脉角","收集上半身的淋巴","由右颈干和右锁骨下干合成"],"a":2,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，注入右静脉角。其长约1.0～1.5cm，仅收集右上肢、右胸部和右头颈部的淋巴。"},{"q":"收集下肢、盆部和腹部成对脏器的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":2,"e":"腰干由腰淋巴结输出淋巴管汇合而成，收集下肢、盆部及腹腔成对脏器的淋巴。肠干收集腹腔不成对脏器的淋巴。"},{"q":"和延髓锥体外侧相连的脑神经为","o":["动眼神经","展神经","滑车神经","舌下神经","迷走神经"],"a":3,"e":"舌下神经由舌下神经核发出，经延髓锥体与橄榄之间的前外侧沟出脑。动眼神经、滑车神经、展神经分别经中脑、中脑下丘下方、脑桥出脑。"},{"q":"关于腭的描述，错误的是","o":["硬腭由腭骨覆以黏膜而成","软腭的后缘游离","前2/3为硬腭，后1/3为软腭","腭是口腔的顶，分隔鼻腔与口腔","吞咽时，软腭上提可分隔鼻咽、口咽"],"a":0,"e":"硬腭由骨腭及表面覆盖的黏膜构成，骨腭由上颌骨腭突和腭骨水平板组成，并非仅由腭骨构成。软腭后缘游离，前2/3为硬腭、后1/3为软腭，腭分隔鼻腔与口腔。"},{"q":"下列关于子宫的描述，正确的是","o":["分为子宫底、子宫体及子宫颈管","下端的部分称为子宫底","底和体交界的部位称为子宫峡","子宫的内腔称为子宫腔","伸入阴道的部分称为子宫颈阴道部"],"a":4,"e":"子宫颈分为子宫颈阴道部和子宫颈阴道上部，突入阴道的部分即子宫颈阴道部。子宫分底、体、颈三部；底与体交界处为子宫体，非子宫峡；内腔包括子宫腔和子宫颈管。"},{"q":"锁骨下动脉的分支中没有","o":["椎动脉","甲状颈干","胸廓内动脉","肋颈干","甲状腺上动脉"],"a":4,"e":"甲状腺上动脉发自颈外动脉，不属于锁骨下动脉的分支。锁骨下动脉的分支包括椎动脉、胸廓内动脉、甲状颈干和肋颈干。"},{"q":"支配睫状肌的神经为","o":["眼神经","视神经","动眼神经","滑车神经","展神经"],"a":2,"e":"睫状肌由动眼神经的副交感纤维支配，节前纤维起自动眼神经副核，在睫状神经节换元后经睫状短神经分布于睫状肌，以调节晶状体曲度。"},{"q":"右心室","o":["参与心右缘的构成","有三入口一出口","入口周围有二尖瓣","出口周围有三尖瓣","构成心前面的大部分"],"a":4,"e":"右心室前壁构成胸肋面的大部分，故右心室参与构成心前面的大部分。右心室入口为右房室口，周围附三尖瓣；出口为肺动脉口，周围附肺动脉瓣。"},{"q":"属于下肢带骨的是","o":["股骨","胫骨","跗骨","髋骨","跖骨"],"a":3,"e":"髋骨由髂骨、坐骨和耻骨融合而成，属下肢带骨。股骨、胫骨、跗骨、跖骨均属自由下肢骨。"},{"q":"黄韧带连结的部位是","o":["相邻椎体之间","相邻椎弓根之间","相邻椎弓板之间","相邻横突之间","相邻棘突之间"],"a":2,"e":"黄韧带为连结相邻两椎弓板的韧带，由黄色弹性纤维构成，协助围成椎管并限制脊柱过度前屈。"},{"q":"下列属于颈内动脉直接分支的是","o":["椎动脉","脑膜中动脉","前交通动脉","大脑前动脉","大脑后动脉"],"a":3,"e":"大脑前动脉是颈内动脉的直接分支，在视神经上方行向前内进入大脑纵裂。前交通动脉连接两侧大脑前动脉，大脑后动脉来自基底动脉。"},{"q":"肝门静脉的属支不包括下列哪项","o":["胃左静脉","肠系膜上静脉","肠系膜下静脉","脾静脉","肾静脉"],"a":4,"e":"肾静脉直接注入下腔静脉，属下腔静脉系，不是肝门静脉的属支。肝门静脉的属支包括胃左静脉、肠系膜上静脉、肠系膜下静脉和脾静脉等。"},{"q":"颈丛位于","o":["颈阔肌浅层","颈阔肌深面","胸锁乳突肌上部深面","胸锁乳突肌下部深面","胸锁乳突肌上部浅层"],"a":2,"e":"颈丛由第1～4颈神经前支交织构成，位于胸锁乳突肌上部的深面、中斜角肌和肩胛提肌起始端的前方。"},{"q":"全身运动最灵活的关节是","o":["肩关节","肘关节","桡腕关节","髋关节","膝关节"],"a":0,"e":"肩关节是全身最灵活的关节，可作屈伸、收展、旋内旋外及环转三轴运动。其关节囊薄而松弛、关节盂浅，稳固性由周围肌肉韧带代偿。"},{"q":"关于气管的说法，错误的是","o":["有14～16个气管软骨环","气管杈的位置约平胸骨角平面","位于食管的前方","气管可分为颈、胸、腹三段","气管切开术常在第3～5气管软骨环处进行"],"a":3,"e":"气管仅分颈部和胸部两段，无腹部。气管软骨环14～16个，气管杈平胸骨角平面，位于食管前方，切开术常在第3～5软骨环处。"},{"q":"关于腰椎的正确说法是","o":["椎体粗壮，横切面呈三角形","椎孔呈圆形","各棘突的间隙较宽","上关节面是冠状位","上关节面呈水平位"],"a":2,"e":"腰椎棘突宽短呈板状、水平后伸，各棘突间隙较宽，临床可于此行腰椎穿刺术。腰椎椎体横切面呈肾形，椎孔呈卵圆形或三角形，关节面近矢状位。"},{"q":"关于胸廓内动脉的描述，何者正确","o":["发自锁骨下动脉上壁","行程中发出肋间后动脉","发自甲状颈干","发出腹壁上动脉","与腹壁下动脉无吻合"],"a":3,"e":"胸廓内动脉行至第6肋间隙发出腹壁上动脉和肌膈动脉两个终支，腹壁上动脉穿膈入腹直肌鞘，与腹壁下动脉吻合。该动脉发自锁骨下动脉下壁。"},{"q":"关于甲状软骨的描述，错误的是","o":["是喉软骨中最大的软骨","两甲状软骨板前缘相交形成前角","前角上端突出称喉结","上角与杓状软骨形成关节","下角与环状软骨形成关节"],"a":3,"e":"甲状软骨上角借韧带与舌骨大角相连，下角与环状软骨构成环甲关节。杓状软骨位于环状软骨板上缘，不与甲状软骨上角成关节。"},{"q":"下列关于脊髓的说法，错误的是","o":["位于椎管内，成人下端平第3腰椎下缘","全长有两个膨大，即颈膨大和腰骶膨大","全长有31个脊髓节段，连有31对脊神经","人胚早期，脊髓与椎管长度相等","表面无明显的节段性"],"a":0,"e":"成人脊髓下端平第1腰椎椎体下缘，而非第3腰椎下缘。脊髓全长有颈膨大和腰骶膨大，共31个节段连31对脊神经，胚胎早期与椎管等长。"},{"q":"关于网膜囊的描述，正确的是","o":["是仅位于小网膜与腹后壁之间扁窄的腹膜间隙","是仅位于胃与腹后壁之间扁窄的腹膜间隙","为腹膜腔的一部分，又称大腹膜腔","网膜囊以外的腹膜腔称为小腹膜腔","网膜孔是小腹膜腔与大腹膜腔之间的唯一通道"],"a":4,"e":"网膜囊为小腹膜腔，借网膜孔与其余腹膜腔（大腹膜腔）相交通，网膜孔是两者间唯一通道。网膜囊前壁包括小网膜、胃后壁腹膜和胃结肠韧带。"},{"q":"通过内囊膝的纤维束是","o":["皮质脊髓束","皮质核束","脊髓丘脑束","丘脑中央辐射","视辐射"],"a":1,"e":"内囊膝部通过皮质核束，由中央前回下部下行至脑干躯体运动核和特殊内脏运动核。皮质脊髓束、丘脑中央辐射位于内囊后肢，视辐射经豆状核下部。"},{"q":"股动脉在腹股沟深面的正确位置是","o":["在股神经的外侧","在股神经的内侧","在股静脉的内侧","在股静脉的后侧","在股静脉的前面"],"a":1,"e":"股动脉经腹股沟韧带中点稍内侧深面进入股三角，位于股神经内侧、股静脉外侧。股神经在腹股沟韧带中点稍外侧穿出，于股动脉外侧进入股三角。"},{"q":"关于结膜的叙述正确的是","o":["无血管","球结膜位于巩膜的后部","睑结膜位于上、下睑内面，与睑板紧密连接","结膜穹窿位于上睑结膜与下睑结膜之间","上睑与下睑闭合时，整个结膜形成的囊状腔隙为结膜穹窿"],"a":2,"e":"睑结膜衬覆于上、下睑内面，与睑板结合紧密。结膜富含血管；球结膜覆盖眼球前面；结膜穹窿为睑结膜与球结膜的移行处；结膜囊由整个结膜形成。"},{"q":"不属于股骨近端结构的是","o":["股骨颈","股骨头","小转子","大转子","粗线"],"a":4,"e":"粗线位于股骨体后面，属股骨干结构。股骨近端包括股骨头、股骨颈、大转子和小转子。"},{"q":"下列对阑尾的描述何者正确","o":["有系膜但不恒定","阑尾动脉通常有两支","常位于右髂窝腹膜外","McBurney点是阑尾根部的体表投影","阑尾静脉注入肠系膜下静脉"],"a":3,"e":"阑尾根部体表投影为右髂前上棘与脐连线中、外1/3交点，即McBurney点。阑尾动脉多为一支；阑尾多位于右髂窝腹膜内；阑尾静脉经回结肠静脉注入肠系膜上静脉。"},{"q":"小腿内侧面皮肤由什么神经支配","o":["闭孔神经","胫神经","腓浅神经","腓深神经","隐神经"],"a":4,"e":"隐神经为股神经最长皮支，伴股动脉入收肌管，与大隐静脉伴行沿小腿内侧面下行至足内侧缘，分布于小腿内侧面皮肤。"},{"q":"颈外动脉的描述中何者有误","o":["起始处行于颈内动脉的前内侧","继经颈内动脉的前方转至外侧","经二腹肌深方入腮腺实质","在下颌颈后方分为上颌动脉及颞浅动脉","起始处的膨大称颈动脉窦"],"a":4,"e":"颈动脉窦是颈总动脉末端与颈内动脉起始部的膨大，属颈内动脉起始处结构，而非颈外动脉起始处。颈外动脉起始处行于颈内动脉前内侧，后转至其外侧，经二腹肌深方入腮腺，于下颌颈后方分为上颌动脉和颞浅动脉。"},{"q":"关于输卵管的描述，正确的是","o":["直接与卵巢相通","壶腹部有伞附着","末端有漏斗","长7～8cm","位于盆腔中央"],"a":2,"e":"输卵管末端膨大为漏斗部，其末端有输卵管腹腔口。输卵管不直接与卵巢相通；伞附着于漏斗部而非壶腹部；输卵管长约10～14cm；位于子宫两侧。"},{"q":"输尿管与髂血管交叉处是在","o":["输尿管腹段","输尿管盆段","肾盂与输尿管移行处","越过小骨盆入口处","输尿管壁内段"],"a":3,"e":"输尿管经腰大肌前面下行，达小骨盆入口处越过髂血管前方，左侧越左髂总动脉末端，右侧越右髂外动脉起始部，此交叉处即输尿管盆部起始。"},{"q":"坐骨棘与髂后下棘之间的是","o":["坐骨大切迹","坐骨结节","髋臼切迹","坐骨小切迹","弓状线"],"a":0,"e":"坐骨棘与髂后下棘之间为坐骨大切迹。坐骨小切迹位于坐骨棘下方，两者以坐骨棘为界。"},{"q":"以下对牵涉性痛的描述错误的是","o":["因某些内脏器官发生病变在体表一定区域产生感觉过敏或痛觉的现象","海德带有助于内脏疾病的定位诊断","牵涉性痛均发生在患病内脏邻近的皮肤区","肝胆疾患时常在右肩部感到疼痛","心绞痛时常在胸前区及左臂内侧皮肤感到疼痛"],"a":2,"e":"牵涉性痛既可发生在患病脏器邻近皮肤区，也可发生在距患病脏器较远的皮肤区。其机制是病变器官与体表部位的感觉神经进入同一脊髓节段并在后角内密切联系。"},{"q":"关于颈外静脉，下列描述中正确的是","o":["属于深静脉","注入颈内静脉","与同名动脉伴行","注入锁骨下静脉或静脉角","起自面静脉"],"a":3,"e":"颈外静脉由下颌后静脉后支、耳后静脉和枕静脉在下颌角处汇合而成，沿胸锁乳突肌表面下行，注入锁骨下静脉或静脉角。"},{"q":"确认输卵管的标志是","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":4,"e":"输卵管伞是输卵管腹腔口边缘的细长突起，盖于卵巢表面，是手术中确认输卵管的标志。输卵管壶腹为受精部位，峡为结扎部位。"},{"q":"关于肾的描述，正确的是","o":["左、右肾上端等高","出入肾门的结构被纤维囊包绕","右肾比左肾略低半个椎体","第12肋斜过右肾后面的下部","在肾门处肾小盏移行为肾大盏"],"a":2,"e":"左肾位于第11胸椎下缘至第2～3腰椎椎间盘之间，右肾位于第12胸椎上缘至第3腰椎上缘之间，右肾比左肾略低半个椎体。第12肋斜过右肾后面上部。"},{"q":"以人体正中矢状面为准的方位术语是","o":["内、外","内侧、外侧","近侧、远侧","深、浅","近端、远端"],"a":1,"e":"内侧和外侧是描述结构距人体正中矢状面相对远近的术语，近者为内侧，远者为外侧。内、外则描述体腔或空腔器官的相互位置关系。"},{"q":"后丘脑的主要功能是","o":["视、听觉传导路的中继站","痛、温觉传导路的中继站","本体感觉传导路的中继站","内分泌调节","随意运动调节"],"a":0,"e":"后丘脑包括内侧膝状体和外侧膝状体，分别是听觉传导通路和视觉传导通路在丘脑的中继站，发出听辐射和视辐射投射至大脑皮质。"},{"q":"关于上腔静脉，下列描述中正确的是","o":["由左、右头臂静脉汇合而成","注入左心房","在入心之前接受无名静脉注入","沿升主动脉前面垂直下行","收集胸腔内心脏的静脉血"],"a":0,"e":"上腔静脉由左、右头臂静脉在右侧第1胸肋结合处后方汇合而成，沿升主动脉右侧下行，注入右心房。"},{"q":"与颈内静脉伴行的血管是","o":["颈外静脉","上颌静脉","颈外动脉","下颌后静脉","颈总动脉"],"a":4,"e":"颈内静脉在颈动脉鞘内沿颈内动脉和颈总动脉外侧下行，故与颈总动脉伴行。颈外静脉为浅静脉，位于胸锁乳突肌表面。"},{"q":"在脑桥基底部和小脑中脚交界处连接的神经为","o":["三叉神经","展神经","面神经","动眼神经","滑车神经"],"a":0,"e":"三叉神经根连于脑桥基底部与小脑中脚交界处，其中粗大的感觉根入脑、细小的运动根出脑。展神经、面神经和前庭蜗神经根连于延髓脑桥沟。"},{"q":"关于小腿肌前群的描述，正确的是","o":["包括胫骨前肌、趾长伸肌和腓骨长肌","趾长伸肌位于胫骨前肌和拇长伸肌之间","均能屈距小腿关节","胫骨前肌还能使足外翻","均能使足背屈"],"a":4,"e":"小腿肌前群包括胫骨前肌、长伸肌和趾长伸肌，三肌均能伸踝关节即足背屈。腓骨长肌属外侧群，胫骨前肌使足内翻而非外翻。"},{"q":"躯干和四肢意识性本体感觉传导通路的第1级神经元是","o":["脊神经节","三叉神经节","脊髓后角细胞","薄束核和楔束核","三叉神经脊束核"],"a":0,"e":"躯干和四肢意识性本体感觉传导通路第1级神经元为脊神经节内假单极神经元，中枢突经脊神经后根入脊髓后索。薄束核和楔束核为第2级神经元。"}];
